window.ETSDATA=window.ETSDATA||{};window.ETSDATA[15]={"lc":{"p1":[{"n":1,"opts":["The worker is carrying some plants.","The worker is reading a sign.","The worker is pushing a cart.","The worker is writing some notes."],"vi":["Người công nhân đang mang một số cây.","Người công nhân đang đọc một tấm biển.","Người công nhân đang đẩy một chiếc xe đẩy.","Người công nhân đang ghi chép."],"ans":"D","xp":"Ảnh một người: người công nhân đang cầm giấy bút ghi chép (writing some notes) → chọn (D).\n(A) không mang cây, (B) không đọc biển, (C) không đẩy xe — sai hành động.","a":"E24-T05-01.mp3","img":"q1.jpg"},{"n":2,"opts":["Some of the people are pulling suitcases.","Some of the people are relaxing on benches.","Some of the people are putting luggage onto a rack.","Some of the people are waiting in line to purchase a ticket."],"vi":["Một vài người đang kéo vali.","Một vài người đang nghỉ ngơi trên ghế băng.","Một vài người đang đặt hành lý lên giá.","Một vài người đang xếp hàng để mua vé."],"ans":"A","xp":"Ảnh nhiều người: một vài người đang kéo vali (pulling suitcases) → chọn (A).\n(B) không ai ngồi nghỉ trên ghế, (C) trong ảnh không có giá để hành lý (rack), (D) không ai xếp hàng mua vé.","a":"E24-T05-02.mp3","img":"q2.jpg"},{"n":3,"opts":["She's looking into her backpack.","She's tying the laces of her boots.","She's hiking on an outdoor path.","She's walking out of a tunnel."],"vi":["Cô ấy đang nhìn vào trong ba lô.","Cô ấy đang buộc dây giày bốt.","Cô ấy đang đi bộ đường dài trên một con đường ngoài trời.","Cô ấy đang đi ra khỏi một đường hầm."],"ans":"C","xp":"Người phụ nữ đang đi bộ trên con đường mòn ngoài trời (hiking on an outdoor path) → chọn (C).\n(A), (B) sai hành động; (D) trong ảnh không có đường hầm (tunnel).","a":"E24-T05-03.mp3","img":"q3.jpg"},{"n":4,"opts":["He's holding the handle of a shopping cart.","He's plugging a cord into a wall outlet.","He's looking into a kitchen cupboard.","He's kneeling down on a tile floor."],"vi":["Anh ấy đang cầm tay nắm của một xe đẩy mua sắm.","Anh ấy đang cắm dây điện vào ổ cắm trên tường.","Anh ấy đang nhìn vào tủ bếp.","Anh ấy đang quỳ trên sàn lát gạch."],"ans":"D","xp":"Người đàn ông đang quỳ gối (kneeling down) trên sàn lát gạch → chọn (D).\n(A) không có xe đẩy, (B) không có ổ cắm tường, (C) anh ấy không nhìn vào tủ bếp.","a":"E24-T05-04.mp3","img":"q4.jpg"},{"n":5,"opts":["Seats have been arranged under some umbrellas.","Some street signs are being taken down.","Some bushes are being trimmed.","Some chairs are being folded and stacked."],"vi":["Ghế ngồi đã được sắp xếp dưới mấy chiếc dù che.","Một số biển báo đường phố đang được tháo xuống.","Một số bụi cây đang được cắt tỉa.","Một số ghế đang được gấp lại và xếp chồng lên."],"ans":"A","xp":"Ảnh cảnh vật: ghế được bày sẵn dưới những chiếc dù che nắng (have been arranged under some umbrellas) → chọn (A).\n(B) không có biển báo đường phố; (C), (D) dùng 'are being + V3' (đang được làm) nhưng không có ai đang cắt tỉa cây hay gấp ghế.","a":"E24-T05-05.mp3","img":"q5.jpg"},{"n":6,"opts":["Some cushions have been laid on the floor.","Books have been piled up by a glass door.","A light fixture is suspended from the ceiling.","A rug has been rolled up against a wall."],"vi":["Một số chiếc đệm đã được đặt trên sàn.","Sách đã được chất chồng cạnh một cửa kính.","Một chiếc đèn được treo từ trần nhà.","Một tấm thảm đã được cuộn lại dựa vào tường."],"ans":"B","xp":"Sách được chất thành chồng (have been piled up) cạnh cửa kính → chọn (B).\n(A) đệm nằm trên ghế chứ không phải trên sàn; (C) không thấy đèn treo trên trần; (D) tấm thảm không bị cuộn lại.","a":"E24-T05-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"There's a meeting in the conference room soon, right?","qvi":"Sắp có một cuộc họp ở phòng hội nghị, phải không?","opts":["Yes, it's for the whole department.","No, put it in the closet.","The rent is too high."],"vi":["Vâng, cuộc họp dành cho cả phòng ban.","Không, hãy để nó vào tủ.","Tiền thuê quá cao."],"ans":"A","xp":"Câu hỏi đuôi xác nhận có cuộc họp. (A) trả lời 'Yes' rồi bổ sung thông tin liên quan (họp cho cả phòng ban) → đúng.\n(B) 'closet' (tủ) và (C) 'rent' (tiền thuê) là bẫy liên tưởng từ 'room'.","a":"E24-T05-07.mp3"},{"n":8,"q":"Why hasn't the mural in the lobby been painted yet?","qvi":"Tại sao bức tranh tường ở sảnh vẫn chưa được vẽ?","opts":["Red and yellow.","Please pick up the ladder.","Because the artist is out of town."],"vi":["Đỏ và vàng.","Làm ơn nhấc cái thang lên.","Vì người họa sĩ đang đi vắng (ra khỏi thành phố)."],"ans":"C","xp":"Câu hỏi Why hỏi lý do. (C) đưa ra lý do cụ thể: họa sĩ đang đi xa → đúng.\n(A) màu sắc và (B) cái thang (ladder) là bẫy liên tưởng từ 'painted'.","a":"E24-T05-08.mp3"},{"n":9,"q":"Do you prefer writing in the morning or the afternoon?","qvi":"Bạn thích viết vào buổi sáng hay buổi chiều hơn?","opts":["My publisher requested edits.","Thanks for providing a solution.","Mornings are usually better for me."],"vi":["Nhà xuất bản của tôi yêu cầu chỉnh sửa.","Cảm ơn vì đã đưa ra giải pháp.","Buổi sáng thường tốt hơn với tôi."],"ans":"C","xp":"Câu hỏi lựa chọn (sáng hay chiều). (C) chọn buổi sáng → đúng.\n(A) 'publisher', 'edits' là bẫy liên tưởng từ 'writing'; (B) không liên quan.","a":"E24-T05-09.mp3"},{"n":10,"q":"I suggest we paint the waiting room light blue.","qvi":"Tôi đề nghị chúng ta sơn phòng chờ màu xanh da trời nhạt.","opts":["Doctor Park has an opening at three.","That's a good idea.","I prefer the red jacket."],"vi":["Bác sĩ Park có lịch trống lúc ba giờ.","Đó là một ý hay.","Tôi thích chiếc áo khoác đỏ hơn."],"ans":"B","xp":"Câu đề nghị (I suggest...). (B) đồng ý: 'Ý hay đấy' → đúng.\n(A) không liên quan (bẫy liên tưởng 'waiting room' – phòng khám); (C) 'red' là bẫy liên tưởng từ màu 'blue'.","a":"E24-T05-10.mp3"},{"n":11,"q":"Did you know that the music school is closed on Sundays?","qvi":"Bạn có biết trường nhạc đóng cửa vào Chủ nhật không?","opts":["Forty dollars an hour.","No, I didn't know that.","I saw the piano recital."],"vi":["Bốn mươi đô la một giờ.","Không, tôi không biết điều đó.","Tôi đã xem buổi biểu diễn piano."],"ans":"B","xp":"Câu hỏi Yes/No 'Did you know...?'. (B) trả lời 'No' và nói mình không biết → đúng.\n(A) trả lời cho câu hỏi giá (How much); (C) 'piano recital' là bẫy liên tưởng từ 'music school'.","a":"E24-T05-11.mp3"},{"n":12,"q":"How do I find the office manager?","qvi":"Làm thế nào để tôi gặp được quản lý văn phòng?","opts":["The receptionist would know.","Desk lamps and headsets.","Twelve euros."],"vi":["Nhân viên lễ tân sẽ biết.","Đèn bàn và tai nghe.","Mười hai euro."],"ans":"A","xp":"Câu hỏi How hỏi cách tìm quản lý. (A) chỉ người có thể giúp: lễ tân sẽ biết → đúng.\n(B) 'desk lamps' là bẫy liên tưởng từ 'office'; (C) trả lời cho How much.","a":"E24-T05-12.mp3"},{"n":13,"q":"When did you place the order for the lumber?","qvi":"Bạn đã đặt hàng gỗ xẻ khi nào?","opts":["Yes, it's a great place for hiking.","It's out of stock right now.","The warehouse on William Street."],"vi":["Vâng, đó là một nơi tuyệt vời để đi bộ đường dài.","Hiện tại nó đang hết hàng.","Nhà kho trên phố William."],"ans":"B","xp":"Câu hỏi When. (B) trả lời gián tiếp: gỗ đang hết hàng nên chưa đặt được → đúng.\n(A) câu hỏi When không trả lời bằng Yes/No (và 'place' là bẫy lặp từ); (C) trả lời cho câu hỏi Where.","a":"E24-T05-13.mp3"},{"n":14,"q":"Where is the new packaging machine?","qvi":"Máy đóng gói mới ở đâu?","opts":["Ten packages a minute.","We met last Thursday.","We decided to keep the old one."],"vi":["Mười kiện hàng mỗi phút.","Chúng ta đã gặp nhau thứ Năm tuần trước.","Chúng tôi đã quyết định giữ lại cái máy cũ."],"ans":"C","xp":"Câu hỏi Where. (C) trả lời gián tiếp: đã quyết định giữ máy cũ → không có máy mới → đúng.\n(A) 'packages' là bẫy âm giống 'packaging'; (B) không liên quan.","a":"E24-T05-14.mp3"},{"n":15,"q":"I'll be out of the office this afternoon.","qvi":"Chiều nay tôi sẽ không có mặt ở văn phòng.","opts":["An awfully long commute.","OK—I'll update your schedule.","It's right down the hallway."],"vi":["Một quãng đường đi làm dài kinh khủng.","Được—tôi sẽ cập nhật lịch làm việc của bạn.","Nó ở ngay cuối hành lang."],"ans":"B","xp":"Câu trần thuật báo tin vắng mặt. (B) đáp 'OK' và nói sẽ cập nhật lịch → phản hồi hợp lý.\n(A) 'commute' và (C) 'hallway' là bẫy liên tưởng từ 'office'.","a":"E24-T05-15.mp3"},{"n":16,"q":"Are you taking a vacation once this project is over?","qvi":"Bạn có đi nghỉ phép khi dự án này kết thúc không?","opts":["Yes—I'm planning a trip to Barcelona.","This is your second time, isn't it?","Blueprints for a high-rise building."],"vi":["Có—tôi đang lên kế hoạch đi Barcelona.","Đây là lần thứ hai của bạn, phải không?","Bản thiết kế cho một tòa nhà cao tầng."],"ans":"A","xp":"Câu hỏi Yes/No về kế hoạch nghỉ phép. (A) 'Yes' + sẽ đi Barcelona → đúng.\n(B) 'second time' là bẫy liên tưởng từ 'once'; (C) 'blueprints' là bẫy liên tưởng từ 'project'.","a":"E24-T05-16.mp3"},{"n":17,"q":"Let's post the sales report to our team's Web page.","qvi":"Chúng ta hãy đăng báo cáo doanh số lên trang web của nhóm nhé.","opts":["We're sharing a taxi to the airport.","I can do that.","A recent hiring decision."],"vi":["Chúng tôi đi chung taxi ra sân bay.","Tôi có thể làm việc đó.","Một quyết định tuyển dụng gần đây."],"ans":"B","xp":"Câu đề nghị 'Let's...'. (B) nhận làm việc đó → đúng.\n(A), (C) không liên quan đến việc đăng báo cáo.","a":"E24-T05-17.mp3"},{"n":18,"q":"Which airline are you planning on using?","qvi":"Bạn định đi hãng hàng không nào?","opts":["The usual one.","A one-way ticket.","Yes, you can use mine."],"vi":["Hãng tôi vẫn thường đi.","Một vé một chiều.","Vâng, bạn có thể dùng cái của tôi."],"ans":"A","xp":"Câu hỏi Which (hãng nào). (A) 'the usual one' = hãng quen thuộc → đúng. Mẹo: câu hỏi Which thường có đáp án dạng 'the ... one'.\n(B) 'one-way ticket' là bẫy liên tưởng từ 'airline'; (C) câu hỏi Which không trả lời bằng Yes/No.","a":"E24-T05-18.mp3"},{"n":19,"q":"Where's this shipment of parts being sent?","qvi":"Lô hàng linh kiện này được gửi đi đâu?","opts":["Around five thirty this evening.","To the assembly plant in Dublin.","Just half the order."],"vi":["Khoảng 5 giờ 30 tối nay.","Đến nhà máy lắp ráp ở Dublin.","Chỉ một nửa đơn hàng."],"ans":"B","xp":"Câu hỏi Where. (B) nêu địa điểm cụ thể: nhà máy lắp ráp ở Dublin → đúng.\n(A) trả lời cho When; (C) 'order' là bẫy liên tưởng từ 'shipment'.","a":"E24-T05-19.mp3"},{"n":20,"q":"Who paid for lunch?","qvi":"Ai đã trả tiền bữa trưa?","opts":["I just ate.","It closes at five.","Alberto did."],"vi":["Tôi vừa ăn xong.","Nó đóng cửa lúc năm giờ.","Alberto đã trả."],"ans":"C","xp":"Câu hỏi Who → cần tên người. (C) 'Alberto did' → đúng.\n(A) 'ate' là bẫy liên tưởng từ 'lunch'; (B) không liên quan.","a":"E24-T05-20.mp3"},{"n":21,"q":"How many employees work in your department?","qvi":"Có bao nhiêu nhân viên làm việc trong phòng ban của bạn?","opts":["I don't mind taking notes at the meeting.","A couple dozen, I think.","It's seven meters long."],"vi":["Tôi không ngại ghi chép trong cuộc họp.","Khoảng hai chục người, tôi nghĩ vậy.","Nó dài bảy mét."],"ans":"B","xp":"Câu hỏi How many hỏi số lượng. (B) 'a couple dozen' (khoảng 24) → đúng.\n(A) 'meeting' là bẫy liên tưởng từ 'department'; (C) có con số nhưng là chiều dài, không phải số người.","a":"E24-T05-21.mp3"},{"n":22,"q":"We should leave for our training course soon, shouldn't we?","qvi":"Chúng ta nên sớm xuất phát đến khóa đào tạo, phải không?","opts":["We still have a few minutes.","There's a map on the wall.","Two sessions per day."],"vi":["Chúng ta vẫn còn vài phút.","Có một tấm bản đồ trên tường.","Hai buổi học mỗi ngày."],"ans":"A","xp":"Câu hỏi đuôi. (A) trả lời gián tiếp: vẫn còn vài phút, chưa cần đi ngay → đúng.\n(B) không liên quan; (C) 'sessions' là bẫy liên tưởng từ 'training course'.","a":"E24-T05-22.mp3"},{"n":23,"q":"Isn't there a limit on travel expenses?","qvi":"Chẳng phải có giới hạn cho chi phí công tác sao?","opts":["To fix the vending machine.","One hundred dollars per day.","Next to the travel agency."],"vi":["Để sửa máy bán hàng tự động.","Một trăm đô la mỗi ngày.","Bên cạnh công ty du lịch."],"ans":"B","xp":"Câu hỏi phủ định xác nhận có giới hạn chi phí. (B) nêu luôn mức giới hạn 100 đô/ngày (ngầm hiểu 'Yes') → đúng.\n(A) trả lời cho Why; (C) lặp từ 'travel' gây bẫy.","a":"E24-T05-23.mp3"},{"n":24,"q":"When should I tell the director that I'm interested in the management position?","qvi":"Khi nào tôi nên nói với giám đốc rằng tôi quan tâm đến vị trí quản lý?","opts":["Yes, we're extending our business hours.","Didn't Andrey direct the play?","I'm not on the hiring team."],"vi":["Vâng, chúng tôi đang kéo dài giờ làm việc.","Không phải Andrey đạo diễn vở kịch sao?","Tôi không ở trong nhóm tuyển dụng."],"ans":"C","xp":"Câu hỏi When. (C) trả lời gián tiếp: tôi không thuộc nhóm tuyển dụng (nên không biết) → đúng.\n(A) câu hỏi When không trả lời Yes/No; (B) 'direct' là bẫy từ cùng gốc với 'director'.","a":"E24-T05-24.mp3"},{"n":25,"q":"The layout of the footwear department has changed.","qvi":"Cách bố trí của khu giày dép đã thay đổi.","opts":["There's a charging station in the café.","Yes, a three-bedroom apartment.","The store has a new manager."],"vi":["Có một trạm sạc trong quán cà phê.","Vâng, một căn hộ ba phòng ngủ.","Cửa hàng có quản lý mới."],"ans":"C","xp":"Câu trần thuật. (C) giải thích lý do bố trí thay đổi: cửa hàng có quản lý mới → đúng.\n(A) không liên quan; (B) 'apartment' là bẫy âm giống 'department'.","a":"E24-T05-25.mp3"},{"n":26,"q":"Can you look at this month's revenue report?","qvi":"Bạn có thể xem qua báo cáo doanh thu tháng này không?","opts":["The news program is informative.","I have some free time tomorrow afternoon.","He started that position in July."],"vi":["Chương trình thời sự rất bổ ích.","Chiều mai tôi có chút thời gian rảnh.","Anh ấy bắt đầu đảm nhận vị trí đó vào tháng Bảy."],"ans":"B","xp":"Câu yêu cầu 'Can you...?'. (B) trả lời gián tiếp: chiều mai rảnh → có thể xem lúc đó → đúng.\n(A) 'news' là bẫy liên tưởng từ 'report'; (C) 'He' không rõ chỉ ai.","a":"E24-T05-26.mp3"},{"n":27,"q":"Why haven't the windows been replaced yet?","qvi":"Tại sao các cửa sổ vẫn chưa được thay?","opts":["Not too much wind, no.","Look in the filing cabinet.","Did you see the cost estimate?"],"vi":["Không có gió nhiều lắm, không.","Hãy tìm trong tủ hồ sơ.","Bạn đã xem bản dự toán chi phí chưa?"],"ans":"C","xp":"Câu hỏi Why. (C) trả lời gián tiếp bằng câu hỏi ngược lại: bạn đã xem bản báo giá chưa? → ngụ ý chi phí quá cao nên chưa thay → đúng.\n(A) 'wind' là bẫy âm giống 'windows'; (B) không liên quan.","a":"E24-T05-27.mp3"},{"n":28,"q":"Isn't your suitcase going to be heavier than the permitted weight?","qvi":"Chẳng phải vali của bạn sẽ nặng hơn trọng lượng cho phép sao?","opts":["The building permit arrived today.","There are seats in the lobby.","I'll have to pay a little bit extra."],"vi":["Giấy phép xây dựng đã đến hôm nay.","Có ghế ngồi ở sảnh.","Tôi sẽ phải trả thêm một chút tiền."],"ans":"C","xp":"Câu hỏi phủ định xác nhận vali quá cân. (C) trả lời gián tiếp: sẽ phải trả thêm tiền → tức là đúng là quá cân → đúng.\n(A) 'permit' là bẫy từ cùng gốc với 'permitted'; (B) không liên quan.","a":"E24-T05-28.mp3"},{"n":29,"q":"Who manufactures the engines for our machines?","qvi":"Ai sản xuất động cơ cho máy móc của chúng ta?","opts":["Koji is in charge of supplier contracts.","I'm sorry—the storage room is full.","That's a cargo airplane."],"vi":["Koji phụ trách các hợp đồng với nhà cung cấp.","Xin lỗi—phòng kho đầy rồi.","Đó là một máy bay chở hàng."],"ans":"A","xp":"Câu hỏi Who. (A) chỉ ra người có thể biết thông tin: Koji phụ trách hợp đồng nhà cung cấp → đúng.\n(B) không liên quan; (C) 'airplane' là bẫy liên tưởng từ 'engines'.","a":"E24-T05-29.mp3"},{"n":30,"q":"Should we meet at the department store on Fifth Street or the one on Grover Lane?","qvi":"Chúng ta nên gặp nhau ở cửa hàng bách hóa trên phố Fifth hay cửa hàng trên đường Grover?","opts":["Let's ask Patricia first.","No, I don't mind.","How much does it cost?"],"vi":["Hãy hỏi Patricia trước đã.","Không, tôi không phiền đâu.","Nó giá bao nhiêu?"],"ans":"A","xp":"Câu hỏi lựa chọn địa điểm. (A) không chọn mà đề nghị hỏi ý Patricia trước → câu trả lời 'người thứ ba' hợp lý → đúng.\n(B) câu hỏi lựa chọn không trả lời Yes/No; (C) 'cost' là bẫy liên tưởng từ 'department store'.","a":"E24-T05-30.mp3"},{"n":31,"q":"Which band is playing at the club tonight?","qvi":"Ban nhạc nào sẽ biểu diễn ở câu lạc bộ tối nay?","opts":["There's always a comedy show on Thursday nights.","Yes, I've played the piano for many years.","Their number one hit."],"vi":["Tối thứ Năm nào cũng có một buổi diễn hài.","Vâng, tôi đã chơi piano nhiều năm rồi.","Bài hát ăn khách nhất của họ."],"ans":"A","xp":"Câu hỏi Which. (A) trả lời gián tiếp: tối thứ Năm luôn có diễn hài → tối nay không có ban nhạc → đúng.\n(B) câu hỏi Which không trả lời Yes/No; (C) 'number one hit' là bẫy liên tưởng từ 'band'.","a":"E24-T05-31.mp3"}],"p3":[{"ns":[32,34],"script":[["W","Hi, Shenchao. I'm practicing my presentation in the conference room across the hall, and the projector in there keeps shutting off. I think it's overheating. Has this happened to you?","Chào Shenchao. Tôi đang tập thuyết trình ở phòng hội nghị bên kia hành lang, và cái máy chiếu trong đó cứ tự tắt liên tục. Tôi nghĩ nó bị quá nóng. Bạn đã gặp chuyện này chưa?"],["M","Oh, that projector is old. It really needs to be replaced. If I were you, I'd just move to room 204 and practice there. Also, that room has a window. It's much nicer.","À, cái máy chiếu đó cũ rồi. Thật sự cần phải thay. Nếu tôi là bạn, tôi sẽ chuyển sang phòng 204 và tập ở đó. Hơn nữa, phòng đó có cửa sổ. Dễ chịu hơn nhiều."],["W","OK. Thanks.","Được. Cảm ơn bạn."],["M","By the way, you'll need a special cable to connect to the control panel in that room. Here, you can use this one. Just leave it plugged in when you're finished.","Nhân tiện, bạn sẽ cần một sợi cáp đặc biệt để kết nối với bảng điều khiển trong phòng đó. Đây, bạn có thể dùng sợi này. Dùng xong cứ để nó cắm ở đó nhé."]],"qs":[{"n":32,"q":"What problem does the woman describe?","qvi":"Người phụ nữ mô tả vấn đề gì?","opts":["A room is not available.","A window will not open.","A projector is not working.","The weather has changed suddenly."],"vi":["Một căn phòng không sử dụng được.","Một cửa sổ không mở được.","Một máy chiếu không hoạt động.","Thời tiết thay đổi đột ngột."],"ans":"C","xp":"Người phụ nữ nói: \"the projector in there keeps shutting off\" (máy chiếu cứ tự tắt liên tục).\n'keeps shutting off' được diễn đạt lại thành 'is not working' (không hoạt động) → (C)."},{"n":33,"q":"What does the man suggest doing?","qvi":"Người đàn ông gợi ý làm gì?","opts":["Moving to a different room","Calling a technician","Canceling an event","Ordering some supplies"],"vi":["Chuyển sang một phòng khác","Gọi kỹ thuật viên","Hủy một sự kiện","Đặt mua một số vật dụng"],"ans":"A","xp":"Người đàn ông nói: \"If I were you, I'd just move to room 204 and practice there.\" (Nếu là bạn, tôi sẽ chuyển sang phòng 204).\n'move to room 204' = 'Moving to a different room' → (A)."},{"n":34,"q":"What does the man hand to the woman?","qvi":"Người đàn ông đưa cho người phụ nữ cái gì?","opts":["An umbrella","Some keys","A cable","Some printouts"],"vi":["Một cái ô","Mấy chiếc chìa khóa","Một sợi cáp","Một số bản in"],"ans":"C","xp":"Cuối đoạn, người đàn ông nói: \"you'll need a special cable to connect to the control panel... Here, you can use this one.\" (bạn cần một sợi cáp đặc biệt... Đây, dùng sợi này) → anh ấy đưa cho cô một sợi cáp → (C)."}],"a":"E24-T05-32-34.mp3"},{"ns":[35,37],"script":[["W","Hi. I'm Amanda Hoffman, and I'm on the panel of publishing experts. I was told to check in here at the registration desk.","Xin chào. Tôi là Amanda Hoffman, tôi nằm trong nhóm chuyên gia xuất bản tham gia tọa đàm. Tôi được bảo là làm thủ tục ở quầy đăng ký này."],["M","Yes, Ms. Hoffman. Welcome to the Portland Literary Conference. Here's your registration packet, which includes a gift card to thank you for participating.","Vâng, thưa cô Hoffman. Chào mừng cô đến với Hội nghị Văn học Portland. Đây là bộ tài liệu đăng ký của cô, trong đó có một thẻ quà tặng để cảm ơn cô đã tham gia."],["W","Oh, thank you. Just to confirm, the panel discussion begins at three P.M., right?","Ồ, cảm ơn anh. Cho tôi xác nhận lại, buổi tọa đàm bắt đầu lúc 3 giờ chiều, đúng không?"],["M","Yes, but we do ask that all panel members arrive ten minutes beforehand. I hope you enjoy the conference!","Đúng vậy, nhưng chúng tôi đề nghị tất cả thành viên tọa đàm đến trước mười phút. Chúc cô tận hưởng hội nghị!"]],"qs":[{"n":35,"q":"What industry does Amanda Hoffman work in?","qvi":"Amanda Hoffman làm việc trong ngành nào?","opts":["Hospitality","Healthcare","Publishing","Information technology"],"vi":["Dịch vụ khách sạn – nhà hàng","Y tế","Xuất bản","Công nghệ thông tin"],"ans":"C","xp":"Người phụ nữ tự giới thiệu: \"I'm Amanda Hoffman, and I'm on the panel of publishing experts.\" (tôi thuộc nhóm chuyên gia xuất bản) → cô làm trong ngành xuất bản → (C)."},{"n":36,"q":"According to the man, what is included in the registration packet?","qvi":"Theo người đàn ông, bộ tài liệu đăng ký có gì?","opts":["A map","A gift card","A schedule of events","A certificate of attendance"],"vi":["Một tấm bản đồ","Một thẻ quà tặng","Lịch trình các sự kiện","Giấy chứng nhận tham dự"],"ans":"B","xp":"Người đàn ông nói: \"Here's your registration packet, which includes a gift card to thank you for participating.\" → trong bộ tài liệu có thẻ quà tặng → (B)."},{"n":37,"q":"What does the man tell the woman to do?","qvi":"Người đàn ông bảo người phụ nữ làm gì?","opts":["Arrive early","Pay a fee","Wear a name badge","Choose a menu option"],"vi":["Đến sớm","Trả phí","Đeo thẻ tên","Chọn một món trong thực đơn"],"ans":"A","xp":"Người đàn ông nói: \"we do ask that all panel members arrive ten minutes beforehand\" (đề nghị thành viên tọa đàm đến trước 10 phút).\n'arrive ten minutes beforehand' = 'Arrive early' → (A)."}],"a":"E24-T05-35-37.mp3"},{"ns":[38,40],"script":[["W","I'm looking for a gift for my brother's birthday party this weekend. He loves teas, and you have so many varieties!","Tôi đang tìm quà cho tiệc sinh nhật em trai tôi vào cuối tuần này. Em ấy rất thích trà, mà cửa hàng anh có nhiều loại quá!"],["M","Well, I could recommend a quality brand if you know what type he enjoys.","Nếu chị biết em ấy thích loại nào, tôi có thể giới thiệu một thương hiệu chất lượng."],["W","Oh, I'm not sure. Hmm. Maybe I should get him a gift card so he can choose his own.","Ồ, tôi không chắc lắm. Hừm. Có lẽ tôi nên mua cho em ấy một thẻ quà tặng để em ấy tự chọn."],["M","That's a good idea.","Ý hay đấy."],["W","I'll get one for 50 dollars. Do your cards have an expiration date?","Tôi sẽ lấy một thẻ 50 đô la. Thẻ của cửa hàng có hạn sử dụng không?"],["M","Yes. We ask that they be used within one year of purchase.","Có. Thẻ cần được sử dụng trong vòng một năm kể từ ngày mua."]],"qs":[{"n":38,"q":"What event will the woman attend this weekend?","qvi":"Cuối tuần này người phụ nữ sẽ tham dự sự kiện gì?","opts":["A wedding","A birthday party","A retirement dinner","A graduation celebration"],"vi":["Một đám cưới","Một bữa tiệc sinh nhật","Một bữa tối mừng nghỉ hưu","Một buổi mừng tốt nghiệp"],"ans":"B","xp":"Người phụ nữ nói: \"I'm looking for a gift for my brother's birthday party this weekend.\" → cô sẽ dự tiệc sinh nhật em trai → (B)."},{"n":39,"q":"What does the man offer to do?","qvi":"Người đàn ông đề nghị làm gì?","opts":["Authorize free shipping","Apply a discount","Provide a sample","Make a recommendation"],"vi":["Cho phép miễn phí vận chuyển","Áp dụng giảm giá","Cung cấp hàng mẫu","Đưa ra gợi ý"],"ans":"D","xp":"Người đàn ông nói: \"I could recommend a quality brand if you know what type he enjoys.\"\n'recommend a quality brand' = 'Make a recommendation' (đưa ra gợi ý) → (D)."},{"n":40,"q":"What does the woman ask about?","qvi":"Người phụ nữ hỏi về điều gì?","opts":["An expiration date","A manufacturer's guarantee","The origin of a product","The cost of a product"],"vi":["Hạn sử dụng","Giấy bảo hành của nhà sản xuất","Nguồn gốc của sản phẩm","Giá của sản phẩm"],"ans":"A","xp":"Người phụ nữ hỏi: \"Do your cards have an expiration date?\" (thẻ có hạn sử dụng không?) → (A)."}],"a":"E24-T05-38-40.mp3"},{"ns":[41,43],"script":[["M1","Thanks for meeting with us, Ms. Raj. We're excited to learn about the product your company has developed for factories like ours.","Cảm ơn chị đã gặp chúng tôi, chị Raj. Chúng tôi rất háo hức được tìm hiểu về sản phẩm mà công ty chị đã phát triển cho những nhà máy như của chúng tôi."],["W","I'm happy to tell you about it. It's an application to monitor factory machines. It identifies problems in operations and generates a report about the efficiency of each machine.","Tôi rất vui được giới thiệu. Đây là một ứng dụng để giám sát máy móc trong nhà máy. Nó phát hiện các vấn đề trong vận hành và tạo báo cáo về hiệu suất của từng máy."],["M2","That sounds great! We have about 100 machine operators here. How much training would be involved?","Nghe tuyệt quá! Chúng tôi có khoảng 100 công nhân vận hành máy ở đây. Sẽ cần đào tạo bao nhiêu?"],["W","About an hour's worth. We provide a video with step-by-step instructions.","Khoảng một giờ thôi. Chúng tôi cung cấp một video hướng dẫn từng bước."],["M1","Excellent. That's good to know.","Tuyệt vời. Thật tốt khi biết điều đó."]],"qs":[{"n":41,"q":"Why is the woman visiting?","qvi":"Tại sao người phụ nữ đến thăm?","opts":["To promote a product","To sign a contract","To tour a facility","To inspect some equipment"],"vi":["Để quảng bá một sản phẩm","Để ký hợp đồng","Để tham quan một cơ sở","Để kiểm tra một số thiết bị"],"ans":"A","xp":"Người đàn ông thứ nhất nói: \"We're excited to learn about the product your company has developed for factories like ours.\" → người phụ nữ đến để giới thiệu, quảng bá sản phẩm của công ty cô → (A)."},{"n":42,"q":"What did the woman's company design?","qvi":"Công ty của người phụ nữ đã thiết kế cái gì?","opts":["A digital security system","A device to lift heavy objects","An application to monitor machines","Protective clothing for workers"],"vi":["Một hệ thống an ninh kỹ thuật số","Một thiết bị nâng vật nặng","Một ứng dụng giám sát máy móc","Quần áo bảo hộ cho công nhân"],"ans":"C","xp":"Người phụ nữ nói: \"It's an application to monitor factory machines.\" (Đây là ứng dụng giám sát máy móc nhà máy) → (C)."},{"n":43,"q":"What does the woman say her company can provide?","qvi":"Người phụ nữ nói công ty cô có thể cung cấp gì?","opts":["A new client discount","A training video","An extended warranty","Customer testimonials"],"vi":["Ưu đãi giảm giá cho khách hàng mới","Một video đào tạo","Bảo hành mở rộng","Lời chứng thực của khách hàng"],"ans":"B","xp":"Người phụ nữ nói: \"We provide a video with step-by-step instructions.\"\n'a video with step-by-step instructions' (video hướng dẫn từng bước) = 'A training video' → (B)."}],"a":"E24-T05-41-43.mp3"},{"ns":[44,46],"script":[["W","Hi. I'd like to go to the Baldwin Theater. The address is 91 Circle Drive.","Chào anh. Tôi muốn đến Nhà hát Baldwin. Địa chỉ là số 91 đường Circle."],["M","Sure, but did you know they're resurfacing Circle Drive? I just dropped someone off in that area.","Được thôi, nhưng chị có biết họ đang trải lại mặt đường Circle không? Tôi vừa thả một khách ở khu đó."],["W","Oh, really? I've got a ticket to a play, and the show starts at seven thirty. They don't let you in if you're late.","Ồ, thật sao? Tôi có vé xem kịch, và buổi diễn bắt đầu lúc 7 giờ 30. Nếu đến muộn họ không cho vào đâu."],["M","Well, let me see. I can turn onto Felton Street and cut over to Lancaster Drive. It's a little out of the way, but it'll get you close to the theater.","Để tôi xem nào. Tôi có thể rẽ vào phố Felton rồi cắt sang đường Lancaster. Hơi đi vòng một chút, nhưng sẽ đưa chị đến gần nhà hát."]],"qs":[{"n":44,"q":"Who most likely is the man?","qvi":"Người đàn ông nhiều khả năng là ai?","opts":["A theater employee","A taxi driver","A train conductor","A construction worker"],"vi":["Nhân viên nhà hát","Tài xế taxi","Nhân viên soát vé tàu","Công nhân xây dựng"],"ans":"B","xp":"Người phụ nữ nói muốn đến nhà hát Baldwin, người đàn ông đáp \"Sure\" và nói \"I just dropped someone off in that area.\" (tôi vừa thả một người ở khu đó) → anh ấy là tài xế taxi → (B)."},{"n":45,"q":"What is causing a problem?","qvi":"Điều gì đang gây ra vấn đề?","opts":["A truck is too heavy.","An event has been delayed.","A parking area is full.","A road is closed."],"vi":["Một chiếc xe tải quá nặng.","Một sự kiện đã bị hoãn.","Một bãi đỗ xe đã kín chỗ.","Một con đường bị đóng."],"ans":"D","xp":"Người đàn ông hỏi: \"did you know they're resurfacing Circle Drive?\" (đường Circle đang được trải lại mặt đường), rồi đề xuất đi đường khác (Felton Street, Lancaster Drive) → đường Circle đang bị đóng → (D)."},{"n":46,"q":"What does the man say he will do?","qvi":"Người đàn ông nói anh ấy sẽ làm gì?","opts":["Ask for a refund","Take a different route","Postpone a trip","File a complaint"],"vi":["Yêu cầu hoàn tiền","Đi một tuyến đường khác","Hoãn chuyến đi","Gửi đơn khiếu nại"],"ans":"B","xp":"Người đàn ông nói: \"I can turn onto Felton Street and cut over to Lancaster Drive.\" (rẽ vào phố Felton rồi cắt sang đường Lancaster) → đi đường khác = 'Take a different route' → (B)."}],"a":"E24-T05-44-46.mp3"},{"ns":[47,49],"script":[["W","Do you have a minute to discuss the budget for the upcoming Vancouver meeting? I've looked over the travel requests you submitted for your team. Last year we sent only two representatives.","Anh có chút thời gian để bàn về ngân sách cho cuộc họp sắp tới ở Vancouver không? Tôi đã xem qua các đề nghị đi công tác anh nộp cho nhóm của anh. Năm ngoái chúng ta chỉ cử hai người đại diện thôi."],["M","Ms. Tamura has just given us approval to send three. In fact, the clients are looking to expand their online service options, and the third representative we're bringing is particularly knowledgeable about that.","Chị Tamura vừa duyệt cho chúng tôi cử ba người. Thật ra, khách hàng đang muốn mở rộng các lựa chọn dịch vụ trực tuyến của họ, và người đại diện thứ ba chúng tôi dẫn theo đặc biệt am hiểu về lĩnh vực đó."],["W","OK. I guess we'll have to find savings somewhere else, then.","Được rồi. Vậy có lẽ chúng ta phải tìm cách tiết kiệm ở khoản khác."],["M","I've already looked into some new meeting venues. The Renova Hotel is offering discounted corporate rates this month.","Tôi đã tìm hiểu một vài địa điểm họp mới rồi. Khách sạn Renova đang có giá ưu đãi cho doanh nghiệp trong tháng này."]],"qs":[{"n":47,"q":"Why does the woman say, \"Last year we sent only two representatives\"?","qvi":"Tại sao người phụ nữ nói \"Năm ngoái chúng ta chỉ cử hai người đại diện\"?","opts":["To explain a delay","To compliment a team","To point out that an event was unsuccessful","To question a decision"],"vi":["Để giải thích một sự chậm trễ","Để khen ngợi một nhóm","Để chỉ ra rằng một sự kiện không thành công","Để đặt câu hỏi về một quyết định"],"ans":"D","xp":"Câu hỏi hàm ý. Người phụ nữ vừa xem đề nghị công tác của nhóm anh (\"I've looked over the travel requests you submitted\") rồi nói năm ngoái chỉ cử hai người → cô thắc mắc vì sao năm nay cử nhiều người hơn. Người đàn ông liền giải thích \"Ms. Tamura has just given us approval to send three.\" → cô đang nghi vấn về quyết định này → (D)."},{"n":48,"q":"According to the man, what do some clients want to do?","qvi":"Theo người đàn ông, một số khách hàng muốn làm gì?","opts":["Increase their online offerings","Obtain additional financing","Open a new office","Recruit more employees"],"vi":["Tăng các dịch vụ trực tuyến của họ","Có thêm nguồn vốn","Mở văn phòng mới","Tuyển thêm nhân viên"],"ans":"A","xp":"Người đàn ông nói: \"the clients are looking to expand their online service options\".\n'expand their online service options' (mở rộng lựa chọn dịch vụ trực tuyến) = 'Increase their online offerings' → (A)."},{"n":49,"q":"According to the man, what is the Renova Hotel offering this month?","qvi":"Theo người đàn ông, tháng này khách sạn Renova đang cung cấp gì?","opts":["A new shuttle service","A discount for businesses","A flexible cancellation policy","Complimentary meals"],"vi":["Dịch vụ xe đưa đón mới","Giảm giá cho doanh nghiệp","Chính sách hủy linh hoạt","Bữa ăn miễn phí"],"ans":"B","xp":"Người đàn ông nói: \"The Renova Hotel is offering discounted corporate rates this month.\"\n'discounted corporate rates' (giá ưu đãi cho doanh nghiệp) = 'A discount for businesses' → (B)."}],"a":"E24-T05-47-49.mp3"},{"ns":[50,52],"script":[["W","Good morning. I wanted to meet today to discuss the recent decline in our museum's ticket sales. You're the outreach coordinator, so I'm hoping you might have some ideas on how we can attract more community involvement.","Chào buổi sáng. Hôm nay tôi muốn gặp anh để bàn về việc doanh số bán vé của bảo tàng chúng ta gần đây bị sụt giảm. Anh là điều phối viên hoạt động cộng đồng, nên tôi hy vọng anh có ý tưởng nào đó để thu hút cộng đồng tham gia nhiều hơn."],["M","Well, I recently read an article about a museum in Chicago that has a room where visitors can paint on the walls. It's become very popular. We could try it here—we have that huge room on the third floor that isn't being used.","À, gần đây tôi có đọc một bài báo về một bảo tàng ở Chicago có một căn phòng nơi khách tham quan có thể vẽ lên tường. Nó trở nên rất được ưa chuộng. Chúng ta có thể thử ở đây—chúng ta có căn phòng rất lớn ở tầng ba đang không được sử dụng."],["W","That's a great idea. Can you draft a list of the supplies we would need to make sure we have the budget for them?","Ý tưởng tuyệt vời. Anh có thể soạn thảo danh sách các vật dụng chúng ta cần để đảm bảo chúng ta có đủ ngân sách cho chúng không?"]],"qs":[{"n":50,"q":"What problem does the woman mention?","qvi":"Người phụ nữ đề cập đến vấn đề gì?","opts":["A decrease in ticket sales","A lack of exhibition space","A colleague's resignation","A damaged painting"],"vi":["Doanh số bán vé giảm","Thiếu không gian triển lãm","Một đồng nghiệp nghỉ việc","Một bức tranh bị hư hại"],"ans":"A","xp":"Người phụ nữ nói: \"I wanted to meet today to discuss the recent decline in our museum's ticket sales.\"\n'decline' (sự sụt giảm) = 'decrease' → (A)."},{"n":51,"q":"What does the man suggest doing?","qvi":"Người đàn ông gợi ý làm gì?","opts":["Relocating an exhibit","Consulting a specialist","Adding security measures","Introducing a new activity"],"vi":["Di dời một khu trưng bày","Tham khảo ý kiến chuyên gia","Bổ sung các biện pháp an ninh","Giới thiệu một hoạt động mới"],"ans":"D","xp":"Người đàn ông kể về bảo tàng ở Chicago có phòng \"where visitors can paint on the walls\" và nói \"We could try it here\" (chúng ta có thể thử ở đây) → anh gợi ý đưa vào một hoạt động mới cho khách (vẽ lên tường) → (D)."},{"n":52,"q":"What will the man most likely do next?","qvi":"Người đàn ông nhiều khả năng sẽ làm gì tiếp theo?","opts":["Write a press release","Attend a budget meeting","Make a list of supplies","Plan a site visit"],"vi":["Viết thông cáo báo chí","Dự một cuộc họp ngân sách","Lập danh sách vật dụng","Lên kế hoạch đi khảo sát thực địa"],"ans":"C","xp":"Người phụ nữ nhờ: \"Can you draft a list of the supplies we would need...?\"\n'draft a list of the supplies' (soạn danh sách vật dụng) = 'Make a list of supplies' → (C)."}],"a":"E24-T05-50-52.mp3"},{"ns":[53,55],"script":[["W1","Thilo, this is Ms. Gao, a new customer. She's purchasing an upholstered sofa. We just walked around our showroom, and she's decided on our Hudson model.","Thilo, đây là chị Gao, một khách hàng mới. Chị ấy mua một chiếc ghế sofa bọc nệm. Chúng tôi vừa đi một vòng phòng trưng bày, và chị ấy đã chọn mẫu Hudson của chúng ta."],["M","One of our best sellers!","Một trong những mẫu bán chạy nhất của chúng ta đấy!"],["W2","It is really comfortable.","Nó thật sự rất thoải mái."],["W1","Can you assist her with the paperwork for our payment plan?","Anh có thể giúp chị ấy làm giấy tờ cho gói thanh toán của chúng ta không?"],["M","Sure. Happy to help you, Ms. Gao. Are you getting the standard fabric?","Chắc chắn rồi. Rất vui được giúp chị, chị Gao. Chị chọn loại vải tiêu chuẩn phải không?"],["W2","No—I'd like to select a custom fabric.","Không—tôi muốn chọn vải đặt riêng theo yêu cầu."],["M","Just so you know, the price will increase some with a custom order.","Xin lưu ý là giá sẽ tăng thêm một chút với đơn đặt làm theo yêu cầu."],["W2","I think it's worth the extra cost. It'll really brighten up my living room.","Tôi nghĩ đáng để trả thêm. Nó sẽ làm phòng khách của tôi sáng sủa hẳn lên."],["M","Wonderful. Now in order to set up a payment plan, I'll need to see some identification. A driver's license will do.","Tuyệt vời. Bây giờ để lập gói thanh toán, tôi cần xem giấy tờ tùy thân của chị. Bằng lái xe là được."]],"qs":[{"n":53,"q":"Where most likely are the speakers?","qvi":"Những người nói nhiều khả năng đang ở đâu?","opts":["At a clothing factory","At a bookstore","At a tailor's shop","At a furniture store"],"vi":["Ở một xưởng may quần áo","Ở một hiệu sách","Ở một tiệm may","Ở một cửa hàng nội thất"],"ans":"D","xp":"Người phụ nữ thứ nhất nói: \"this is Ms. Gao, a new customer. She's purchasing an upholstered sofa. We just walked around our showroom\" → họ đang ở cửa hàng bán đồ nội thất (sofa = furniture) → (D)."},{"n":54,"q":"According to the man, why will a product cost more?","qvi":"Theo người đàn ông, tại sao một sản phẩm sẽ đắt hơn?","opts":["It includes an extended warranty.","It is a custom order.","A rebate has expired.","Shipping will be expedited."],"vi":["Nó bao gồm bảo hành mở rộng.","Đó là đơn đặt làm theo yêu cầu.","Một khoản hoàn tiền đã hết hạn.","Việc giao hàng sẽ được đẩy nhanh."],"ans":"B","xp":"Người đàn ông nói: \"the price will increase some with a custom order.\" (giá sẽ tăng với đơn đặt riêng) → (B)."},{"n":55,"q":"What does the man request?","qvi":"Người đàn ông yêu cầu gì?","opts":["A purchase receipt","A delivery address","A form of identification","An account number"],"vi":["Hóa đơn mua hàng","Địa chỉ giao hàng","Một loại giấy tờ tùy thân","Số tài khoản"],"ans":"C","xp":"Người đàn ông nói: \"to set up a payment plan, I'll need to see some identification. A driver's license will do.\" → anh yêu cầu giấy tờ tùy thân → (C)."}],"a":"E24-T05-53-55.mp3"},{"ns":[56,58],"script":[["W","Good morning, Mr. Tong. I'm here to check on my order. How are the chairs coming along?","Chào buổi sáng, anh Tong. Tôi đến để kiểm tra đơn hàng của mình. Mấy chiếc ghế làm đến đâu rồi?"],["M","The machines have been assembling them. They're almost ready. Right over here.","Máy móc đang lắp ráp chúng. Gần xong rồi. Ở ngay đằng này."],["W","Wow, they look so nice!","Ồ, trông chúng đẹp quá!"],["M","Look at the curved shape of the back. The only way you can get that unique shape is by means of the specialized laser we use.","Chị nhìn phần lưng ghế cong này xem. Cách duy nhất để tạo ra hình dáng độc đáo đó là dùng loại tia laser chuyên dụng mà chúng tôi sử dụng."],["W","Amazing! Can I also see the pullout sofa?","Tuyệt quá! Tôi có thể xem luôn chiếc sofa giường kéo được không?"],["M","Not right now. It's being treated with mineral oil. But later today I should be able to take a photo and send it to you.","Bây giờ thì chưa được. Nó đang được xử lý bằng dầu khoáng. Nhưng chiều nay chắc tôi có thể chụp ảnh và gửi cho chị."]],"qs":[{"n":56,"q":"Where most likely are the speakers?","qvi":"Những người nói nhiều khả năng đang ở đâu?","opts":["At a hotel","At a factory","At a retail store","At a trade show"],"vi":["Ở khách sạn","Ở nhà máy","Ở cửa hàng bán lẻ","Ở hội chợ thương mại"],"ans":"B","xp":"Người phụ nữ hỏi về đơn hàng ghế: \"How are the chairs coming along?\", người đàn ông đáp \"The machines have been assembling them.\" (máy móc đang lắp ráp ghế) → họ đang ở nơi sản xuất ghế, tức nhà máy → (B)."},{"n":57,"q":"What feature does the man emphasize about some chairs?","qvi":"Người đàn ông nhấn mạnh đặc điểm nào của những chiếc ghế?","opts":["The color","The price","The shape","The durability"],"vi":["Màu sắc","Giá cả","Hình dáng","Độ bền"],"ans":"C","xp":"Người đàn ông nói: \"Look at the curved shape of the back. The only way you can get that unique shape is...\" → anh nhấn mạnh hình dáng (shape) → (C)."},{"n":58,"q":"What does the man say he will do later?","qvi":"Người đàn ông nói lát nữa anh ấy sẽ làm gì?","opts":["Modify a design","E-mail a contract","Create an invoice","Send a photo"],"vi":["Chỉnh sửa thiết kế","Gửi hợp đồng qua e-mail","Lập hóa đơn","Gửi một tấm ảnh"],"ans":"D","xp":"Người đàn ông nói: \"later today I should be able to take a photo and send it to you.\" → anh sẽ gửi ảnh → (D)."}],"a":"E24-T05-56-58.mp3"},{"ns":[59,61],"script":[["M","Hi, So-Jin. I just heard that Ms. Yoon is retiring next month.","Chào So-Jin. Tôi vừa nghe nói chị Yoon sẽ nghỉ hưu vào tháng sau."],["W","I'll be sorry to see her go. She was my mentor when I first joined the firm, and we've worked on dozens of projects together.","Tôi sẽ rất tiếc khi chị ấy rời đi. Chị ấy là người hướng dẫn tôi khi tôi mới vào công ty, và chúng tôi đã cùng làm hàng chục dự án."],["M","It's a bit hard to imagine our sales team without her. Has anybody approached you about leading the team after she's gone?","Thật khó hình dung đội kinh doanh của chúng ta mà không có chị ấy. Đã có ai đến đề nghị chị dẫn dắt đội sau khi chị ấy nghỉ chưa?"],["W","Yes, and I've thought about it. It's a big step up, even for someone like me who's worked in Sales for eight years. And Human Resources hasn't even posted the job description yet.","Có, và tôi đã suy nghĩ về việc đó. Đó là một bước tiến lớn, kể cả với người đã làm ở bộ phận Kinh doanh tám năm như tôi. Mà phòng Nhân sự thậm chí còn chưa đăng bản mô tả công việc."],["M","Well, we need someone with experience.","Chà, chúng ta cần một người có kinh nghiệm mà."]],"qs":[{"n":59,"q":"What will happen next month?","qvi":"Điều gì sẽ xảy ra vào tháng sau?","opts":["An award will be given.","A new product will launch.","A colleague will retire.","An office will relocate."],"vi":["Một giải thưởng sẽ được trao.","Một sản phẩm mới sẽ ra mắt.","Một đồng nghiệp sẽ nghỉ hưu.","Một văn phòng sẽ chuyển địa điểm."],"ans":"C","xp":"Người đàn ông nói: \"I just heard that Ms. Yoon is retiring next month.\" → đồng nghiệp (chị Yoon) sẽ nghỉ hưu → (C)."},{"n":60,"q":"What department do the speakers work in?","qvi":"Những người nói làm việc ở phòng ban nào?","opts":["Sales","Human Resources","Legal","Accounting"],"vi":["Kinh doanh","Nhân sự","Pháp chế","Kế toán"],"ans":"A","xp":"Người đàn ông nói: \"It's a bit hard to imagine our sales team without her.\" ('our sales team' = đội kinh doanh của chúng ta); người phụ nữ cũng nói đã làm \"in Sales for eight years\" → (A).\n(B) Human Resources được nhắc đến nhưng là phòng ban khác."},{"n":61,"q":"What does the man imply when he says, \"we need someone with experience\"?","qvi":"Người đàn ông ngụ ý gì khi nói \"chúng ta cần một người có kinh nghiệm\"?","opts":["The team has grown very quickly.","The woman should apply for a job.","A job description should be revised.","A new manager is not experienced enough."],"vi":["Đội đã phát triển rất nhanh.","Người phụ nữ nên ứng tuyển vào vị trí đó.","Bản mô tả công việc nên được sửa lại.","Một quản lý mới không đủ kinh nghiệm."],"ans":"B","xp":"Câu hỏi hàm ý. Người phụ nữ ngần ngại vì đó là \"a big step up\" dù cô đã \"worked in Sales for eight years\". Người đàn ông đáp \"we need someone with experience\" → ý là cô có 8 năm kinh nghiệm, chính là người phù hợp, nên ứng tuyển vị trí trưởng nhóm → (B)."}],"a":"E24-T05-59-61.mp3"},{"ns":[62,64],"script":[["W","Rajesh, it was nice to see you here in New York again this year.","Rajesh, thật vui được gặp lại anh ở New York năm nay."],["M","Same here. I look forward to attending the Theater Technology Conference again next year.","Tôi cũng vậy. Tôi rất mong được tham dự lại Hội nghị Công nghệ Sân khấu vào năm sau."],["W","I really enjoyed your talk, especially the information you provided on acoustics. Is it published anywhere? I'd like to have a closer look.","Tôi rất thích bài nói của anh, nhất là thông tin anh đưa ra về âm học. Nó có được đăng ở đâu không? Tôi muốn xem kỹ hơn."],["M","Actually, it is. You can find the article in last November's issue of Theater Sound. It's posted online.","Thật ra là có. Chị có thể tìm bài viết trong số tháng Mười Một năm ngoái của tạp chí Theater Sound. Nó được đăng trên mạng."],["W","Great. I'll look it up.","Tuyệt. Tôi sẽ tìm đọc."],["M","Oh—my train leaves in fourteen minutes. I have to get going. Safe travels, Camille!","Ồ—tàu của tôi khởi hành sau mười bốn phút nữa. Tôi phải đi đây. Chúc chị thượng lộ bình an, Camille!"]],"qs":[{"n":62,"q":"Why are the speakers in New York?","qvi":"Tại sao những người nói đang ở New York?","opts":["They saw a play.","They attended a conference.","They met with some clients.","They viewed some real estate."],"vi":["Họ đã xem một vở kịch.","Họ đã tham dự một hội nghị.","Họ đã gặp một số khách hàng.","Họ đã đi xem bất động sản."],"ans":"B","xp":"Người phụ nữ nói vui được gặp lại anh \"here in New York again this year\", người đàn ông đáp \"I look forward to attending the Theater Technology Conference again next year.\" → họ đến New York để dự hội nghị → (B)."},{"n":63,"q":"What does the woman ask the man about?","qvi":"Người phụ nữ hỏi người đàn ông về điều gì?","opts":["Locating some information","Applying for a position","Opening a branch office","Making a reservation"],"vi":["Tìm một số thông tin","Ứng tuyển một vị trí","Mở văn phòng chi nhánh","Đặt chỗ trước"],"ans":"A","xp":"Người phụ nữ khen phần thông tin về âm học trong bài nói của anh và hỏi: \"Is it published anywhere? I'd like to have a closer look.\" (nó có được đăng ở đâu không?) → cô hỏi chỗ tìm thông tin đó → (A)."},{"n":64,"q":"Look at the graphic. Where will the man travel to next?","qvi":"Hãy nhìn vào hình. Người đàn ông sẽ đi đến đâu tiếp theo?","opts":["Shady Grove","Braddock Bay","Largo","Ashburn"],"vi":["Shady Grove","Braddock Bay","Largo","Ashburn"],"ans":"C","xp":"Người đàn ông nói: \"my train leaves in fourteen minutes\" (tàu của tôi chạy sau 14 phút). Trên bảng, chuyến tàu đến sau 14 phút là tuyến Blue đi Largo → (C)."}],"a":"E24-T05-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["M","Welcome to Orlando's Deli. If you'd like to try one of our daily specials, they're on the board behind me.","Chào mừng chị đến với Orlando's Deli. Nếu chị muốn thử một món đặc biệt trong ngày, các món đó được ghi trên tấm bảng phía sau tôi."],["W","Wow, that's a great menu. The vegetable curry looks good. Is it spicy?","Ồ, thực đơn tuyệt quá. Món cà ri rau trông ngon đấy. Nó có cay không?"],["M","No, it's very mild—but we just sold out, unfortunately.","Không, nó rất dịu—nhưng tiếc là chúng tôi vừa bán hết rồi."],["W","In that case, I'll have the lasagna.","Vậy thì tôi sẽ gọi món lasagna."],["M","Great choice. By the way, we just opened our new patio this week in case you'd like to sit outside.","Lựa chọn tuyệt vời. Nhân tiện, tuần này chúng tôi vừa mở khu sân hiên mới, nếu chị muốn ngồi ngoài trời."],["W","Actually, it is a beautiful day. And your patio looks lovely.","Thật ra hôm nay trời đẹp thật. Mà sân hiên của quán trông dễ thương quá."]],"qs":[{"n":65,"q":"What does the woman ask the man about?","qvi":"Người phụ nữ hỏi người đàn ông về điều gì?","opts":["Whether a coupon is valid","Whether a food is spicy","Whether a drink is included","Whether any seats are available"],"vi":["Phiếu giảm giá có còn hiệu lực không","Một món ăn có cay không","Có kèm đồ uống không","Còn chỗ ngồi không"],"ans":"B","xp":"Người phụ nữ hỏi về món cà ri rau: \"Is it spicy?\" (Nó có cay không?) → (B)."},{"n":66,"q":"Look at the graphic. Which special does the woman order?","qvi":"Hãy nhìn vào hình. Người phụ nữ gọi món đặc biệt nào?","opts":["Special 1","Special 2","Special 3","Special 4"],"vi":["Món đặc biệt số 1","Món đặc biệt số 2","Món đặc biệt số 3","Món đặc biệt số 4"],"ans":"C","xp":"Món cà ri rau đã hết, người phụ nữ nói: \"In that case, I'll have the lasagna.\" Trên thực đơn, Lasagna là món số 3 → (C)."},{"n":67,"q":"What will the woman most likely do next?","qvi":"Người phụ nữ nhiều khả năng sẽ làm gì tiếp theo?","opts":["Move her car","Go to a patio","Make a reservation","Meet some friends"],"vi":["Dời xe của cô ấy","Ra khu sân hiên","Đặt chỗ","Gặp vài người bạn"],"ans":"B","xp":"Người đàn ông nói quán vừa mở sân hiên mới \"in case you'd like to sit outside\", người phụ nữ đáp \"it is a beautiful day. And your patio looks lovely.\" → cô sẽ ra ngồi ở sân hiên → (B)."}],"a":"E24-T05-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["W","I'm excited about our hike today here at Marina Park. And I'm so glad we got to the park early before it gets crowded. Which trail should we hike?","Tôi rất háo hức với chuyến đi bộ đường dài hôm nay ở Công viên Marina. Và tôi rất mừng là chúng ta đến công viên sớm trước khi nó đông người. Chúng ta nên đi đường mòn nào?"],["M","Let's take a look at the map. We're at the visitor center, and there's a shuttle that stops at different trailheads.","Mình xem bản đồ đi. Chúng ta đang ở trung tâm du khách, và có một xe đưa đón dừng ở các điểm đầu đường mòn khác nhau."],["W","Right. It looks like the Creek Trail and the Pond Trail are fairly short. I'd like to do a more challenging hike.","Đúng rồi. Có vẻ như đường mòn Creek và đường mòn Pond khá ngắn. Tôi muốn đi một tuyến thử thách hơn."],["M","OK. How about the Waterfall Trail?","Được. Vậy đường mòn Waterfall thì sao?"],["W","That sounds good. And look—there's a video about the park. We can watch while we wait.","Nghe được đấy. Và nhìn kìa—có một video về công viên. Chúng ta có thể xem trong lúc chờ."]],"qs":[{"n":68,"q":"What is the woman happy about?","qvi":"Người phụ nữ vui về điều gì?","opts":["She happened to meet some friends.","The weather is perfect for an activity.","The park was closer than expected.","There are few people in the park."],"vi":["Cô ấy tình cờ gặp vài người bạn.","Thời tiết hoàn hảo cho một hoạt động.","Công viên gần hơn dự kiến.","Có ít người trong công viên."],"ans":"D","xp":"Người phụ nữ nói: \"I'm so glad we got to the park early before it gets crowded.\" (mừng vì đến sớm trước khi đông người) → hiện công viên còn vắng người → (D)."},{"n":69,"q":"Look at the graphic. How far will the speakers hike?","qvi":"Hãy nhìn vào hình. Những người nói sẽ đi bộ bao xa?","opts":["7 kilometers","5 kilometers","2 kilometers","1 kilometer"],"vi":["7 ki-lô-mét","5 ki-lô-mét","2 ki-lô-mét","1 ki-lô-mét"],"ans":"B","xp":"Người đàn ông gợi ý: \"How about the Waterfall Trail?\", người phụ nữ đồng ý: \"That sounds good.\" Trên bản đồ, Waterfall Trail dài 5 kilometers → (B)."},{"n":70,"q":"What can the speakers do while waiting for the shuttle?","qvi":"Những người nói có thể làm gì trong lúc chờ xe đưa đón?","opts":["Buy some snacks","Watch a video","Visit a gift shop","Rent some equipment"],"vi":["Mua đồ ăn vặt","Xem một video","Ghé cửa hàng quà lưu niệm","Thuê thiết bị"],"ans":"B","xp":"Người phụ nữ nói: \"there's a video about the park. We can watch while we wait.\" → họ có thể xem video trong lúc chờ → (B)."}],"a":"E24-T05-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","Hi, Ms. Cho. I'm calling from Springdale Lights. Yesterday, you ordered 24 of our purple solar lanterns for your upcoming event. Unfortunately, our supplier won't be able to get us purple lanterns for another three weeks, so we only have yellow ones in stock. We would like to offer you a ten percent discount on them to apologize for this. Please call us back to confirm whether you'd like the yellow solar lights, and we'll set them aside for you.","Xin chào chị Cho. Tôi gọi từ Springdale Lights. Hôm qua, chị đã đặt 24 chiếc đèn lồng năng lượng mặt trời màu tím của chúng tôi cho sự kiện sắp tới của chị. Thật không may, nhà cung cấp của chúng tôi sẽ không thể giao đèn lồng màu tím cho chúng tôi trong ba tuần nữa, nên hiện chúng tôi chỉ còn đèn màu vàng trong kho. Để xin lỗi chị về việc này, chúng tôi xin giảm giá 10% cho những chiếc đèn màu vàng. Vui lòng gọi lại cho chúng tôi để xác nhận chị có muốn lấy đèn năng lượng mặt trời màu vàng không, và chúng tôi sẽ giữ lại cho chị."]],"qs":[{"n":71,"q":"What did the listener do yesterday?","qvi":"Hôm qua người nghe đã làm gì?","opts":["She placed an order.","She scheduled an event.","She called a manager.","She painted some rooms."],"vi":["Cô ấy đã đặt hàng.","Cô ấy đã lên lịch một sự kiện.","Cô ấy đã gọi cho quản lý.","Cô ấy đã sơn vài căn phòng."],"ans":"A","xp":"Người nói: \"Yesterday, you ordered 24 of our purple solar lanterns\" (hôm qua chị đã đặt 24 đèn lồng).\n'ordered' = 'placed an order' (đặt hàng) → (A)."},{"n":72,"q":"What problem does the speaker mention?","qvi":"Người nói đề cập đến vấn đề gì?","opts":["A price has increased.","A machine needs to be repaired.","A product is not available.","A performance has been canceled."],"vi":["Giá đã tăng.","Một chiếc máy cần được sửa.","Một sản phẩm hiện không có sẵn.","Một buổi biểu diễn đã bị hủy."],"ans":"C","xp":"Người nói: \"Unfortunately, our supplier won't be able to get us purple lanterns for another three weeks, so we only have yellow ones in stock.\" → đèn màu tím hiện không có hàng → (C)."},{"n":73,"q":"What does the speaker offer the listener?","qvi":"Người nói đề nghị cho người nghe điều gì?","opts":["Expedited shipping","A full refund","A free consultation","A discount"],"vi":["Giao hàng nhanh","Hoàn tiền toàn bộ","Tư vấn miễn phí","Giảm giá"],"ans":"D","xp":"Người nói: \"We would like to offer you a ten percent discount on them to apologize for this.\" → đề nghị giảm giá 10% → (D)."}],"a":"E24-T05-71-73.mp3"},{"ns":[74,76],"script":[["","Welcome to Osterwind Estate. The former owner, Ms. Yuping Wei, was a famous painter. What's special about this estate is that Ms. Wei designed it herself, including the landscaping. We're asking volunteers to clear debris from the walkways around the gardens in preparation for the estate's first season as a public park. You can pick up a bag and gloves from the patio area. And remember, be sure to see me as you check out before you leave. All volunteers are eligible for a complimentary visitor pass that you can use to access the estate and attend any events held here all summer long.","Chào mừng các bạn đến với Dinh thự Osterwind. Chủ nhân trước đây, bà Yuping Wei, là một họa sĩ nổi tiếng. Điều đặc biệt ở dinh thự này là chính bà Wei đã tự thiết kế nó, kể cả phần cảnh quan. Chúng tôi đề nghị các tình nguyện viên dọn rác trên các lối đi quanh khu vườn để chuẩn bị cho mùa đầu tiên dinh thự mở cửa như một công viên công cộng. Các bạn có thể lấy túi và găng tay ở khu sân hiên. Và hãy nhớ gặp tôi để làm thủ tục ra về trước khi rời đi. Tất cả tình nguyện viên đều được nhận một thẻ tham quan miễn phí, có thể dùng để vào dinh thự và tham dự mọi sự kiện được tổ chức ở đây suốt mùa hè."]],"qs":[{"n":74,"q":"According to the speaker, what is special about Osterwind Estate?","qvi":"Theo người nói, điều gì đặc biệt ở Dinh thự Osterwind?","opts":["It houses many historic paintings.","It was designed by its owner.","It includes a botanical garden.","It is used as a museum."],"vi":["Nó lưu giữ nhiều bức tranh lịch sử.","Nó được thiết kế bởi chính chủ nhân của nó.","Nó có một vườn thực vật.","Nó được dùng làm bảo tàng."],"ans":"B","xp":"Người nói: \"What's special about this estate is that Ms. Wei designed it herself\" (bà Wei – chủ nhân trước đây – tự thiết kế) → (B).\n(A) bà Wei là họa sĩ nhưng không nói dinh thự lưu giữ nhiều tranh."},{"n":75,"q":"Why are the listeners at Osterwind Estate?","qvi":"Tại sao người nghe có mặt ở Dinh thự Osterwind?","opts":["To attend an awards ceremony","To apply for landscaping jobs","To take a tour of a building","To clean up some gardens"],"vi":["Để dự lễ trao giải","Để ứng tuyển việc làm cảnh quan","Để tham quan một tòa nhà","Để dọn dẹp khu vườn"],"ans":"D","xp":"Người nói: \"We're asking volunteers to clear debris from the walkways around the gardens\" và hướng dẫn lấy túi, găng tay → người nghe là tình nguyện viên đến dọn dẹp vườn.\n'clear debris from the walkways around the gardens' = 'clean up some gardens' → (D)."},{"n":76,"q":"What will the listeners receive?","qvi":"Người nghe sẽ nhận được gì?","opts":["Gift-shop coupons","Free passes","Lunch boxes","T-shirts"],"vi":["Phiếu giảm giá cửa hàng quà tặng","Thẻ vào cửa miễn phí","Hộp cơm trưa","Áo phông"],"ans":"B","xp":"Người nói: \"All volunteers are eligible for a complimentary visitor pass\".\n'complimentary' (miễn phí) visitor pass = 'Free passes' → (B)."}],"a":"E24-T05-74-76.mp3"},{"ns":[77,79],"script":[["","Good morning, Ms. Espinosa. This is Marcel Fournier. It's Saturday morning, and I'm on my way to the airport. This is a little out of the ordinary, but I'm calling because in my haste I left a note with Mr. Hang's mobile phone number on my office desk. He's picking me up from the airport, and I'll be stuck if I can't reach him. I'll need you to go into the office and text me with the number. I know this is inconvenient. I'll check my messages once I land in San Diego.","Chào buổi sáng, chị Espinosa. Tôi là Marcel Fournier. Bây giờ là sáng thứ Bảy và tôi đang trên đường ra sân bay. Chuyện này hơi bất thường một chút, nhưng tôi gọi vì trong lúc vội vàng tôi đã để quên mẩu giấy ghi số điện thoại di động của ông Hang trên bàn làm việc. Ông ấy sẽ đón tôi ở sân bay, và tôi sẽ bị kẹt lại nếu không liên lạc được với ông ấy. Tôi cần chị đến văn phòng và nhắn tin số điện thoại đó cho tôi. Tôi biết việc này gây bất tiện cho chị. Tôi sẽ kiểm tra tin nhắn ngay khi hạ cánh ở San Diego."]],"qs":[{"n":77,"q":"Who most likely is the listener?","qvi":"Người nghe nhiều khả năng là ai?","opts":["A travel agent","An administrative assistant","A flight attendant","A security guard"],"vi":["Nhân viên đại lý du lịch","Trợ lý hành chính","Tiếp viên hàng không","Nhân viên bảo vệ"],"ans":"B","xp":"Người nói để quên số điện thoại \"on my office desk\" và nhờ: \"I'll need you to go into the office and text me with the number.\" → người nghe là người hỗ trợ công việc văn phòng cho anh, tức trợ lý hành chính → (B)."},{"n":78,"q":"Why does the speaker say, \"I know this is inconvenient\"?","qvi":"Tại sao người nói nói \"Tôi biết việc này gây bất tiện\"?","opts":["To suggest a deadline extension","To report on an additional cost","To offer an alternative solution","To apologize for a request"],"vi":["Để đề xuất gia hạn thời hạn","Để báo cáo về một khoản chi phí phát sinh","Để đưa ra một giải pháp thay thế","Để xin lỗi vì một lời nhờ vả"],"ans":"D","xp":"Câu hỏi hàm ý. Ngay trước đó người nói nhờ: \"I'll need you to go into the office and text me with the number.\" (vào văn phòng vào sáng thứ Bảy) rồi nói \"I know this is inconvenient\" → anh xin lỗi vì đã nhờ việc gây phiền → (D)."},{"n":79,"q":"What will the speaker do when he arrives in San Diego?","qvi":"Người nói sẽ làm gì khi đến San Diego?","opts":["Retrieve his messages","Check in to a hotel","Change a flight reservation","Visit a company office"],"vi":["Xem tin nhắn của mình","Nhận phòng khách sạn","Đổi vé máy bay đã đặt","Ghé văn phòng công ty"],"ans":"A","xp":"Người nói: \"I'll check my messages once I land in San Diego.\"\n'land' (hạ cánh) = 'arrives'; 'check my messages' = 'Retrieve his messages' (xem tin nhắn) → (A)."}],"a":"E24-T05-77-79.mp3"},{"ns":[80,82],"script":[["","Hi, everyone! Thanks for watching today. If you're new to my channel, you should know that my videos focus on ways that we can repurpose common objects so that they don't end up in landfills. In this video, you'll learn how to make candles from old and leftover crayons. Your first step is to collect the items you'll need. You may already have some old crayons around the house, or you can ask your friends and neighbors for theirs. I'll be covering a lot of steps, but don't worry, a full written version of the instructions is available on my Web site. I recommend downloading those later for future reference.","Chào mọi người! Cảm ơn các bạn đã xem hôm nay. Nếu bạn mới đến với kênh của mình, bạn nên biết rằng các video của mình tập trung vào những cách tái sử dụng đồ vật thông thường vào mục đích khác để chúng không bị vứt vào bãi rác. Trong video này, các bạn sẽ học cách làm nến từ những cây bút sáp màu cũ và còn thừa. Bước đầu tiên là thu gom những thứ bạn cần. Có thể bạn đã có sẵn vài cây bút sáp cũ trong nhà, hoặc bạn có thể xin bạn bè và hàng xóm. Mình sẽ trình bày rất nhiều bước, nhưng đừng lo, bản hướng dẫn đầy đủ dạng văn bản có trên trang web của mình. Mình khuyên các bạn sau đó nên tải về để tham khảo sau này."]],"qs":[{"n":80,"q":"What does the speaker say her videos are usually about?","qvi":"Người nói cho biết video của cô thường nói về điều gì?","opts":["How to plan trips","How to reuse items","How to organize closets","How to draw landscapes"],"vi":["Cách lên kế hoạch du lịch","Cách tái sử dụng đồ vật","Cách sắp xếp tủ quần áo","Cách vẽ phong cảnh"],"ans":"B","xp":"Người nói: \"my videos focus on ways that we can repurpose common objects so that they don't end up in landfills.\"\n'repurpose common objects' (dùng đồ vật thông thường vào mục đích mới) = 'reuse items' → (B)."},{"n":81,"q":"What first step does the speaker mention?","qvi":"Người nói đề cập bước đầu tiên là gì?","opts":["Writing a list","Finding coupons","Gathering supplies","Looking at images online"],"vi":["Viết một danh sách","Tìm phiếu giảm giá","Thu gom vật liệu","Xem hình ảnh trên mạng"],"ans":"C","xp":"Người nói: \"Your first step is to collect the items you'll need.\"\n'collect the items' = 'Gathering supplies' (thu gom vật liệu) → (C)."},{"n":82,"q":"According to the speaker, what can the listeners do on a Web site?","qvi":"Theo người nói, người nghe có thể làm gì trên trang web?","opts":["Enter a contest","Subscribe to a video channel","Submit some photographs","Download some instructions"],"vi":["Tham gia một cuộc thi","Đăng ký theo dõi một kênh video","Gửi một số ảnh","Tải về bản hướng dẫn"],"ans":"D","xp":"Người nói: \"a full written version of the instructions is available on my Web site. I recommend downloading those later\" → người nghe có thể tải bản hướng dẫn trên trang web → (D)."}],"a":"E24-T05-80-82.mp3"},{"ns":[83,85],"script":[["","Thank you all for coming to this press conference. As you know, the Grand Falls Bridge improvement work has been underway for almost a year. We're nearing the final stage of sanding and painting the newly built portions. I know the fishing community has expressed concern over the potential environmental impact of this project on our local marine life. Well, all required studies were conducted a year ago. I'll take some questions now. After that, our special-events coordinator will discuss the bridge-opening ceremony that's being planned.","Cảm ơn tất cả quý vị đã đến dự buổi họp báo này. Như quý vị đã biết, công trình cải tạo cầu Grand Falls đã được tiến hành gần một năm nay. Chúng tôi sắp đến giai đoạn cuối là chà nhám và sơn những phần mới xây. Tôi biết cộng đồng ngư dân đã bày tỏ lo ngại về tác động môi trường có thể có của dự án này đối với sinh vật biển ở địa phương. Vâng, tất cả các nghiên cứu bắt buộc đã được thực hiện từ một năm trước. Bây giờ tôi sẽ nhận một vài câu hỏi. Sau đó, điều phối viên sự kiện đặc biệt của chúng tôi sẽ trình bày về lễ thông cầu đang được lên kế hoạch."]],"qs":[{"n":83,"q":"What is the speech mainly about?","qvi":"Bài phát biểu chủ yếu nói về điều gì?","opts":["A financial report","A round of promotions","A product prototype","A construction project"],"vi":["Một báo cáo tài chính","Một đợt thăng chức","Một sản phẩm mẫu","Một dự án xây dựng"],"ans":"D","xp":"Người nói: \"the Grand Falls Bridge improvement work has been underway for almost a year\" và nói về giai đoạn chà nhám, sơn phần mới xây → bài nói về công trình cải tạo cầu = 'A construction project' → (D)."},{"n":84,"q":"Why does the speaker say, \"all required studies were conducted a year ago\"?","qvi":"Tại sao người nói nói \"tất cả các nghiên cứu bắt buộc đã được thực hiện từ một năm trước\"?","opts":["To correct a timeline error","To provide reassurance","To deny responsibility for a problem","To argue that a new study is needed"],"vi":["Để sửa một lỗi trong lịch trình","Để trấn an","Để chối bỏ trách nhiệm về một vấn đề","Để lập luận rằng cần một nghiên cứu mới"],"ans":"B","xp":"Câu hỏi hàm ý. Ngay trước đó người nói nhắc: \"the fishing community has expressed concern over the potential environmental impact\" (ngư dân lo ngại về tác động môi trường). Nói rằng mọi nghiên cứu cần thiết đã được làm từ một năm trước là để trấn an họ, không cần lo lắng → (B)."},{"n":85,"q":"What will the next speaker discuss?","qvi":"Người nói tiếp theo sẽ trình bày về điều gì?","opts":["A job fair","A school opening","A ceremony","A sporting event"],"vi":["Một hội chợ việc làm","Lễ khai trương một trường học","Một buổi lễ","Một sự kiện thể thao"],"ans":"C","xp":"Người nói: \"After that, our special-events coordinator will discuss the bridge-opening ceremony that's being planned.\" → người nói tiếp theo sẽ trình bày về lễ thông cầu, tức một buổi lễ → (C)."}],"a":"E24-T05-83-85.mp3"},{"ns":[86,88],"script":[["","Hello, Mr. Smith. I hope you're getting settled into your office space in our building. I'm calling about some large packages that arrived for your company last week. We're keeping them for you in the storage room downstairs. The lease agreement says management will hold packages for five days. It's been ten days. Please give me a call and let me know when you can come down to claim them so I can be there to open the storage room door for you.","Xin chào anh Smith. Tôi hy vọng anh đang dần ổn định ở văn phòng trong tòa nhà của chúng tôi. Tôi gọi về mấy kiện hàng lớn được gửi đến cho công ty anh vào tuần trước. Chúng tôi đang giữ chúng cho anh trong phòng kho ở tầng dưới. Hợp đồng thuê ghi rằng ban quản lý sẽ giữ bưu kiện trong năm ngày. Đã mười ngày rồi. Vui lòng gọi cho tôi và cho tôi biết khi nào anh có thể xuống nhận để tôi có mặt mở cửa phòng kho cho anh."]],"qs":[{"n":86,"q":"Who most likely is the speaker?","qvi":"Người nói nhiều khả năng là ai?","opts":["A salesperson","A government official","An interior designer","A building manager"],"vi":["Nhân viên bán hàng","Viên chức chính phủ","Nhà thiết kế nội thất","Người quản lý tòa nhà"],"ans":"D","xp":"Người nói: \"I hope you're getting settled into your office space in our building\" và nói đang giữ bưu kiện trong phòng kho, sẽ mở cửa phòng kho → người nói là quản lý tòa nhà → (D)."},{"n":87,"q":"Why does the speaker say, \"It's been ten days\"?","qvi":"Tại sao người nói nói \"Đã mười ngày rồi\"?","opts":["To explain an expense","To point out a problem","To make an offer","To thank a colleague"],"vi":["Để giải thích một khoản chi phí","Để chỉ ra một vấn đề","Để đưa ra một lời đề nghị","Để cảm ơn một đồng nghiệp"],"ans":"B","xp":"Câu hỏi hàm ý. Ngay trước đó: \"The lease agreement says management will hold packages for five days.\" (hợp đồng chỉ giữ hàng 5 ngày). Nói 'đã 10 ngày rồi' là để chỉ ra vấn đề: hàng đã bị giữ quá thời hạn → (B)."},{"n":88,"q":"What does the speaker offer to do?","qvi":"Người nói đề nghị làm gì?","opts":["Open the door to a room","Reset a password","Send a copy of a document","Refund a payment"],"vi":["Mở cửa một căn phòng","Đặt lại mật khẩu","Gửi bản sao một tài liệu","Hoàn lại một khoản tiền"],"ans":"A","xp":"Người nói: \"so I can be there to open the storage room door for you.\" → mở cửa phòng kho = 'Open the door to a room' → (A)."}],"a":"E24-T05-86-88.mp3"},{"ns":[89,91],"script":[["","Our next story concerns Ferndale Valley. It's well-known that the area is one of the windiest locations in the region, and one company would like to take advantage of that natural energy source. Breeze Capture hopes to install dozens of wind turbines by the end of next year. The company is looking for local farmers who are interested in leasing some of their land for the project. In addition to being paid for the land use, participants will also be compensated for the energy that is generated by the turbines. For more information, e-mail info@breezecapture.com.","Bản tin tiếp theo của chúng tôi liên quan đến Thung lũng Ferndale. Ai cũng biết khu vực này là một trong những nơi lộng gió nhất vùng, và một công ty muốn tận dụng nguồn năng lượng tự nhiên đó. Công ty Breeze Capture hy vọng lắp đặt hàng chục tua-bin gió trước cuối năm sau. Công ty đang tìm kiếm những nông dân địa phương quan tâm đến việc cho thuê một phần đất của họ cho dự án. Ngoài việc được trả tiền sử dụng đất, những người tham gia còn được trả tiền cho phần năng lượng do các tua-bin tạo ra. Để biết thêm thông tin, hãy gửi e-mail đến info@breezecapture.com."]],"qs":[{"n":89,"q":"What is mentioned about Ferndale Valley?","qvi":"Điều gì được nhắc đến về Thung lũng Ferndale?","opts":["It is heavily forested.","It attracts many tourists.","It is developing quickly.","It is very windy."],"vi":["Nơi đó có nhiều rừng rậm.","Nơi đó thu hút nhiều khách du lịch.","Nơi đó đang phát triển nhanh.","Nơi đó có rất nhiều gió."],"ans":"D","xp":"Người nói: \"It's well-known that the area is one of the windiest locations in the region\".\n'one of the windiest locations' (một trong những nơi lộng gió nhất) = 'It is very windy' → (D)."},{"n":90,"q":"Who will participate in a project?","qvi":"Ai sẽ tham gia vào một dự án?","opts":["Biologists","Farmers","Airline pilots","Real estate agents"],"vi":["Các nhà sinh vật học","Nông dân","Phi công","Nhân viên môi giới bất động sản"],"ans":"B","xp":"Người nói: \"The company is looking for local farmers who are interested in leasing some of their land for the project.\" → nông dân sẽ tham gia dự án → (B)."},{"n":91,"q":"What will the participants receive?","qvi":"Những người tham gia sẽ nhận được gì?","opts":["Tickets to an industry event","Technical assistance","Financial compensation","Advertising advice"],"vi":["Vé dự một sự kiện của ngành","Hỗ trợ kỹ thuật","Khoản bồi hoàn tài chính (tiền)","Tư vấn quảng cáo"],"ans":"C","xp":"Người nói: \"In addition to being paid for the land use, participants will also be compensated for the energy...\" → họ được trả tiền.\n'being paid', 'be compensated' = 'Financial compensation' → (C)."}],"a":"E24-T05-89-91.mp3"},{"ns":[92,94],"script":[["","Hello, Mr. Kimura. I'm calling from Feras Portable Storage. You recently ordered a container to store and move your household belongings in. I'm calling to confirm that your container will be delivered tomorrow morning at nine o'clock. The driver will place it in your driveway. After the delivery, if you could, please complete the customer feedback survey that we'll e-mail you. It will help us to improve our service. Thanks.","Xin chào ông Kimura. Tôi gọi từ công ty Kho chứa Di động Feras. Gần đây ông đã đặt một thùng container để chứa và vận chuyển đồ đạc gia đình. Tôi gọi để xác nhận rằng thùng container của ông sẽ được giao vào 9 giờ sáng mai. Tài xế sẽ đặt nó ở lối xe vào nhà ông. Sau khi nhận hàng, nếu được, xin ông vui lòng hoàn thành bản khảo sát ý kiến khách hàng mà chúng tôi sẽ gửi qua e-mail. Nó sẽ giúp chúng tôi cải thiện dịch vụ. Cảm ơn ông."]],"qs":[{"n":92,"q":"What kind of business does the speaker work for?","qvi":"Người nói làm việc cho loại hình doanh nghiệp nào?","opts":["A construction firm","A landscaping service","A storage company","An auto repair shop"],"vi":["Một công ty xây dựng","Một dịch vụ cảnh quan","Một công ty kho chứa","Một tiệm sửa xe ô tô"],"ans":"C","xp":"Người nói: \"I'm calling from Feras Portable Storage. You recently ordered a container to store and move your household belongings in.\" → người nói làm cho công ty cho thuê kho chứa → (C)."},{"n":93,"q":"Why is the speaker calling?","qvi":"Tại sao người nói gọi điện?","opts":["To apologize for a cancellation","To confirm a delivery","To share a price quote","To update some contact information"],"vi":["Để xin lỗi vì việc hủy","Để xác nhận việc giao hàng","Để gửi báo giá","Để cập nhật thông tin liên lạc"],"ans":"B","xp":"Người nói: \"I'm calling to confirm that your container will be delivered tomorrow morning at nine o'clock.\" → gọi để xác nhận giao hàng → (B)."},{"n":94,"q":"What does the speaker ask the listener to do?","qvi":"Người nói yêu cầu người nghe làm gì?","opts":["Purchase a warranty","Complete a survey","Clean up an area","Apply for a permit"],"vi":["Mua gói bảo hành","Hoàn thành một bản khảo sát","Dọn dẹp một khu vực","Xin giấy phép"],"ans":"B","xp":"Người nói: \"please complete the customer feedback survey that we'll e-mail you\" → (B)."}],"a":"E24-T05-92-94.mp3"},{"ns":[95,97],"script":[["","This is the custodial staff's cabinet for cleaning supplies. As part of your training, you'll be expected to learn which cleaning solutions are used for different surfaces in the hotel, such as carpet and tile flooring. The spray bottle on the top shelf, Baxlon, is for glass surfaces. The product directly under the spray bottle is brand new. It was just released this month, and it's excellent for polishing furniture. Oh, and every Tuesday at one o'clock, a delivery truck brings any supplies that we're low on. Don't forget to check that.","Đây là tủ đựng dụng cụ vệ sinh của nhân viên tạp vụ. Trong khóa đào tạo, các bạn sẽ phải học loại dung dịch tẩy rửa nào được dùng cho từng loại bề mặt khác nhau trong khách sạn, chẳng hạn như thảm và sàn lát gạch. Bình xịt ở kệ trên cùng, Baxlon, dùng cho bề mặt kính. Sản phẩm nằm ngay bên dưới bình xịt là hàng mới hoàn toàn. Nó vừa được tung ra tháng này và rất tốt để đánh bóng đồ nội thất. À, và mỗi thứ Ba lúc một giờ, một xe tải giao hàng sẽ mang đến những vật dụng mà chúng ta sắp hết. Đừng quên kiểm tra việc đó nhé."]],"qs":[{"n":95,"q":"What is the purpose of the talk?","qvi":"Mục đích của bài nói là gì?","opts":["To discuss a schedule","To consider changing suppliers","To train employees","To develop an inventory system"],"vi":["Để bàn về một lịch trình","Để cân nhắc việc đổi nhà cung cấp","Để đào tạo nhân viên","Để xây dựng một hệ thống quản lý hàng tồn kho"],"ans":"C","xp":"Người nói giới thiệu tủ đồ vệ sinh và nói: \"As part of your training, you'll be expected to learn which cleaning solutions are used for different surfaces\" → bài nói nhằm đào tạo nhân viên → (C)."},{"n":96,"q":"Look at the graphic. Which product does the speaker say is new?","qvi":"Hãy nhìn vào hình. Người nói cho biết sản phẩm nào là sản phẩm mới?","opts":["Klennlee","Baxlon","Z-Factor","Clean Sure"],"vi":["Klennlee","Baxlon","Z-Factor","Clean Sure"],"ans":"D","xp":"Người nói: \"The spray bottle on the top shelf, Baxlon... The product directly under the spray bottle is brand new.\" Trên hình, sản phẩm ngay dưới bình xịt Baxlon là Clean Sure → (D)."},{"n":97,"q":"What happens at one o'clock on Tuesdays?","qvi":"Điều gì diễn ra lúc một giờ vào các ngày thứ Ba?","opts":["An expense report is due.","A work shift begins.","A staff meeting is held.","A delivery arrives."],"vi":["Phải nộp báo cáo chi phí.","Một ca làm việc bắt đầu.","Một cuộc họp nhân viên được tổ chức.","Một chuyến hàng được giao đến."],"ans":"D","xp":"Người nói: \"every Tuesday at one o'clock, a delivery truck brings any supplies that we're low on.\" → có xe tải giao hàng đến = 'A delivery arrives' → (D)."}],"a":"E24-T05-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","Welcome back to this professional development workshop. We'll continue from where we left off in our discussion on advertising through social media using videos, and we'll end today's meeting by performing a group task. Last week, we discussed the planning phase for a video marketing campaign. Today, we'll move on to the production phase. During this phase, you'll need to ensure that high-quality equipment is used for lighting and camera work and that you have the best video editors you can get for the job. We're very lucky to have an expert here today to talk about her experience with the process. Please give your attention to Usha Madan.","Chào mừng các bạn quay lại với hội thảo phát triển chuyên môn này. Chúng ta sẽ tiếp tục từ chỗ đã dừng lại trong phần thảo luận về quảng cáo qua mạng xã hội bằng video, và chúng ta sẽ kết thúc buổi hôm nay bằng một bài tập nhóm. Tuần trước, chúng ta đã bàn về giai đoạn lập kế hoạch cho một chiến dịch tiếp thị bằng video. Hôm nay, chúng ta sẽ chuyển sang giai đoạn sản xuất. Trong giai đoạn này, các bạn cần đảm bảo sử dụng thiết bị chất lượng cao cho ánh sáng và quay phim, và có được những người biên tập video giỏi nhất cho công việc. Chúng ta rất may mắn hôm nay có một chuyên gia ở đây để chia sẻ kinh nghiệm của cô ấy về quy trình này. Xin mời các bạn chú ý lắng nghe cô Usha Madan."]],"qs":[{"n":98,"q":"What is the topic of the course?","qvi":"Chủ đề của khóa học là gì?","opts":["Marketing","Investing","Documentary filmmaking","Software development"],"vi":["Tiếp thị","Đầu tư","Làm phim tài liệu","Phát triển phần mềm"],"ans":"A","xp":"Người nói: \"our discussion on advertising through social media using videos\" và \"Last week, we discussed the planning phase for a video marketing campaign.\" → khóa học về quảng cáo, tiếp thị → (A).\n(C) có nhắc đến video nhưng không phải làm phim tài liệu."},{"n":99,"q":"Look at the graphic. Which step will be discussed today?","qvi":"Hãy nhìn vào hình. Bước nào sẽ được thảo luận hôm nay?","opts":["Step 1","Step 2","Step 3","Step 4"],"vi":["Bước 1","Bước 2","Bước 3","Bước 4"],"ans":"C","xp":"Người nói: \"Today, we'll move on to the production phase.\" Trên sơ đồ, Production (sản xuất) là Step 3 → (C)."},{"n":100,"q":"What will the listeners do next?","qvi":"Người nghe sẽ làm gì tiếp theo?","opts":["Read a handout","Watch a video","Take a coffee break","Listen to a guest speaker"],"vi":["Đọc tài liệu phát tay","Xem một video","Nghỉ giải lao uống cà phê","Nghe một diễn giả khách mời"],"ans":"D","xp":"Người nói: \"We're very lucky to have an expert here today to talk about her experience... Please give your attention to Usha Madan.\" → tiếp theo người nghe sẽ nghe chuyên gia khách mời nói chuyện → (D)."}],"a":"E24-T05-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"After upgrading to Pro Data Whiz, our clients began ------- problems with spreadsheets.","opts":["has","had","have","having"],"ans":"D","xp":"Từ loại/dạng động từ: sau 'begin' dùng V-ing hoặc to V (begin doing / begin to do). Trong các lựa chọn chỉ có (D) having là phù hợp. (A) has, (B) had, (C) have là động từ chia thì, không đứng sau 'began' được.\nDịch: Sau khi nâng cấp lên Pro Data Whiz, khách hàng của chúng tôi bắt đầu gặp sự cố với bảng tính."},{"n":102,"q":"Requests for additional days off are ------- by Ms. Chung in Human Resources.","opts":["approved","dropped","reached","reminded"],"ans":"A","xp":"Từ vựng (bị động 'are + V3 + by'): Yêu cầu nghỉ thêm ngày thì được 'phê duyệt' → (A) approved (được phê duyệt). (B) dropped: bị bỏ/rơi; (C) reached: được đạt tới/liên lạc được; (D) reminded: được nhắc nhở (dùng cho người).\nDịch: Các yêu cầu xin thêm ngày nghỉ được cô Chung ở phòng Nhân sự phê duyệt."},{"n":103,"q":"The programmers have a list of changes ------- the next software update.","opts":["between","of","for","above"],"ans":"C","xp":"Giới từ: 'danh sách thay đổi DÀNH CHO bản cập nhật tới' → (C) for (cho, dành cho). (A) between: giữa hai thứ; (B) of: của; (D) above: phía trên — đều không hợp nghĩa.\nDịch: Các lập trình viên có một danh sách thay đổi cho bản cập nhật phần mềm tiếp theo."},{"n":104,"q":"Let Farida Banquet Service ------- professional catering for your important corporate events.","opts":["providing","provide","provides","to provide"],"ans":"B","xp":"Cấu trúc: let + tân ngữ + động từ nguyên mẫu KHÔNG 'to' (let somebody do something). → (B) provide. (A) providing là V-ing, (C) provides đã chia, (D) to provide có 'to' → sai.\nDịch: Hãy để Dịch vụ Tiệc Farida cung cấp dịch vụ ăn uống chuyên nghiệp cho các sự kiện quan trọng của công ty bạn."},{"n":105,"q":"Using various innovative techniques, Boyd Industries has improved the ------- of its tiles.","opts":["closure","product","quality","method"],"ans":"C","xp":"Từ vựng: 'cải thiện ------- của gạch lát' → hợp nghĩa nhất là 'chất lượng' → (C) quality. (A) closure: sự đóng cửa; (B) product: sản phẩm (gạch đã là sản phẩm rồi); (D) method: phương pháp (gạch không có 'phương pháp').\nDịch: Bằng nhiều kỹ thuật cải tiến khác nhau, Boyd Industries đã nâng cao chất lượng gạch lát của mình."},{"n":106,"q":"------- of all cosmetics are final, and refunds will not be given under any circumstances.","opts":["Sale","Sales","Sells","Selling"],"ans":"B","xp":"Từ loại + hòa hợp chủ-vị: chỗ trống làm chủ ngữ, động từ là 'are' (số nhiều) → cần danh từ số nhiều → (B) Sales (các giao dịch bán). 'Sales are final' = hàng đã bán không đổi trả. (A) Sale số ít không hợp 'are'; (C) Sells là động từ; (D) Selling (V-ing làm chủ ngữ) đi với động từ số ít.\nDịch: Tất cả mỹ phẩm đã bán đều không được đổi trả, và sẽ không hoàn tiền trong bất kỳ trường hợp nào."},{"n":107,"q":"If you have already submitted your response, no ------- action is required.","opts":["bright","further","previous","average"],"ans":"B","xp":"Từ vựng (tính từ): 'no further action is required' = không cần làm gì thêm → (B) further (thêm, tiếp theo). (A) bright: sáng; (C) previous: trước đó; (D) average: trung bình — không hợp nghĩa.\nDịch: Nếu bạn đã gửi phản hồi rồi thì không cần thực hiện thêm thao tác nào nữa."},{"n":108,"q":"Ms. Sieglak stated that the app design was based on ------- own research.","opts":["she","hers","her","herself"],"ans":"C","xp":"Đại từ: trước 'own + danh từ' phải dùng tính từ sở hữu (my/your/her... own) → (C) her. (A) she là chủ ngữ; (B) hers là đại từ sở hữu (đứng một mình); (D) herself là đại từ phản thân.\nDịch: Cô Sieglak cho biết thiết kế ứng dụng dựa trên nghiên cứu của chính cô ấy."},{"n":109,"q":"------- the organization has doubled its outreach efforts, it has yet to see an increase in new clients.","opts":["Until","Because","Although","Therefore"],"ans":"C","xp":"Liên từ: hai mệnh đề trái ngược nhau (đã tăng gấp đôi nỗ lực nhưng vẫn chưa thấy khách mới tăng) → (C) Although (mặc dù). (A) Until: cho đến khi; (B) Because: bởi vì (quan hệ nguyên nhân, không hợp); (D) Therefore là trạng từ 'do đó', không nối hai mệnh đề được.\nDịch: Mặc dù tổ chức đã tăng gấp đôi nỗ lực tiếp cận cộng đồng, họ vẫn chưa thấy lượng khách hàng mới tăng lên."},{"n":110,"q":"Starting on October 8, ------- board of education meetings will be streamed live on the school district's Web site.","opts":["all","so","that","to"],"ans":"A","xp":"Từ hạn định: trước cụm danh từ số nhiều 'board of education meetings' cần từ hạn định → (A) all (tất cả). (B) so: vì vậy/rất; (C) that đi với danh từ số ít (that meeting); (D) to là giới từ, không hợp.\nDịch: Bắt đầu từ ngày 8 tháng 10, tất cả các cuộc họp của hội đồng giáo dục sẽ được phát trực tiếp trên trang web của khu học chánh."},{"n":111,"q":"The hairstylists at Urbanite Salon have ------- experience working with a variety of hair products.","opts":["considers","considerable","considerate","considering"],"ans":"B","xp":"Từ loại + từ vựng: trước danh từ 'experience' cần tính từ. (B) considerable = đáng kể, nhiều; (C) considerate = chu đáo, ân cần (dùng cho người) → chọn (B). (A) considers là động từ; (D) considering là V-ing/giới từ.\nDịch: Các thợ làm tóc ở Urbanite Salon có kinh nghiệm đáng kể trong việc sử dụng nhiều loại sản phẩm tóc."},{"n":112,"q":"Both candidates are ------- suitable for the assistant manager position.","opts":["permanently","promptly","equally","gradually"],"ans":"C","xp":"Từ vựng (trạng từ): 'Both candidates' (cả hai ứng viên) → 'phù hợp NGANG NHAU' → (C) equally. (A) permanently: vĩnh viễn; (B) promptly: nhanh chóng, đúng giờ; (D) gradually: dần dần.\nDịch: Cả hai ứng viên đều phù hợp ngang nhau cho vị trí trợ lý quản lý."},{"n":113,"q":"With the acquisition of Bloom Circuit, Wellstrom Hardware has ------- expanded its offerings and services.","opts":["greater","greatness","great","greatly"],"ans":"D","xp":"Từ loại: chỗ trống nằm giữa 'has' và động từ V3 'expanded' → cần trạng từ bổ nghĩa cho động từ → (D) greatly (rất nhiều, đáng kể). (A) greater, (C) great là tính từ; (B) greatness là danh từ.\nDịch: Với việc mua lại Bloom Circuit, Wellstrom Hardware đã mở rộng đáng kể các sản phẩm và dịch vụ của mình."},{"n":114,"q":"Please note that file names should not ------- capital letters or spaces.","opts":["differ","contain","match","pick"],"ans":"B","xp":"Từ vựng: 'tên tệp không nên CHỨA chữ in hoa hoặc khoảng trắng' → (B) contain (chứa). (A) differ: khác biệt (differ from); (C) match: khớp với; (D) pick: chọn.\nDịch: Xin lưu ý rằng tên tệp không được chứa chữ in hoa hoặc khoảng trắng."},{"n":115,"q":"The Sun-Tech ceiling fan has received more than 15,000 five-star reviews from ------- customers.","opts":["satisfied","checked","adjusted","allowed"],"ans":"A","xp":"Từ vựng (tính từ trước danh từ): đánh giá 5 sao đến từ khách hàng 'hài lòng' → (A) satisfied. (B) checked: đã được kiểm tra; (C) adjusted: đã được điều chỉnh; (D) allowed: được cho phép.\nDịch: Quạt trần Sun-Tech đã nhận được hơn 15.000 đánh giá năm sao từ những khách hàng hài lòng."},{"n":116,"q":"Please ------- the Returns section of our Web site if you are unhappy with any part of your order.","opts":["visit","visits","visited","visiting"],"ans":"A","xp":"Câu mệnh lệnh: 'Please + động từ nguyên mẫu' → (A) visit. (B) visits, (C) visited, (D) visiting đều không dùng sau 'Please' trong câu mệnh lệnh.\nDịch: Vui lòng truy cập mục Trả hàng trên trang web của chúng tôi nếu bạn không hài lòng với bất kỳ phần nào trong đơn hàng."},{"n":117,"q":"Ito Auto Group is offering excellent ------- on pre-owned vehicles this month.","opts":["trips","reasons","customs","deals"],"ans":"D","xp":"Từ vựng: 'offer excellent deals on ...' = đưa ra ưu đãi tuyệt vời cho ... → (D) deals (ưu đãi, giao dịch giá tốt). (A) trips: chuyến đi; (B) reasons: lý do; (C) customs: phong tục/hải quan.\nDịch: Tập đoàn Ô tô Ito đang đưa ra những ưu đãi tuyệt vời cho xe đã qua sử dụng trong tháng này."},{"n":118,"q":"Product prices are influenced ------- such factors as consumer demand and retail competition.","opts":["by","under","those","nearly"],"ans":"A","xp":"Giới từ trong câu bị động: 'be influenced BY ...' = bị ảnh hưởng bởi → (A) by. (B) under: dưới; (C) those: những cái đó (đại từ); (D) nearly: gần như (trạng từ).\nDịch: Giá sản phẩm bị ảnh hưởng bởi các yếu tố như nhu cầu tiêu dùng và sự cạnh tranh bán lẻ."},{"n":119,"q":"Monmouth Enterprises will be ------- prefabricated houses online starting on April 1.","opts":["predicting","passing","retaining","marketing"],"ans":"D","xp":"Từ vựng: 'sẽ tiếp thị/bán nhà lắp ghép trực tuyến' → (D) marketing (tiếp thị, quảng bá bán). (A) predicting: dự đoán; (B) passing: đi qua/chuyển; (C) retaining: giữ lại.\nDịch: Monmouth Enterprises sẽ bắt đầu tiếp thị nhà lắp ghép sẵn trên mạng kể từ ngày 1 tháng 4."},{"n":120,"q":"All employees should familiarize ------- with the company's policies and procedures.","opts":["their","them","theirs","themselves"],"ans":"D","xp":"Đại từ phản thân: 'familiarize oneself with' = tự làm quen với; chủ ngữ 'All employees' và tân ngữ là cùng một đối tượng → (D) themselves. (A) their: tính từ sở hữu; (B) them: tân ngữ (chỉ người khác); (C) theirs: đại từ sở hữu.\nDịch: Tất cả nhân viên nên tự làm quen với các chính sách và quy trình của công ty."},{"n":121,"q":"Custom furniture orders require a 50 percent deposit ------- the time of the order.","opts":["as","off","into","at"],"ans":"D","xp":"Giới từ: cụm cố định 'at the time of' = vào thời điểm → (D) at. (A) as: như/khi; (B) off: rời khỏi; (C) into: vào trong.\nDịch: Đơn hàng nội thất đặt làm riêng yêu cầu đặt cọc 50% vào thời điểm đặt hàng."},{"n":122,"q":"We are planning a ------- for the Klemner Corporation's twentieth anniversary.","opts":["celebration","celebrated","celebrity","celebrate"],"ans":"A","xp":"Từ loại + từ vựng: sau mạo từ 'a' cần danh từ. (A) celebration: lễ kỷ niệm; (C) celebrity: người nổi tiếng → hợp nghĩa là (A). (B) celebrated là V3/tính từ; (D) celebrate là động từ.\nDịch: Chúng tôi đang lên kế hoạch tổ chức lễ kỷ niệm 20 năm thành lập Tập đoàn Klemner."},{"n":123,"q":"Though she lacks political experience, Ms. Diaz has been ------- impressive in her first term as mayor.","opts":["quite","soon","ever","next"],"ans":"A","xp":"Trạng từ chỉ mức độ: đứng trước tính từ 'impressive' cần trạng từ mức độ → (A) quite (khá, rất). (B) soon: sớm; (C) ever: từng; (D) next: tiếp theo — không bổ nghĩa mức độ cho tính từ.\nDịch: Dù thiếu kinh nghiệm chính trị, bà Diaz đã thể hiện khá ấn tượng trong nhiệm kỳ thị trưởng đầu tiên."},{"n":124,"q":"The university library usually acquires ------- copies of best-selling books to meet students' demand.","opts":["multiply","multiple","multiples","multiplicity"],"ans":"B","xp":"Từ loại: trước danh từ 'copies' cần tính từ → (B) multiple (nhiều). (A) multiply là động từ (nhân lên); (C) multiples, (D) multiplicity là danh từ.\nDịch: Thư viện trường đại học thường mua nhiều bản của các cuốn sách bán chạy để đáp ứng nhu cầu của sinh viên."},{"n":125,"q":"This year's conference tote bags were ------- donated by Etani Designs.","opts":["generous","generosity","generously","generosities"],"ans":"C","xp":"Từ loại: giữa 'were' và V3 'donated' (bị động) cần trạng từ → (C) generously (một cách hào phóng). (A) generous là tính từ; (B), (D) là danh từ.\nDịch: Những chiếc túi tote của hội nghị năm nay được Etani Designs hào phóng tài trợ."},{"n":126,"q":"We will be holding a ------- on Friday to honor the 30-year engineering career of Mr. Kuan.","opts":["record","share","reception","place"],"ans":"C","xp":"Từ vựng: 'hold a reception' = tổ chức tiệc chiêu đãi để vinh danh ai đó → (C) reception. (A) record: hồ sơ/kỷ lục; (B) share: phần/cổ phần; (D) place: nơi chốn.\nDịch: Chúng tôi sẽ tổ chức một buổi tiệc chiêu đãi vào thứ Sáu để vinh danh 30 năm sự nghiệp kỹ sư của ông Kuan."},{"n":127,"q":"Groove Background creates soothing playlists of instrumental music, ------- classical and jazz.","opts":["instead","including","in addition","indeed"],"ans":"B","xp":"Giới từ: sau dấu phẩy là cụm danh từ 'classical and jazz' (ví dụ cho nhạc không lời) → cần giới từ 'including' (bao gồm) → (B). (A) instead: thay vào đó; (C) in addition: ngoài ra; (D) indeed: thực vậy — đều là trạng từ, không đứng trước danh từ để liệt kê.\nDịch: Groove Background tạo ra các danh sách phát nhạc không lời êm dịu, bao gồm nhạc cổ điển và nhạc jazz."},{"n":128,"q":"Members of the finance department ------- to Mr. Chua's lecture on risk avoidance.","opts":["to be invited","inviting","invite","are invited"],"ans":"D","xp":"Thể bị động + động từ chính: câu chưa có động từ chính, và 'các thành viên' là người ĐƯỢC mời (sau chỗ trống không có tân ngữ, chỉ có 'to ...') → bị động 'are invited' → (D). (A) to be invited, (B) inviting không phải động từ chính; (C) invite là chủ động.\nDịch: Các thành viên phòng tài chính được mời tham dự bài giảng của ông Chua về phòng tránh rủi ro."},{"n":129,"q":"The board of trustees debated for hours ------- the revised hiring policies.","opts":["during","above","over","across"],"ans":"C","xp":"Giới từ: 'debate over/about something' = tranh luận về điều gì → (C) over. (A) during: trong suốt (+ khoảng thời gian/sự kiện); (B) above: phía trên; (D) across: băng qua.\nDịch: Hội đồng quản trị đã tranh luận hàng giờ liền về các chính sách tuyển dụng đã được sửa đổi."},{"n":130,"q":"The participants closely ------- the fitness instructor's movements tend to learn the proper technique more quickly.","opts":["imitate","imitations","imitative","imitating"],"ans":"D","xp":"Rút gọn mệnh đề quan hệ: câu đã có động từ chính 'tend'. Cụm 'closely ------- the ... movements' bổ nghĩa cho 'participants' = 'participants (who are) closely imitating ...' → dùng V-ing → (D) imitating. (A) imitate sẽ tạo hai động từ chính; (B) danh từ; (C) tính từ.\nDịch: Những học viên bắt chước sát các động tác của huấn luyện viên thể dục thường học được kỹ thuật đúng nhanh hơn."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following article.","passage":"<h3>Grocery Chain to Host Event</h3><p>LEIGHTON (October 8)—Ohale Foods, one of the region's largest supermarket chains, is seeking to fill almost 100 open positions. For that reason, the company is holding a <span class=\"blank\" data-n=\"131\">-------</span> event on October 20. Job opportunities exist at all fourteen of Ohale's current stores. <span class=\"blank\" data-n=\"132\">-------</span>, Ohale is seeking employees for its new Westside location, which is still under construction. <span class=\"blank\" data-n=\"133\">-------</span>.</p><p>Those who <span class=\"blank\" data-n=\"134\">-------</span> the event should bring copies of their résumé to the Grand Ballroom of the Palace Suites Hotel between 10 A.M. and 7 P.M. No appointment is required.</p>","vi":"Chuỗi cửa hàng tạp hóa tổ chức sự kiện\n\nLEIGHTON (ngày 8 tháng 10) — Ohale Foods, một trong những chuỗi siêu thị lớn nhất khu vực, đang tìm người cho gần 100 vị trí còn trống. Vì lý do đó, công ty sẽ tổ chức một sự kiện tuyển dụng vào ngày 20 tháng 10. Có cơ hội việc làm tại cả mười bốn cửa hàng hiện tại của Ohale. Ngoài ra, Ohale đang tìm nhân viên cho cửa hàng mới ở Westside, hiện vẫn đang được xây dựng. Lễ khai trương của cửa hàng này dự kiến diễn ra vào giữa tháng 11.\n\nNhững ai tham dự sự kiện nên mang theo bản sao sơ yếu lý lịch đến Phòng khiêu vũ lớn (Grand Ballroom) của Khách sạn Palace Suites trong khoảng từ 10 giờ sáng đến 7 giờ tối. Không cần đặt lịch hẹn.","qs":[{"n":131,"opts":["manufacturing","hiring","political","sporting"],"ans":"B","xp":"Từ vựng: câu trước nói công ty đang tìm người cho gần 100 vị trí ('seeking to fill almost 100 open positions'), 'For that reason' → sự kiện là sự kiện 'tuyển dụng' → (B) hiring. (A) manufacturing: sản xuất; (C) political: chính trị; (D) sporting: thể thao.\nDịch: Vì lý do đó, công ty sẽ tổ chức một sự kiện tuyển dụng vào ngày 20 tháng 10."},{"n":132,"opts":["If not","After all","Additionally","For example"],"ans":"C","xp":"Trạng từ liên kết: câu trước nói có việc làm ở 14 cửa hàng hiện tại; câu sau nói thêm còn tuyển cho cửa hàng mới ở Westside → bổ sung thông tin → (C) Additionally (ngoài ra). (A) If not: nếu không; (B) After all: suy cho cùng; (D) For example: ví dụ (cửa hàng mới không phải ví dụ của 14 cửa hàng hiện tại).\nDịch: Ngoài ra, Ohale đang tìm nhân viên cho cửa hàng mới ở Westside."},{"n":133,"opts":["Its grand opening is scheduled for mid-November.","Most applicants had prior experience.","Its appointment of Linda Okumu as its CEO has surprised analysts.","Local competitors cannot match its prices."],"ans":"A","xp":"Điền câu: câu trước nói cửa hàng Westside mới 'is still under construction' (vẫn đang xây). Câu (A) 'Its grand opening is scheduled for mid-November' (Lễ khai trương của nó dự kiến vào giữa tháng 11) nối tiếp tự nhiên — 'Its' chỉ cửa hàng mới → chọn (A). (B) nói về ứng viên ở thì quá khứ trong khi sự kiện chưa diễn ra; (C) bổ nhiệm CEO và (D) giá cả không liên quan đến đoạn văn.\n(A) Lễ khai trương của cửa hàng dự kiến vào giữa tháng 11.\n(B) Hầu hết ứng viên đã có kinh nghiệm trước đó.\n(C) Việc bổ nhiệm Linda Okumu làm CEO đã khiến giới phân tích bất ngờ.\n(D) Các đối thủ địa phương không thể cạnh tranh về giá với công ty."},{"n":134,"opts":["attending","to attend","attended","are attending"],"ans":"D","xp":"Động từ trong mệnh đề quan hệ: 'Those who -------' cần động từ chia thì cho chủ ngữ 'who' (= những người, số nhiều). Sự kiện diễn ra trong tương lai (ngày 20/10) → hiện tại tiếp diễn diễn tả dự định: 'are attending' → (D). (A) attending và (B) to attend không phải động từ chia; (C) attended là quá khứ, sai thời gian.\nDịch: Những ai sẽ tham dự sự kiện nên mang theo bản sao sơ yếu lý lịch."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following instructions.","passage":"<p>Thank you for your purchase of an Ajaz Water Filter Pitcher. It is a wonderful solution for water that tastes great! To improve the effectiveness of the Ajaz Water Filter Pitcher, we <span class=\"blank\" data-n=\"135\">-------</span> priming the filter before the first use. <span class=\"blank\" data-n=\"136\">-------</span>. Then screw the filter clockwise into the lid of the pitcher until it fits <span class=\"blank\" data-n=\"137\">-------</span>. As you use the pitcher, remember that <span class=\"blank\" data-n=\"138\">-------</span> water flow is a signal that the filter is becoming clogged and will need to be replaced soon.</p>","vi":"Cảm ơn bạn đã mua Bình lọc nước Ajaz. Đây là giải pháp tuyệt vời để có nước uống ngon! Để tăng hiệu quả của Bình lọc nước Ajaz, chúng tôi khuyên bạn nên làm ướt (mồi) lõi lọc trước lần sử dụng đầu tiên. Để làm việc này, hãy cho nước máy mát chảy qua lõi lọc trong ba phút. Sau đó vặn lõi lọc theo chiều kim đồng hồ vào nắp bình cho đến khi khít chặt. Trong quá trình sử dụng, hãy nhớ rằng dòng nước chảy yếu đi là dấu hiệu lõi lọc đang bị tắc và sẽ sớm cần thay.","qs":[{"n":135,"opts":["tried","recommend","consider","started"],"ans":"B","xp":"Thì + từ vựng: chủ ngữ 'we' trong lời hướng dẫn, đưa ra lời khuyên ở hiện tại → 'we recommend priming the filter' (chúng tôi khuyên nên mồi lõi lọc) → (B). (A) tried, (D) started là quá khứ, không hợp với lời hướng dẫn; (C) consider (cân nhắc) không hợp vì nhà sản xuất đang chỉ dẫn người dùng, không phải tự cân nhắc.\nDịch: Để tăng hiệu quả của bình lọc, chúng tôi khuyên bạn nên mồi lõi lọc trước lần dùng đầu tiên."},{"n":136,"opts":["Our filtration system will be redesigned within the next year.","Water use may be reduced by running your dishwasher less frequently.","To do this, run cool tap water through the filter for three minutes.","There are 150 liters of water in the main storage tank at all times."],"ans":"C","xp":"Điền câu: câu trước nói nên 'priming the filter' (mồi lõi lọc) trước lần dùng đầu; câu sau bắt đầu bằng 'Then screw the filter...' (Sau đó vặn lõi lọc...). Câu (C) 'To do this, run cool tap water through the filter for three minutes' giải thích cách mồi lõi lọc ('To do this' = để làm việc mồi lọc) và là bước trước 'Then' → chọn (C). (A), (B), (D) không liên quan đến các bước hướng dẫn.\n(A) Hệ thống lọc của chúng tôi sẽ được thiết kế lại trong năm tới.\n(B) Có thể giảm lượng nước sử dụng bằng cách chạy máy rửa bát ít thường xuyên hơn.\n(C) Để làm việc này, hãy cho nước máy mát chảy qua lõi lọc trong ba phút.\n(D) Luôn có 150 lít nước trong bồn chứa chính."},{"n":137,"opts":["extremely","highly","tightly","steadily"],"ans":"C","xp":"Từ vựng (trạng từ): 'vặn lõi lọc vào nắp cho đến khi nó vừa khít' → 'fits tightly' (khít chặt) → (C). (A) extremely: cực kỳ; (B) highly: rất, ở mức cao; (D) steadily: đều đặn, vững vàng.\nDịch: Sau đó vặn lõi lọc theo chiều kim đồng hồ vào nắp bình cho đến khi khít chặt."},{"n":138,"opts":["diminished","diminishes","diminish","diminishable"],"ans":"A","xp":"Từ loại: trước cụm danh từ 'water flow' cần tính từ; dùng V3 (phân từ quá khứ) 'diminished' = bị giảm đi → 'diminished water flow' = dòng nước yếu đi → (A). (B), (C) là động từ chia; (D) diminishable = có thể giảm được, không hợp nghĩa.\nDịch: Hãy nhớ rằng dòng nước chảy yếu đi là dấu hiệu lõi lọc đang bị tắc."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following policy.","passage":"<h3>Returning merchandise</h3><p>Abney Home Products is committed to providing outstanding service, and we guarantee the <span class=\"blank\" data-n=\"139\">-------</span> of all the products in our catalog. If you are not satisfied with a purchase, call our customer service line at 339-555-0177 to request a return authorization code. The service agent <span class=\"blank\" data-n=\"140\">-------</span> you for the invoice number from the package insert. <span class=\"blank\" data-n=\"141\">-------</span>. Please be aware that Abney Home Products is not <span class=\"blank\" data-n=\"142\">-------</span> for postage on merchandise returns.</p>","vi":"Trả lại hàng hóa\n\nAbney Home Products cam kết mang đến dịch vụ xuất sắc, và chúng tôi bảo đảm tình trạng (chất lượng) của tất cả sản phẩm trong danh mục. Nếu bạn không hài lòng với món hàng đã mua, hãy gọi đường dây chăm sóc khách hàng của chúng tôi theo số 339-555-0177 để yêu cầu mã cho phép trả hàng. Nhân viên dịch vụ sẽ hỏi bạn số hóa đơn trên tờ phiếu kèm trong kiện hàng. Khi gửi trả sản phẩm, hãy nhớ ghi kèm mã cho phép trả hàng. Xin lưu ý rằng Abney Home Products không chịu trách nhiệm chi trả cước bưu phí cho hàng trả lại.","qs":[{"n":139,"opts":["condition","object","explanation","preview"],"ans":"A","xp":"Từ vựng: 'chúng tôi bảo đảm ------- của tất cả sản phẩm' → hợp nghĩa là 'tình trạng (tốt)' → (A) condition. (B) object: đồ vật/mục tiêu; (C) explanation: lời giải thích; (D) preview: bản xem trước.\nDịch: Chúng tôi bảo đảm tình trạng của tất cả sản phẩm trong danh mục."},{"n":140,"opts":["asked","is asking","has asked","will ask"],"ans":"D","xp":"Thì: việc nhân viên hỏi số hóa đơn xảy ra SAU khi khách gọi điện (bước tiếp theo trong quy trình) → thì tương lai → (D) will ask. (A) asked, (C) has asked là quá khứ/hiện tại hoàn thành; (B) is asking là đang diễn ra — đều không hợp với quy trình chưa xảy ra.\nDịch: Nhân viên dịch vụ sẽ hỏi bạn số hóa đơn trên tờ phiếu kèm trong kiện hàng."},{"n":141,"opts":["Our employees have software training and are skilled at resolving problems.","To cancel a furniture delivery, please call within 24 hours of ordering.","When you send back the product, be sure to include the authorization code.","The catalog has sections for kitchen goods, lighting, appliances, and more."],"ans":"C","xp":"Điền câu: đoạn văn mô tả quy trình trả hàng: gọi điện xin 'return authorization code' → nhân viên hỏi số hóa đơn → (bước tiếp) gửi trả hàng kèm mã → câu sau nói về bưu phí trả hàng. Câu (C) 'When you send back the product, be sure to include the authorization code' nối đúng mạch (nhắc lại 'authorization code') → chọn (C). (A) về đào tạo nhân viên, (B) hủy giao đồ nội thất, (D) các mục trong danh mục đều lạc đề.\n(A) Nhân viên của chúng tôi được đào tạo phần mềm và giỏi giải quyết vấn đề.\n(B) Để hủy giao đồ nội thất, vui lòng gọi trong vòng 24 giờ sau khi đặt hàng.\n(C) Khi gửi trả sản phẩm, hãy nhớ ghi kèm mã cho phép trả hàng.\n(D) Danh mục có các mục đồ dùng nhà bếp, đèn chiếu sáng, thiết bị gia dụng và nhiều hơn nữa."},{"n":142,"opts":["responsibly","responsible","responsibility","responsibleness"],"ans":"B","xp":"Từ loại: sau 'is not' cần tính từ làm bổ ngữ; cấu trúc 'be responsible for' = chịu trách nhiệm về → (B) responsible. (A) responsibly là trạng từ; (C), (D) là danh từ.\nDịch: Xin lưu ý rằng Abney Home Products không chịu trách nhiệm về cước bưu phí cho hàng trả lại."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following memo.","passage":"<div class=\"hdr\"><p><b>To:</b> All Employees</p><p><b>From:</b> Marina Papantonio, Safety Liaison</p><p><b>Date:</b> November 12</p><p><b>Subject:</b> Safety Training</p></div><p>It is time once again for our annual safety training workshop. This year, training will focus on digital safety measures, like avoiding scams and protecting against cyberattacks. Our technology experts already have installed new programs throughout our company's information system to reduce risk. <span class=\"blank\" data-n=\"143\">-------</span>, we all need to understand how the programs work and what to do when a problem arises.</p><p>To accommodate <span class=\"blank\" data-n=\"144\">-------</span>, several workshops will be conducted throughout the upcoming week. You can register for any one of these <span class=\"blank\" data-n=\"145\">-------</span> on our company's intranet page. Just click on the link for “Safety Training.”</p><p><span class=\"blank\" data-n=\"146\">-------</span>. If you are unable to take part in any of the scheduled workshops for any reason, you must inform your supervisor.</p>","vi":"Gửi: Toàn thể nhân viên\nTừ: Marina Papantonio, Phụ trách liên lạc về an toàn\nNgày: 12 tháng 11\nChủ đề: Đào tạo an toàn\n\nĐã lại đến lúc tổ chức buổi hội thảo đào tạo an toàn hằng năm của chúng ta. Năm nay, chương trình đào tạo sẽ tập trung vào các biện pháp an toàn kỹ thuật số, như tránh lừa đảo và bảo vệ trước các cuộc tấn công mạng. Các chuyên gia công nghệ của chúng ta đã cài đặt các chương trình mới trên toàn bộ hệ thống thông tin của công ty để giảm rủi ro. Tuy nhiên, tất cả chúng ta cần hiểu các chương trình đó hoạt động như thế nào và phải làm gì khi có sự cố xảy ra.\n\nĐể tạo điều kiện cho tất cả mọi người, một số buổi hội thảo sẽ được tổ chức trong suốt tuần tới. Bạn có thể đăng ký bất kỳ buổi nào trong số này trên trang mạng nội bộ của công ty. Chỉ cần nhấp vào đường link “Safety Training” (Đào tạo an toàn).\n\nVui lòng cố gắng hết sức để đăng ký. Nếu vì bất kỳ lý do gì bạn không thể tham gia buổi hội thảo nào theo lịch, bạn phải báo cho người giám sát của mình.","qs":[{"n":143,"opts":["If so","However","Otherwise","In that case"],"ans":"B","xp":"Trạng từ liên kết: câu trước nói chuyên gia ĐÃ cài chương trình mới để giảm rủi ro; câu sau nói dù vậy mọi người VẪN cần hiểu cách chương trình hoạt động → quan hệ tương phản → (B) However (tuy nhiên). (A) If so: nếu vậy; (C) Otherwise: nếu không thì; (D) In that case: trong trường hợp đó.\nDịch: Tuy nhiên, tất cả chúng ta cần hiểu các chương trình hoạt động như thế nào và phải làm gì khi có sự cố."},{"n":144,"opts":["itself","his","whose","everyone"],"ans":"D","xp":"Đại từ: sau động từ 'accommodate' (đáp ứng, tạo điều kiện cho) cần tân ngữ; tổ chức nhiều buổi hội thảo để mọi nhân viên đều tham gia được → (D) everyone (mọi người). (A) itself: chính nó (không có danh từ nào để quy chiếu); (B) his: của anh ấy (cần danh từ theo sau); (C) whose: đại từ quan hệ.\nDịch: Để tạo điều kiện cho tất cả mọi người, một số buổi hội thảo sẽ được tổ chức trong tuần tới."},{"n":145,"opts":["sessions","positions","conferences","competitions"],"ans":"A","xp":"Từ vựng: 'any one of these -------' chỉ lại 'several workshops' ở câu trước → các 'buổi' hội thảo → (A) sessions (buổi, phiên). (B) positions: vị trí; (C) conferences: hội nghị (quy mô lớn, không phải các buổi đào tạo nội bộ); (D) competitions: cuộc thi.\nDịch: Bạn có thể đăng ký bất kỳ buổi nào trong số này trên trang mạng nội bộ của công ty."},{"n":146,"opts":["Cyberattacks are on the rise.","The training is held each summer.","Please make every effort to sign up.","Last year's program was canceled."],"ans":"C","xp":"Điền câu: đoạn cuối nói về việc tham gia: câu sau 'If you are unable to take part in any of the scheduled workshops..., you must inform your supervisor' (nếu không thể tham gia thì phải báo cấp trên). Câu (C) 'Please make every effort to sign up' (Hãy cố gắng hết sức để đăng ký) dẫn vào ý đó một cách tự nhiên → chọn (C). (A) tấn công mạng gia tăng không hợp vị trí này; (B) sai vì bản ghi nhớ ngày 12/11 và hội thảo diễn ra tuần tới (không phải mùa hè); (D) mâu thuẫn với 'annual ... once again'.\n(A) Các cuộc tấn công mạng đang gia tăng.\n(B) Khóa đào tạo được tổ chức vào mỗi mùa hè.\n(C) Vui lòng cố gắng hết sức để đăng ký.\n(D) Chương trình năm ngoái đã bị hủy."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following advertisement.","passages":["<h3>Owl and Moon</h3><p>Buy one mattress, and choose one of our beautiful rugs for free!</p><p>Use the following coupon code when you check out at owlandmoon.co.uk: ESSZRS4T.</p><p>Our mattresses are shipped directly to your home and usually arrive within one week. Try out a mattress for 90 days, and if you are not happy with it, send it back for a full refund. We also offer low-interest financing for two years on all our furniture.</p>"],"vi":"Owl and Moon\n\nMua một tấm nệm và chọn miễn phí một trong những tấm thảm đẹp của chúng tôi!\n\nHãy dùng mã giảm giá sau khi thanh toán tại owlandmoon.co.uk: ESSZRS4T.\n\nNệm của chúng tôi được giao thẳng đến nhà bạn và thường đến nơi trong vòng một tuần. Hãy dùng thử nệm trong 90 ngày, và nếu bạn không hài lòng, hãy gửi trả lại để được hoàn tiền toàn bộ. Chúng tôi cũng cung cấp gói trả góp lãi suất thấp trong hai năm cho tất cả đồ nội thất.","qs":[{"n":147,"q":"What types of products are being advertised?","qvi":"Loại sản phẩm nào đang được quảng cáo?","opts":["Camping gear","Household items","Office equipment","Automobile accessories"],"ans":"B","xp":"Câu hỏi chi tiết (chủ đề). Quảng cáo nói về \"mattress\" (nệm), \"rugs\" (thảm) và \"all our furniture\" (đồ nội thất) → đều là đồ dùng trong nhà = Household items.\n(A) Đồ cắm trại\n(B) Đồ gia dụng trong nhà\n(C) Thiết bị văn phòng\n(D) Phụ kiện ô tô"},{"n":148,"q":"What is indicated about the company?","qvi":"Điều gì được nêu về công ty?","opts":["It has been in business for two years.","It accepts product returns.","It has same-day delivery.","It has a yearly sale."],"ans":"B","xp":"Câu hỏi chi tiết. Bằng chứng: \"if you are not happy with it, send it back for a full refund\" → khách có thể gửi trả hàng = công ty chấp nhận trả hàng. (A) sai: \"two years\" là thời hạn trả góp, không phải số năm hoạt động. (C) sai: hàng thường đến \"within one week\" (trong một tuần). (D) không được nhắc.\n(A) Công ty đã kinh doanh được hai năm.\n(B) Công ty chấp nhận trả lại sản phẩm.\n(C) Công ty giao hàng trong ngày.\n(D) Công ty có đợt giảm giá hằng năm."}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Demarco Hines &lt;d.hines@worldmail.com&gt;</p><p><b>From:</b> Soon Yi Park &lt;customerservice@thebestbags.co.kr&gt;</p><p><b>Subject:</b> Item F208 (canvas overnight bag)</p><p><b>Date:</b> 19 June</p></div><p>Dear Mr. Hines,</p><p>The Best Bags canvas overnight bag you ordered is not currently available in the colour you requested. There are several options available to you.</p><p>1. Cancel your order, and we will gladly refund your money in full.</p><p>2. Select a different colour. That item is currently available in light blue, dark green, and dark gray.</p><p>3. Choose an item of equal value from our Web site or catalogue.</p><p>4. Wait until the item you ordered is back in stock in light gray. Allow three to five weeks.</p><p>Please let us know which option you prefer. We apologize for any inconvenience.</p><p>Thank you,</p><p>Soon Yi Park, Customer Service Agent</p>"],"vi":"Người nhận: Demarco Hines <d.hines@worldmail.com>\nNgười gửi: Soon Yi Park <customerservice@thebestbags.co.kr>\nTiêu đề: Mặt hàng F208 (túi du lịch qua đêm bằng vải bạt)\nNgày: 19 tháng 6\n\nKính gửi anh Hines,\n\nChiếc túi du lịch qua đêm bằng vải bạt của Best Bags mà anh đặt hiện không có sẵn màu anh yêu cầu. Anh có một vài lựa chọn sau.\n\n1. Hủy đơn hàng, và chúng tôi sẵn lòng hoàn lại toàn bộ tiền cho anh.\n\n2. Chọn màu khác. Mặt hàng đó hiện có màu xanh dương nhạt, xanh lá đậm và xám đậm.\n\n3. Chọn một mặt hàng có giá trị tương đương từ trang web hoặc danh mục sản phẩm của chúng tôi.\n\n4. Chờ đến khi mặt hàng anh đặt có hàng lại với màu xám nhạt. Vui lòng chờ từ ba đến năm tuần.\n\nXin cho chúng tôi biết anh muốn chọn phương án nào. Chúng tôi xin lỗi vì mọi sự bất tiện.\n\nXin cảm ơn,\n\nSoon Yi Park, Nhân viên Chăm sóc Khách hàng","qs":[{"n":149,"q":"What is the purpose of the e-mail?","qvi":"Mục đích của e-mail là gì?","opts":["To confirm shipment of an order","To acknowledge the return of an order","To provide alternatives for an order","To thank a customer for placing an order"],"ans":"C","xp":"Câu hỏi mục đích. Bằng chứng: \"is not currently available in the colour you requested. There are several options available to you.\" rồi liệt kê 4 phương án → e-mail đưa ra các lựa chọn thay thế cho đơn hàng. \"several options\" = \"alternatives\".\n(A) Xác nhận việc gửi hàng của một đơn hàng\n(B) Xác nhận đã nhận hàng trả lại\n(C) Đưa ra các phương án thay thế cho một đơn hàng\n(D) Cảm ơn khách hàng đã đặt hàng"},{"n":150,"q":"What color bag is currently NOT available?","qvi":"Túi màu nào hiện KHÔNG có sẵn?","opts":["The light blue one","The dark green one","The dark gray one","The light gray one"],"ans":"D","xp":"Câu hỏi chi tiết (NOT). \"That item is currently available in light blue, dark green, and dark gray\" → (A), (B), (C) đều đang có. Phương án 4: \"Wait until the item you ordered is back in stock in light gray\" → màu xám nhạt đang hết hàng.\n(A) Chiếc màu xanh dương nhạt\n(B) Chiếc màu xanh lá đậm\n(C) Chiếc màu xám đậm\n(D) Chiếc màu xám nhạt"}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Christie Moroff (9:47 A.M.)</b></p><p>Good morning, Ren. I just stopped by your office.</p></div><div class=\"msg\"><p><b>Ren Nomura (9:48 A.M.)</b></p><p>Then you already know that I am not there today.</p></div><div class=\"msg\"><p><b>Christie Moroff (9:48 A.M.)</b></p><p>Yes, your new office mate—I can’t remember her name—told me that you just started working remotely on Tuesdays. I was looking for some empty binders.</p></div><div class=\"msg\"><p><b>Ren Nomura (9:49 A.M.)</b></p><p>That’s Cheryl. I thought you had already met her. Are there any binders in the supply closet?</p></div><div class=\"msg\"><p><b>Christie Moroff (9:50 A.M.)</b></p><p>No, I just looked. Frank has ordered some more, but they won’t be in until next week. I need two or three of them now.</p></div><div class=\"msg\"><p><b>Ren Nomura (9:51 A.M.)</b></p><p>Check with Cheryl. She is really helpful.</p></div><div class=\"msg\"><p><b>Christie Moroff (9:52 A.M.)</b></p><p>OK. I will.</p></div>"],"vi":"Christie Moroff (9:47 sáng): Chào buổi sáng, Ren. Tôi vừa ghé qua văn phòng của anh.\n\nRen Nomura (9:48 sáng): Vậy chắc chị đã biết hôm nay tôi không có ở đó.\n\nChristie Moroff (9:48 sáng): Ừ, đồng nghiệp mới cùng phòng với anh—tôi không nhớ tên cô ấy—nói với tôi rằng anh vừa bắt đầu làm việc từ xa vào các ngày thứ Ba. Tôi đang tìm vài cái bìa còng trống.\n\nRen Nomura (9:49 sáng): Đó là Cheryl. Tôi tưởng chị đã gặp cô ấy rồi. Trong tủ đồ dùng văn phòng có bìa còng nào không?\n\nChristie Moroff (9:50 sáng): Không, tôi vừa xem rồi. Frank đã đặt thêm, nhưng phải tuần sau mới có. Tôi cần hai hoặc ba cái ngay bây giờ.\n\nRen Nomura (9:51 sáng): Chị hỏi Cheryl xem. Cô ấy rất nhiệt tình giúp đỡ.\n\nChristie Moroff (9:52 sáng): Được. Tôi sẽ hỏi.","qs":[{"n":151,"q":"What is suggested about Mr. Nomura?","qvi":"Điều gì được ngụ ý về anh Nomura?","opts":["He does not usually work on Tuesdays.","He shares an office with Ms. Moroff.","He recently purchased office supplies.","He works off-site one day a week."],"ans":"D","xp":"Câu hỏi suy luận. Bằng chứng: \"you just started working remotely on Tuesdays\" → anh Nomura làm việc từ xa (không ở văn phòng) vào thứ Ba hằng tuần = \"works off-site one day a week\". (A) sai: anh vẫn làm việc vào thứ Ba, chỉ là làm từ xa. (B) sai: anh chung phòng với Cheryl. (C) sai: Frank mới là người đặt mua bìa còng.\n(A) Anh ấy thường không làm việc vào thứ Ba.\n(B) Anh ấy ở chung văn phòng với chị Moroff.\n(C) Anh ấy mới mua đồ dùng văn phòng.\n(D) Anh ấy làm việc bên ngoài văn phòng một ngày mỗi tuần."},{"n":152,"q":"At 9:51 A.M., what does Mr. Nomura most likely mean when he writes, “Check with Cheryl”?","qvi":"Lúc 9:51 sáng, khi anh Nomura viết \"Check with Cheryl\" (Hãy hỏi Cheryl), nhiều khả năng ý anh ấy là gì?","opts":["Cheryl may have extra binders.","Cheryl must approve a purchase.","Cheryl will be able to locate Frank.","Cheryl knows when a delivery will arrive."],"ans":"A","xp":"Câu hỏi hàm ý. Chị Moroff nói tủ đồ không còn bìa còng và \"I need two or three of them now\" (tôi cần 2–3 cái ngay). Anh Nomura trả lời \"Check with Cheryl. She is really helpful.\" → gợi ý Cheryl có thể có sẵn bìa còng dư để cho mượn. (D) sai: chị Moroff đã biết hàng về \"next week\".\n(A) Cheryl có thể có bìa còng dư.\n(B) Cheryl phải phê duyệt một khoản mua hàng.\n(C) Cheryl sẽ tìm được Frank.\n(D) Cheryl biết khi nào hàng được giao đến."}]},{"ns":[153,154],"head":"Questions 153-154 refer to the following form.","passages":["<h3>Cortica Bank</h3><p>Please fill out the following form to open a new bank account.</p><table><tr><td><b>Is this your first account with Cortica Bank?</b> __ Yes &nbsp;<u>X</u> No</td></tr><tr><td><b>Existing account number (if applicable):</b> <u>190-37580</u></td></tr><tr><td><b>New account type:</b> __ Chequing &nbsp;<u>X</u> Savings &nbsp;__ Investment</td></tr><tr><td><b>Name:</b> <u>Frances Wilkes</u></td></tr><tr><td><b>Mailing address:</b> <u>17 Jones Street</u><br><u>North Sydney NSW 2060</u></td></tr><tr><td><b>Phone number:</b> <u>(02) 7010 8624</u></td></tr><tr><td><b>E-mail address:</b> <u>fwilkes@myemail.com.au</u></td></tr><tr><td><b>Initial deposit amount (minimum $500):</b> <u>$1,500</u></td></tr><tr><td><b>Would you like to sign up for electronic communications?</b> __ Yes &nbsp;<u>X</u> No</td></tr></table><p>If you select “Yes,” we will contact you via voice mail, e-mail, or text.<br>If you select “No,” you will receive monthly paper statements in the mail.</p><p>Please note that accounts take up to two business days to be established. Your funds will be available after this period. You will receive your debit card in the mail in up to five business days.</p>"],"vi":"Ngân hàng Cortica\n\nVui lòng điền vào mẫu đơn sau để mở một tài khoản ngân hàng mới.\n\nĐây có phải là tài khoản đầu tiên của quý khách tại Ngân hàng Cortica không? __ Có  X Không\nSố tài khoản hiện có (nếu có): 190-37580\nLoại tài khoản mới: __ Thanh toán  X Tiết kiệm  __ Đầu tư\nHọ tên: Frances Wilkes\nĐịa chỉ nhận thư: 17 Jones Street, North Sydney NSW 2060\nSố điện thoại: (02) 7010 8624\nĐịa chỉ e-mail: fwilkes@myemail.com.au\nSố tiền gửi ban đầu (tối thiểu 500 đô la): 1.500 đô la\nQuý khách có muốn đăng ký nhận thông tin qua phương thức điện tử không? __ Có  X Không\n\nNếu chọn \"Có\", chúng tôi sẽ liên hệ với quý khách qua tin nhắn thoại, e-mail hoặc tin nhắn văn bản.\nNếu chọn \"Không\", quý khách sẽ nhận bản sao kê giấy hằng tháng qua đường bưu điện.\n\nXin lưu ý rằng tài khoản cần tối đa hai ngày làm việc để được thiết lập. Tiền của quý khách sẽ sử dụng được sau khoảng thời gian này. Quý khách sẽ nhận thẻ ghi nợ qua bưu điện trong vòng tối đa năm ngày làm việc.","qs":[{"n":153,"q":"What is indicated about Ms. Wilkes?","qvi":"Điều gì được nêu về chị Wilkes?","opts":["She has another account with Cortica Bank.","She plans to open an investment account.","She has lost a debit card.","She placed an order for checks."],"ans":"A","xp":"Câu hỏi chi tiết. Bằng chứng: \"Is this your first account with Cortica Bank? ... X No\" và \"Existing account number (if applicable): 190-37580\" → chị đã có một tài khoản khác ở ngân hàng này. (B) sai: chị chọn \"Savings\" (tiết kiệm), không phải \"Investment\". (C), (D) không được nhắc.\n(A) Chị ấy có một tài khoản khác tại Ngân hàng Cortica.\n(B) Chị ấy định mở tài khoản đầu tư.\n(C) Chị ấy bị mất thẻ ghi nợ.\n(D) Chị ấy đã đặt mua séc."},{"n":154,"q":"How will the bank most likely contact Ms. Wilkes?","qvi":"Ngân hàng nhiều khả năng sẽ liên hệ với chị Wilkes bằng cách nào?","opts":["By e-mail","By text message","By telephone","By letter"],"ans":"D","xp":"Câu hỏi suy luận. Chị Wilkes đánh dấu \"X No\" cho câu hỏi đăng ký nhận thông tin điện tử. Mẫu đơn ghi: \"If you select 'No,' you will receive monthly paper statements in the mail.\" → ngân hàng sẽ liên lạc bằng thư giấy qua bưu điện = \"By letter\". (A), (B), (C) là các cách dành cho người chọn \"Yes\".\n(A) Qua e-mail\n(B) Qua tin nhắn văn bản\n(C) Qua điện thoại\n(D) Qua thư (bưu điện)"}]},{"ns":[155,157],"head":"Questions 155-157 refer to the following job advertisement.","passages":["<h3>Construction Superintendent<br>Jones-Richmond Construction (JRC)</h3><p>Founded 25 years ago, JRC is a full-service general contractor serving clients throughout Winnipeg and the surrounding area.</p><h4>Responsibilities:</h4><ul><li>Report to senior project manager</li><li>Manage on-site construction activities</li><li>Ensure compliance with safety regulations</li><li>Negotiate purchases and contracts</li><li>Establish construction schedules</li></ul><h4>Qualifications:</h4><ul><li>Minimum five years of commercial construction experience</li><li>Willingness to travel to job sites daily (usually within a 50-kilometre radius)</li><li>Strong written communication skills</li></ul><p>To apply, submit a résumé and cover letter through www.jrc.ca/apply.</p>"],"vi":"Giám sát Thi công\nCông ty Xây dựng Jones-Richmond (JRC)\n\nĐược thành lập cách đây 25 năm, JRC là nhà thầu chính cung cấp dịch vụ trọn gói, phục vụ khách hàng khắp Winnipeg và khu vực lân cận.\n\nTrách nhiệm:\n- Báo cáo cho quản lý dự án cấp cao\n- Quản lý các hoạt động thi công tại công trường\n- Đảm bảo tuân thủ các quy định an toàn\n- Đàm phán việc mua hàng và hợp đồng\n- Lập tiến độ thi công\n\nYêu cầu:\n- Tối thiểu năm năm kinh nghiệm trong xây dựng thương mại\n- Sẵn sàng di chuyển đến công trường hằng ngày (thường trong bán kính 50 km)\n- Kỹ năng giao tiếp bằng văn bản tốt\n\nĐể ứng tuyển, hãy nộp sơ yếu lý lịch và thư xin việc qua www.jrc.ca/apply.","qs":[{"n":155,"q":"What is suggested about Jones-Richmond Construction?","qvi":"Điều gì được ngụ ý về Công ty Xây dựng Jones-Richmond?","opts":["It is a new company.","It has won industry awards for its work.","It is based in Winnipeg.","It specializes in home construction projects."],"ans":"C","xp":"Câu hỏi suy luận. Bằng chứng: \"serving clients throughout Winnipeg and the surrounding area\" → công ty phục vụ khách ở Winnipeg và vùng lân cận → có trụ sở ở Winnipeg. (A) sai: \"Founded 25 years ago\". (B) không được nhắc. (D) sai: yêu cầu kinh nghiệm \"commercial construction\" (xây dựng thương mại), công ty là \"full-service general contractor\".\n(A) Đây là một công ty mới.\n(B) Công ty đã giành giải thưởng trong ngành.\n(C) Công ty có trụ sở tại Winnipeg.\n(D) Công ty chuyên về các dự án xây nhà ở."},{"n":156,"q":"What is NOT listed as a responsibility of the construction superintendent?","qvi":"Điều gì KHÔNG được liệt kê là trách nhiệm của giám sát thi công?","opts":["Setting schedules","Training inexperienced workers","Participating in contract discussions","Ensuring worker safety"],"ans":"B","xp":"Câu hỏi NOT. (A) = \"Establish construction schedules\"; (C) = \"Negotiate purchases and contracts\"; (D) = \"Ensure compliance with safety regulations\". Việc đào tạo công nhân thiếu kinh nghiệm không được nhắc → chọn (B).\n(A) Lập lịch trình\n(B) Đào tạo công nhân thiếu kinh nghiệm\n(C) Tham gia thảo luận hợp đồng\n(D) Đảm bảo an toàn cho công nhân"},{"n":157,"q":"According to the advertisement, what must a successful job applicant have?","qvi":"Theo quảng cáo, ứng viên trúng tuyển phải có điều gì?","opts":["A technical certification","A reference letter from a former employer","Senior management experience","The ability to visit construction sites each workday"],"ans":"D","xp":"Câu hỏi chi tiết. Bằng chứng: \"Willingness to travel to job sites daily\" → sẵn sàng đến công trường mỗi ngày = \"visit construction sites each workday\". Các yêu cầu khác là 5 năm kinh nghiệm và kỹ năng viết; không có chứng chỉ, thư giới thiệu hay kinh nghiệm quản lý cấp cao.\n(A) Một chứng chỉ kỹ thuật\n(B) Thư giới thiệu từ chủ cũ\n(C) Kinh nghiệm quản lý cấp cao\n(D) Khả năng đến công trường mỗi ngày làm việc"}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> All Sledgehammer Gym Staff</p><p><b>From:</b> Lucas Sledge</p><p><b>Date:</b> September 15</p><p><b>Subject:</b> Payroll changes</p><p><b>Attachment:</b> Form</p></div><p>Dear Staff,</p><p>Thanks to your dedicated work, word of our little gym has spread. Over the past twelve months, enrollment has significantly increased and so has our teaching staff. Although this growth is wonderful, having to process the payroll by myself has become rather burdensome. Therefore, I have contracted Trumbull and Company to provide direct deposit of your wages into your bank accounts. —<span class=\"pos\">[1]</span>—. Consequently, you no longer need to deposit your paycheck yourself. Also, you will now be able to get your pay stubs and tax information online. —<span class=\"pos\">[2]</span>—.</p><p>To allow for these changes, I am asking everyone to provide me with the necessary banking details. Please complete the attached form and bring it to the office with a voided check no later than September 25. —<span class=\"pos\">[3]</span>—. The new process will take effect in October. —<span class=\"pos\">[4]</span>—. Please let me know if you have any questions.</p><p>Take care,</p><p>Lucas</p>"],"vi":"Người nhận: Toàn thể nhân viên phòng tập Sledgehammer\nNgười gửi: Lucas Sledge\nNgày: 15 tháng 9\nTiêu đề: Thay đổi về bảng lương\nTệp đính kèm: Mẫu đơn\n\nCác bạn nhân viên thân mến,\n\nNhờ sự làm việc tận tụy của các bạn, tiếng tăm của phòng tập nhỏ của chúng ta đã lan rộng. Trong mười hai tháng qua, số người đăng ký đã tăng đáng kể và đội ngũ huấn luyện viên cũng vậy. Mặc dù sự tăng trưởng này thật tuyệt vời, việc phải tự mình xử lý bảng lương đã trở nên khá nặng nề. Vì vậy, tôi đã ký hợp đồng với Trumbull and Company để chuyển lương trực tiếp vào tài khoản ngân hàng của các bạn. [1] Do đó, các bạn không cần tự mình mang séc lương đi gửi nữa. Ngoài ra, giờ đây các bạn có thể xem phiếu lương và thông tin thuế trực tuyến. [2]\n\nĐể thực hiện những thay đổi này, tôi đề nghị mọi người cung cấp cho tôi các thông tin ngân hàng cần thiết. Vui lòng điền vào mẫu đơn đính kèm và mang đến văn phòng cùng với một tờ séc đã hủy chậm nhất vào ngày 25 tháng 9. [3] Quy trình mới sẽ có hiệu lực vào tháng 10. [4] Hãy cho tôi biết nếu các bạn có bất kỳ câu hỏi nào.\n\nChúc các bạn mọi điều tốt đẹp,\n\nLucas","qs":[{"n":158,"q":"What is mentioned as a benefit of the new payment system?","qvi":"Điều gì được nhắc đến như một lợi ích của hệ thống trả lương mới?","opts":["It will reduce Mr. Sledge’s workload.","It will include more staff involvement.","It will simplify tax collection.","It will result in fewer payment errors."],"ans":"A","xp":"Câu hỏi chi tiết. Bằng chứng: \"having to process the payroll by myself has become rather burdensome. Therefore, I have contracted Trumbull and Company...\" → ông Sledge thuê công ty bên ngoài vì tự làm lương quá nặng nề → hệ thống mới giảm khối lượng công việc cho ông. (C) sai: chỉ nói nhân viên xem được \"tax information online\", không nói về việc thu thuế. (B), (D) không được nhắc.\n(A) Nó sẽ giảm khối lượng công việc của ông Sledge.\n(B) Nó sẽ cần nhân viên tham gia nhiều hơn.\n(C) Nó sẽ đơn giản hóa việc thu thuế.\n(D) Nó sẽ giúp giảm sai sót khi trả lương."},{"n":159,"q":"What does Mr. Sledge ask employees to do?","qvi":"Ông Sledge yêu cầu nhân viên làm gì?","opts":["Update their contact information","Submit ideas on how to improve the gym","Provide information about their bank account","Sign up for a professional development class"],"ans":"C","xp":"Câu hỏi chi tiết. Bằng chứng: \"I am asking everyone to provide me with the necessary banking details. Please complete the attached form...\" → \"banking details\" = \"information about their bank account\".\n(A) Cập nhật thông tin liên lạc\n(B) Gửi ý tưởng để cải thiện phòng tập\n(C) Cung cấp thông tin về tài khoản ngân hàng\n(D) Đăng ký một lớp phát triển chuyên môn"},{"n":160,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“If I am not around, please see my assistant.”","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\"Nếu tôi không có mặt, vui lòng gặp trợ lý của tôi.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"C","xp":"Câu hỏi điền câu. Câu cần điền nói về việc nếu ông Sledge không có ở đó thì gặp trợ lý → phải đứng sau câu yêu cầu nhân viên đến gặp/mang đồ đến văn phòng. Câu trước vị trí [3]: \"Please complete the attached form and bring it to the office with a voided check no later than September 25.\" → khi mang mẫu đơn đến văn phòng mà ông không có mặt thì đưa cho trợ lý. Vì vậy chọn [3].\n(A) [1]\n(B) [2]\n(C) [3]\n(D) [4]"}]},{"ns":[161,163],"head":"Questions 161-163 refer to the following article.","passages":["<h3>Aussie Coffee Fair This Weekend</h3><p>SYDNEY (4 June)—Coffee will be the main attraction this weekend at the Aussie Coffee Fair hosted by Homewares, the country’s top kitchen appliance manufacturer. The event will be held at the Harbour Expo Centre.</p><p>The two-day event will feature a variety of coffee-oriented presentations by coffee growers and roasters, food writers, makers of kitchen equipment, and chefs. Foods and beverages will be available to view, taste, and buy at booths throughout the centre.</p><p>Sessions will feature demonstrations on cooking with coffee and tips for brewing the best cup of coffee, as well as information on nonfood uses for coffee. In addition, culinary experts will be on hand to meet with coffee enthusiasts for discussions designed to help them create a true coffeehouse experience in their own homes.</p><p>Entry to the Aussie Coffee Fair is free. However, registration is required as space is limited. For information and to register online, go to www.aussiecoffeefair.com.</p>"],"vi":"Hội chợ Cà phê Úc diễn ra cuối tuần này\n\nSYDNEY (4 tháng 6)—Cà phê sẽ là điểm thu hút chính vào cuối tuần này tại Hội chợ Cà phê Úc do Homewares, nhà sản xuất thiết bị nhà bếp hàng đầu cả nước, tổ chức. Sự kiện sẽ diễn ra tại Trung tâm Triển lãm Harbour.\n\nSự kiện kéo dài hai ngày sẽ có nhiều bài thuyết trình xoay quanh cà phê do những người trồng và rang cà phê, các cây bút viết về ẩm thực, các nhà sản xuất thiết bị nhà bếp và các đầu bếp trình bày. Đồ ăn và thức uống sẽ được trưng bày để khách xem, nếm thử và mua tại các gian hàng khắp trung tâm.\n\nCác buổi giới thiệu sẽ có phần trình diễn nấu ăn với cà phê và mẹo pha tách cà phê ngon nhất, cùng thông tin về các công dụng của cà phê ngoài ăn uống. Ngoài ra, các chuyên gia ẩm thực sẽ có mặt để gặp gỡ những người yêu cà phê trong các buổi trao đổi nhằm giúp họ tạo ra trải nghiệm quán cà phê thực thụ ngay tại nhà.\n\nVào cửa Hội chợ Cà phê Úc miễn phí. Tuy nhiên, cần đăng ký trước vì số chỗ có hạn. Để biết thông tin và đăng ký trực tuyến, hãy truy cập www.aussiecoffeefair.com.","qs":[{"n":161,"q":"The word “top” in paragraph 1, line 3, is closest in meaning to","qvi":"Từ \"top\" ở đoạn 1, dòng 3 gần nghĩa nhất với","opts":["only","leading","highest","modern"],"ans":"B","xp":"Câu hỏi đồng nghĩa. \"Homewares, the country’s top kitchen appliance manufacturer\" → \"top\" ở đây là \"hàng đầu, dẫn đầu\" (về vị thế trong ngành) = \"leading\". (C) highest là \"cao nhất\" (về độ cao/mức độ), không dùng để nói về công ty hàng đầu.\n(A) duy nhất\n(B) hàng đầu, dẫn đầu\n(C) cao nhất\n(D) hiện đại"},{"n":162,"q":"Who will NOT be conducting informational presentations at the fair?","qvi":"Ai sẽ KHÔNG thuyết trình cung cấp thông tin tại hội chợ?","opts":["Chefs","Coffee growers","Equipment makers","Coffeehouse owners"],"ans":"D","xp":"Câu hỏi NOT. \"presentations by coffee growers and roasters, food writers, makers of kitchen equipment, and chefs\" → (A) chefs, (B) coffee growers, (C) makers of kitchen equipment đều có. Chủ quán cà phê không được nhắc (chỉ có cụm \"coffeehouse experience\" – trải nghiệm quán cà phê tại nhà) → chọn (D).\n(A) Các đầu bếp\n(B) Người trồng cà phê\n(C) Các nhà sản xuất thiết bị\n(D) Chủ quán cà phê"},{"n":163,"q":"What must people do to attend the fair?","qvi":"Mọi người phải làm gì để tham dự hội chợ?","opts":["Sign up on a Web site","Call to make a reservation","Buy a ticket at the event location","Present a Homewares product receipt"],"ans":"A","xp":"Câu hỏi chi tiết. Bằng chứng: \"registration is required as space is limited. For information and to register online, go to www.aussiecoffeefair.com.\" → phải đăng ký trên trang web. \"register online\" = \"sign up on a Web site\". (C) sai: \"Entry ... is free\".\n(A) Đăng ký trên một trang web\n(B) Gọi điện để đặt chỗ\n(C) Mua vé tại địa điểm tổ chức\n(D) Xuất trình hóa đơn mua sản phẩm Homewares"}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>From:</b> melissa@grandgrainsbakery.com</p><p><b>To:</b> elinorotero@webmail.com</p><p><b>Date:</b> October 28</p><p><b>Re:</b> Desserts</p></div><p>Dear Ms. Otero,</p><p>I just followed up with our baker about your request to have an assortment of desserts instead of one large cake for the party you are hosting at your home on November 7. We suggest ordering three dessert pieces per person. The cost for three desserts is between $10 and $12 per person. Our most popular desserts are the mini cheesecakes, the berry tartlets, and the brownies.</p><p>I know you are using a separate caterer for the lunch, and they will help serve and clean up after the party. You also mentioned that you were considering whether to put the dessert table in your backyard or inside your house. Just keep in mind that if you order the cheesecakes, they should not be left out for more than two hours. If you give us very specific instructions about where to set up the desserts, our staff can leave them in the appropriate place without disturbing the party.</p><p>Once you make your dessert choices, simply let us know how many guests you expect, and we can take care of the rest.</p><p>Melissa Luhya<br>Grand Grains Bakery</p>"],"vi":"Người gửi: melissa@grandgrainsbakery.com\nNgười nhận: elinorotero@webmail.com\nNgày: 28 tháng 10\nV/v: Món tráng miệng\n\nKính gửi chị Otero,\n\nTôi vừa trao đổi lại với thợ làm bánh của chúng tôi về yêu cầu của chị muốn có nhiều loại món tráng miệng khác nhau thay vì một chiếc bánh lớn cho bữa tiệc chị tổ chức tại nhà vào ngày 7 tháng 11. Chúng tôi đề nghị đặt ba phần tráng miệng cho mỗi người. Chi phí cho ba món tráng miệng là từ 10 đến 12 đô la mỗi người. Những món tráng miệng được ưa chuộng nhất của chúng tôi là bánh phô mai mini, bánh tart nhỏ nhân quả mọng và bánh brownie.\n\nTôi biết chị thuê một đơn vị phục vụ ăn uống riêng cho bữa trưa, và họ sẽ giúp phục vụ cũng như dọn dẹp sau bữa tiệc. Chị cũng có nói rằng chị đang cân nhắc nên đặt bàn tráng miệng ở sân sau hay trong nhà. Xin chị lưu ý rằng nếu chị đặt bánh phô mai, không nên để bánh ở ngoài quá hai tiếng. Nếu chị cho chúng tôi hướng dẫn thật cụ thể về nơi bày các món tráng miệng, nhân viên của chúng tôi có thể đặt chúng ở đúng chỗ mà không làm gián đoạn bữa tiệc.\n\nKhi chị đã chọn xong các món tráng miệng, chỉ cần cho chúng tôi biết chị dự kiến có bao nhiêu khách, và chúng tôi sẽ lo phần còn lại.\n\nMelissa Luhya\nTiệm bánh Grand Grains","qs":[{"n":164,"q":"What is the purpose of the e-mail?","qvi":"Mục đích của e-mail là gì?","opts":["To advertise some new pastries","To present options for an event","To recommend serving a larger cake","To request payment on an order"],"ans":"B","xp":"Câu hỏi mục đích. E-mail trả lời yêu cầu của chị Otero về \"an assortment of desserts ... for the party\", gợi ý số lượng (\"three dessert pieces per person\"), giá và các món phổ biến (\"mini cheesecakes, the berry tartlets, and the brownies\") → đưa ra các lựa chọn cho một sự kiện (bữa tiệc). (C) sai: chị muốn món tráng miệng \"instead of one large cake\". (A), (D) không được nhắc.\n(A) Quảng cáo một số loại bánh ngọt mới\n(B) Đưa ra các lựa chọn cho một sự kiện\n(C) Đề nghị phục vụ một chiếc bánh lớn hơn\n(D) Yêu cầu thanh toán cho một đơn hàng"},{"n":165,"q":"What does Ms. Luhya indicate about the mini cheesecakes?","qvi":"Chị Luhya cho biết điều gì về bánh phô mai mini?","opts":["They are the most expensive dessert.","They are available in several flavors.","They should not be unrefrigerated for a long time.","They cannot be ordered in larger sizes."],"ans":"C","xp":"Câu hỏi chi tiết. Bằng chứng: \"if you order the cheesecakes, they should not be left out for more than two hours\" → không nên để bánh ở ngoài (không có tủ lạnh) quá lâu = \"should not be unrefrigerated for a long time\".\n(A) Đó là món tráng miệng đắt nhất.\n(B) Có nhiều hương vị.\n(C) Không nên để ngoài tủ lạnh quá lâu.\n(D) Không thể đặt cỡ lớn hơn."},{"n":166,"q":"The word “disturbing” in paragraph 2, line 6, is closest in meaning to","qvi":"Từ \"disturbing\" ở đoạn 2, dòng 6 gần nghĩa nhất với","opts":["interrupting","frightening","rearranging","moving"],"ans":"A","xp":"Câu hỏi đồng nghĩa. \"our staff can leave them in the appropriate place without disturbing the party\" → nhân viên đặt bánh mà không làm phiền/làm gián đoạn bữa tiệc → \"disturbing\" = \"interrupting\" (làm gián đoạn).\n(A) làm gián đoạn\n(B) làm sợ hãi\n(C) sắp xếp lại\n(D) di chuyển"},{"n":167,"q":"What information does Ms. Luhya request from Ms. Otero?","qvi":"Chị Luhya đề nghị chị Otero cung cấp thông tin gì?","opts":["A street address","An approximate budget","The name of a caterer","The number of guests"],"ans":"D","xp":"Câu hỏi chi tiết. Bằng chứng: \"simply let us know how many guests you expect\" → yêu cầu cho biết số lượng khách.\n(A) Địa chỉ nhà\n(B) Ngân sách ước tính\n(C) Tên của đơn vị phục vụ ăn uống\n(D) Số lượng khách"}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Cheryl Futrel &lt;cfutrel@zephyrmail.com&gt;</p><p><b>From:</b> Lydia Matsuda &lt;service@candella.com&gt;</p><p><b>Date:</b> June 9</p><p><b>Subject:</b> Home decorating</p></div><p>Dear Ms. Futrel,</p><p>Thank you for your interest in Candella Interior Design. —<span class=\"pos\">[1]</span>—. We are proud to claim that we are the oldest and most successful online design consulting company in the region. We welcome you as a new client. —<span class=\"pos\">[2]</span>—. From modest country homes to urban apartments, we do it all.</p><p>We understand from your original inquiry that you intend to sell your apartment soon and are primarily interested in how best to present it to prospective buyers. Here’s how our design services work: the first step is completing an online questionnaire. —<span class=\"pos\">[3]</span>—. Next, you will be matched with an online professional interior designer who can help you with all choices for paint colors, window treatments, and floor coverings. You will receive a room layout plan and a personalized list of ideas for furniture and accessories, with all products available for purchase online. —<span class=\"pos\">[4]</span>—. As a special bonus, from now until July 1 our online retail partners have agreed to offer a 10 percent discount on products purchased through our links.</p><p>Finally, you will be glad to learn that we charge not by the hour but by the room for our design ideas, with the average price being about $275 per room.</p><p>We look forward to hearing from you and working with you soon.</p><p>Sincerely,</p><p>Lydia Matsuda</p>"],"vi":"Người nhận: Cheryl Futrel <cfutrel@zephyrmail.com>\nNgười gửi: Lydia Matsuda <service@candella.com>\nNgày: 9 tháng 6\nTiêu đề: Trang trí nhà cửa\n\nKính gửi chị Futrel,\n\nCảm ơn chị đã quan tâm đến Candella Interior Design. [1] Chúng tôi tự hào khẳng định rằng chúng tôi là công ty tư vấn thiết kế trực tuyến lâu đời nhất và thành công nhất trong khu vực. Chúng tôi chào đón chị với tư cách là khách hàng mới. [2] Từ những ngôi nhà giản dị ở nông thôn đến các căn hộ ở thành thị, chúng tôi đều làm được.\n\nTừ yêu cầu ban đầu của chị, chúng tôi hiểu rằng chị dự định sớm bán căn hộ của mình và chủ yếu quan tâm đến cách trình bày căn hộ sao cho đẹp nhất trước những người mua tiềm năng. Dịch vụ thiết kế của chúng tôi hoạt động như sau: bước đầu tiên là hoàn thành một bảng câu hỏi trực tuyến. [3] Tiếp theo, chị sẽ được ghép với một nhà thiết kế nội thất chuyên nghiệp trực tuyến, người có thể giúp chị mọi lựa chọn về màu sơn, rèm cửa và vật liệu lót sàn. Chị sẽ nhận được một bản vẽ bố trí phòng và một danh sách ý tưởng được cá nhân hóa về đồ nội thất và phụ kiện, với tất cả sản phẩm đều có thể mua trực tuyến. [4] Như một ưu đãi đặc biệt, từ nay đến ngày 1 tháng 7, các đối tác bán lẻ trực tuyến của chúng tôi đã đồng ý giảm giá 10% cho các sản phẩm được mua qua đường liên kết của chúng tôi.\n\nCuối cùng, chị sẽ vui khi biết rằng chúng tôi tính phí cho ý tưởng thiết kế không theo giờ mà theo phòng, với mức giá trung bình khoảng 275 đô la mỗi phòng.\n\nChúng tôi mong sớm nhận được hồi âm và được làm việc cùng chị.\n\nTrân trọng,\n\nLydia Matsuda","qs":[{"n":168,"q":"What is indicated about Candella Interior Design?","qvi":"Điều gì được nêu về Candella Interior Design?","opts":["Its main office is located in a major city.","Its staff members visit clients’ houses.","It has been in business longer than its competitors have been.","It is a family-run business."],"ans":"C","xp":"Câu hỏi chi tiết. Bằng chứng: \"we are the oldest and most successful online design consulting company in the region\" → \"oldest\" (lâu đời nhất) = hoạt động lâu hơn các đối thủ. (B) sai: công ty tư vấn trực tuyến (\"online professional interior designer\"). (A), (D) không được nhắc.\n(A) Văn phòng chính đặt tại một thành phố lớn.\n(B) Nhân viên đến thăm nhà khách hàng.\n(C) Công ty đã kinh doanh lâu hơn các đối thủ cạnh tranh.\n(D) Đây là doanh nghiệp gia đình."},{"n":169,"q":"Why does Ms. Futrel want to redecorate her apartment?","qvi":"Tại sao chị Futrel muốn trang trí lại căn hộ của mình?","opts":["To prepare for a visit from relatives","To make it attractive to potential buyers","To replace furniture that she dislikes","To use it as an example for her clients"],"ans":"B","xp":"Câu hỏi chi tiết. Bằng chứng: \"you intend to sell your apartment soon and are primarily interested in how best to present it to prospective buyers\" → chị muốn căn hộ trông hấp dẫn với người mua. \"prospective buyers\" = \"potential buyers\".\n(A) Để chuẩn bị cho chuyến thăm của người thân\n(B) Để làm căn hộ hấp dẫn với người mua tiềm năng\n(C) Để thay đồ nội thất mà chị không thích\n(D) Để dùng làm mẫu cho khách hàng của chị"},{"n":170,"q":"What will happen on July 1 ?","qvi":"Điều gì sẽ xảy ra vào ngày 1 tháng 7?","opts":["Room accessories will be distributed.","Work will begin on a new project.","The client list will be expanded.","A special offer will end."],"ans":"D","xp":"Câu hỏi chi tiết. Bằng chứng: \"As a special bonus, from now until July 1 our online retail partners have agreed to offer a 10 percent discount\" → ưu đãi giảm giá 10% kéo dài đến ngày 1/7 → ngày 1/7 ưu đãi đặc biệt kết thúc. \"special bonus ... discount\" = \"special offer\".\n(A) Phụ kiện trang trí phòng sẽ được phân phát.\n(B) Công việc sẽ bắt đầu ở một dự án mới.\n(C) Danh sách khách hàng sẽ được mở rộng.\n(D) Một ưu đãi đặc biệt sẽ kết thúc."},{"n":171,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“The answers will give us a sense of your taste and requirements.”","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\"Các câu trả lời sẽ giúp chúng tôi hiểu được gu thẩm mỹ và yêu cầu của chị.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"C","xp":"Câu hỏi điền câu. \"The answers\" (các câu trả lời) phải đi sau một thứ có câu hỏi. Câu trước vị trí [3]: \"the first step is completing an online questionnaire\" (bước đầu là hoàn thành bảng câu hỏi trực tuyến) → \"The answers\" chính là câu trả lời cho bảng câu hỏi đó. Sau [3] là \"Next, you will be matched with...\" tiếp nối mạch các bước. Vì vậy chọn [3].\n(A) [1]\n(B) [2]\n(C) [3]\n(D) [4]"}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Darius Wilkins (11:09 A.M.)</b></p><p>Hi, Ms. Clarke. This is Darius from Roto Bicycle. I promised to check with you before servicing your bicycle.</p></div><div class=\"msg\"><p><b>Lauren Clarke (11:14 A.M.)</b></p><p>Thanks. So, what do you think?</p></div><div class=\"msg\"><p><b>Darius Wilkins (11:15 A.M.)</b></p><p>In addition to the regular maintenance service, I suggest a drivetrain cleaning and new brake mechanisms.</p></div><div class=\"msg\"><p><b>Lauren Clarke (11:16 A.M.)</b></p><p>OK. What does that come to?</p></div><div class=\"msg\"><p><b>Darius Wilkins (11:18 A.M.)</b></p><p>An extensive maintenance service, which includes the same gear and brake adjustments as a regular maintenance service, plus the drivetrain cleaning, is $140. Add $70 for two new brake mechanisms and pads and another $30 for labor charges. So it should come to around $240 altogether. Shall I move forward?</p></div><div class=\"msg\"><p><b>Lauren Clarke (11:21 A.M.)</b></p><p>Wow! That much?</p></div><div class=\"msg\"><p><b>Darius Wilkins (11:22 A.M.)</b></p><p>Especially with that major bicycle race you have ahead of you.</p></div><div class=\"msg\"><p><b>Lauren Clarke (11:24 A.M.)</b></p><p>I know. I guess we have to do it. Please let me know when it’s ready.</p></div>"],"vi":"Darius Wilkins (11:09 sáng): Chào chị Clarke. Tôi là Darius từ cửa hàng xe đạp Roto. Tôi đã hứa sẽ hỏi ý kiến chị trước khi bảo dưỡng xe đạp của chị.\n\nLauren Clarke (11:14 sáng): Cảm ơn anh. Vậy anh thấy thế nào?\n\nDarius Wilkins (11:15 sáng): Ngoài gói bảo dưỡng thông thường, tôi đề nghị vệ sinh bộ truyền động và thay cơ cấu phanh mới.\n\nLauren Clarke (11:16 sáng): Được. Tổng cộng hết bao nhiêu?\n\nDarius Wilkins (11:18 sáng): Gói bảo dưỡng toàn diện, bao gồm việc chỉnh líp và phanh giống như gói bảo dưỡng thông thường, cộng thêm vệ sinh bộ truyền động, là 140 đô la. Cộng thêm 70 đô la cho hai bộ cơ cấu phanh và má phanh mới, và 30 đô la nữa cho tiền công. Vậy tổng cộng khoảng 240 đô la. Tôi tiến hành nhé?\n\nLauren Clarke (11:21 sáng): Trời! Nhiều vậy sao?\n\nDarius Wilkins (11:22 sáng): Nhất là khi chị sắp có cuộc đua xe đạp lớn phía trước.\n\nLauren Clarke (11:24 sáng): Tôi biết. Chắc là phải làm thôi. Khi nào xong thì báo tôi nhé.","qs":[{"n":172,"q":"Why did Mr. Wilkins contact Ms. Clarke?","qvi":"Tại sao anh Wilkins liên lạc với chị Clarke?","opts":["To recommend a new product","To discuss a scheduling problem","To confirm that a bicycle part has been ordered","To request permission to do some work"],"ans":"D","xp":"Câu hỏi mục đích. Bằng chứng: \"I promised to check with you before servicing your bicycle\" và sau khi báo giá anh hỏi \"Shall I move forward?\" → anh liên lạc để xin phép chị trước khi làm việc sửa chữa/bảo dưỡng. (A) sai: anh đề xuất dịch vụ, không phải sản phẩm mới.\n(A) Để giới thiệu một sản phẩm mới\n(B) Để thảo luận một vấn đề về lịch trình\n(C) Để xác nhận một phụ tùng xe đạp đã được đặt hàng\n(D) Để xin phép thực hiện một số công việc"},{"n":173,"q":"What most likely cost about $30 ?","qvi":"Khoản nào nhiều khả năng có giá khoảng 30 đô la?","opts":["New braking mechanisms","Labor charges","Basic maintenance service","Drivetrain cleaning"],"ans":"B","xp":"Câu hỏi chi tiết. Bằng chứng: \"Add $70 for two new brake mechanisms and pads and another $30 for labor charges\" → 30 đô la là tiền công. (A) phanh mới là 70 đô la; (C), (D) gói bảo dưỡng toàn diện kèm vệ sinh bộ truyền động là 140 đô la.\n(A) Cơ cấu phanh mới\n(B) Tiền công\n(C) Gói bảo dưỡng cơ bản\n(D) Vệ sinh bộ truyền động"},{"n":174,"q":"At 11:21 A.M., what does Ms. Clarke imply when she writes, “That much”?","qvi":"Lúc 11:21 sáng, khi chị Clarke viết \"That much\" (Nhiều vậy sao), chị ấy ngụ ý điều gì?","opts":["She did not realize how busy Mr. Wilkins is.","The pressure in her tires was surprisingly low.","The cost of repairs seems high.","Repairing the bike will take more time than she expected."],"ans":"C","xp":"Câu hỏi hàm ý. Ngay trước đó anh Wilkins báo \"it should come to around $240 altogether\". Chị Clarke phản ứng \"Wow! That much?\" → chị ngạc nhiên vì chi phí sửa chữa cao.\n(A) Chị không biết anh Wilkins bận đến mức nào.\n(B) Áp suất lốp xe của chị thấp đến bất ngờ.\n(C) Chi phí sửa chữa có vẻ cao.\n(D) Việc sửa xe sẽ mất nhiều thời gian hơn chị nghĩ."},{"n":175,"q":"What is suggested about Ms. Clarke?","qvi":"Điều gì được ngụ ý về chị Clarke?","opts":["She prefers to pay with cash.","She is shopping for a new bicycle.","She is unhappy with the quality of a repair.","She will soon compete in a bicycle race."],"ans":"D","xp":"Câu hỏi suy luận. Bằng chứng: \"Especially with that major bicycle race you have ahead of you.\" – chị Clarke đáp \"I know.\" → chị sắp tham gia một cuộc đua xe đạp. (C) sai: việc sửa chữa chưa được thực hiện. (A), (B) không được nhắc.\n(A) Chị thích trả bằng tiền mặt.\n(B) Chị đang tìm mua xe đạp mới.\n(C) Chị không hài lòng với chất lượng sửa chữa.\n(D) Chị sắp thi đấu trong một cuộc đua xe đạp."}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following e-mail and Web page.","passages":["<div class=\"hdr\"><p><b>To:</b> Cassie Raferty &lt;cassie@mailcurrent.ie&gt;</p><p><b>From:</b> Youssef Zimri &lt;zimri@zimrimechanical.ie&gt;</p><p><b>Subject:</b> Following up</p><p><b>Date:</b> 12 September</p><p><b>Attachment:</b> cmcclinic</p></div>\n<p>Dear Ms. Raferty,</p>\n<p>I am very happy with your work so far. Your suggestion to add photos from our archive certainly dressed up the \"Company History\" page. The help-wanted pop-up bubble on the home page also looks good. Hopefully, it will attract applicants with mechanical experience.</p>\n<p>I'd like you to add one more project to our \"Portfolio\" page. We have finally finished replacing the plumbing and heating systems at Clary Medical Centre's satellite clinic in Galway. It was a challenging job, and I'm proud of our results. The attachment contains photos and a short description of what we did there.</p>\n<p>Sincerely,</p>\n<p>Youssef Zimri<br>Owner, Zimri Mechanical</p>","<p>https://www.clarymedicalcentre.ie</p>\n<p>About | <u>News</u> | Staff | Contact Us</p>\n<h3>Clinic opening soon</h3>\n<p>We have repurposed 47 High Street, Galway, into a satellite medical clinic and will celebrate with a grand opening party on Friday, 28 October. Remarks by Medical Director Dr. Celia O'Leary and local elected officials will begin promptly at 1:00 P.M., followed by a ribbon-cutting ceremony and tours until 4:30 P.M.</p>\n<p>Thirty miles from the Clary Medical Centre's main campus, the Clary Clinic is housed in the historic Brandmore shoe factory, which closed more than two decades ago. During renovations, care was taken to maintain the exterior's nineteenth-century architectural features. The clinic's interior boasts eighteen examination rooms, a state-of-the-art x-ray facility, private offices for patient consultations, and a lab for processing patient samples.</p>\n<p>Clinic staff will begin seeing patients on Tuesday, 1 November. To make an appointment, please call 020 915 1424.</p>"],"vi":"[E-mail]\nNgười nhận: Cassie Raferty <cassie@mailcurrent.ie>\nNgười gửi: Youssef Zimri <zimri@zimrimechanical.ie>\nTiêu đề: Theo dõi tiếp\nNgày: 12 tháng 9\nTệp đính kèm: cmcclinic\n\nChị Raferty thân mến,\n\nTôi rất hài lòng với công việc của chị cho đến giờ. Đề xuất của chị về việc thêm ảnh từ kho lưu trữ của chúng tôi chắc chắn đã làm trang \"Lịch sử công ty\" đẹp hơn hẳn. Bong bóng pop-up thông báo tuyển dụng trên trang chủ cũng trông rất ổn. Hy vọng nó sẽ thu hút được những ứng viên có kinh nghiệm về cơ khí.\n\nTôi muốn chị thêm một dự án nữa vào trang \"Hồ sơ dự án\" của chúng tôi. Cuối cùng chúng tôi đã hoàn thành việc thay thế hệ thống ống nước và hệ thống sưởi tại phòng khám vệ tinh của Trung tâm Y tế Clary ở Galway. Đó là một công việc đầy thử thách, và tôi tự hào về kết quả của chúng tôi. Tệp đính kèm có ảnh và một đoạn mô tả ngắn về những gì chúng tôi đã làm ở đó.\n\nTrân trọng,\n\nYoussef Zimri\nChủ sở hữu, Zimri Mechanical\n\n[Trang web]\nhttps://www.clarymedicalcentre.ie\nGiới thiệu | Tin tức | Nhân viên | Liên hệ\n\nPhòng khám sắp khai trương\n\nChúng tôi đã cải tạo số 47 phố High, Galway, thành một phòng khám y tế vệ tinh và sẽ ăn mừng bằng một buổi tiệc khai trương vào thứ Sáu, ngày 28 tháng 10. Phần phát biểu của Giám đốc Y khoa, bác sĩ Celia O'Leary, và các quan chức dân cử địa phương sẽ bắt đầu đúng 1 giờ chiều, tiếp theo là lễ cắt băng khánh thành và các chuyến tham quan đến 4 giờ 30 chiều.\n\nCách khuôn viên chính của Trung tâm Y tế Clary ba mươi dặm, Phòng khám Clary nằm trong tòa nhà xưởng giày Brandmore lịch sử, nơi đã đóng cửa hơn hai mươi năm trước. Trong quá trình cải tạo, chúng tôi đã cẩn thận giữ gìn các đặc điểm kiến trúc thế kỷ 19 ở mặt ngoài tòa nhà. Bên trong phòng khám có mười tám phòng khám bệnh, một cơ sở chụp X-quang hiện đại bậc nhất, các văn phòng riêng để tư vấn cho bệnh nhân, và một phòng xét nghiệm để xử lý mẫu bệnh phẩm.\n\nNhân viên phòng khám sẽ bắt đầu tiếp nhận bệnh nhân vào thứ Ba, ngày 1 tháng 11. Để đặt lịch hẹn, vui lòng gọi số 020 915 1424.","qs":[{"n":176,"q":"Who most likely is Ms. Raferty?","qvi":"Cô Raferty nhiều khả năng là ai?","opts":["A job recruiter","A plumbing contractor","A Galway historian","A Web-site designer"],"ans":"D","xp":"Suy luận (danh tính người nhận). Trong e-mail, ông Zimri khen công việc của cô Raferty: \"Your suggestion to add photos from our archive certainly dressed up the 'Company History' page. The help-wanted pop-up bubble on the home page also looks good.\" và nhờ \"add one more project to our 'Portfolio' page\". Cô ấy làm các trang (page), trang chủ (home page), pop-up → cô là người thiết kế trang web → (D).\n(A) Bẫy: pop-up tuyển dụng chỉ là một phần cô làm trên trang web, cô không phải người đi tuyển dụng. (B) Công ty ông Zimri mới là bên làm ống nước. (C) Không có thông tin.\n(A) Nhân viên tuyển dụng\n(B) Nhà thầu ống nước\n(C) Nhà sử học ở Galway\n(D) Nhà thiết kế trang web"},{"n":177,"q":"What is indicated about Mr. Zimri?","qvi":"Điều gì được nói về ông Zimri?","opts":["He is trying to recruit an assistant architect.","He is a member of Clary Medical Centre's board of directors.","He is pleased with his firm's work at a former shoe factory.","He is waiting for Dr. O'Leary's feedback on a portfolio."],"ans":"C","xp":"Câu hỏi liên kết 2 đoạn. E-mail: \"We have finally finished replacing the plumbing and heating systems at Clary Medical Centre's satellite clinic in Galway. It was a challenging job, and I'm proud of our results.\" Trang web: \"the Clary Clinic is housed in the historic Brandmore shoe factory, which closed more than two decades ago.\" → Phòng khám vệ tinh ở Galway nằm trong một xưởng giày cũ, và ông Zimri tự hào (proud → pleased) về công việc ở đó → (C).\n(A) Ông muốn tuyển người có kinh nghiệm cơ khí (mechanical), không phải kiến trúc sư. (B), (D) Không được nhắc đến.\n(A) Ông đang cố tuyển một trợ lý kiến trúc sư.\n(B) Ông là thành viên hội đồng quản trị của Trung tâm Y tế Clary.\n(C) Ông hài lòng với công việc của công ty mình tại một xưởng giày cũ.\n(D) Ông đang chờ phản hồi của bác sĩ O'Leary về một hồ sơ dự án."},{"n":178,"q":"According to the Web page, what will happen at the grand opening event?","qvi":"Theo trang web, điều gì sẽ diễn ra tại sự kiện khai trương?","opts":["Government officials will be in attendance.","Sandwiches will be served.","New building plans will be revealed.","Former patients will be interviewed."],"ans":"A","xp":"Chi tiết. Trang web: \"Remarks by Medical Director Dr. Celia O'Leary and local elected officials will begin promptly at 1:00 P.M.\" → các quan chức dân cử địa phương (local elected officials) sẽ phát biểu, tức là họ có mặt → \"Government officials will be in attendance\" → (A).\n(B), (C), (D) không được nhắc đến (chỉ có phát biểu, cắt băng, tham quan).\n(A) Các quan chức chính quyền sẽ có mặt.\n(B) Bánh mì kẹp sẽ được phục vụ.\n(C) Kế hoạch xây dựng mới sẽ được công bố.\n(D) Các bệnh nhân cũ sẽ được phỏng vấn."},{"n":179,"q":"On the Web page, the word \"maintain\" in paragraph 2, line 3, is closest in meaning to","qvi":"Trên trang web, từ \"maintain\" ở đoạn 2, dòng 3, gần nghĩa nhất với","opts":["assert","heal","support","preserve"],"ans":"D","xp":"Đồng nghĩa. Câu gốc: \"During renovations, care was taken to maintain the exterior's nineteenth-century architectural features.\" → trong lúc cải tạo, họ cẩn thận GIỮ GÌN các đặc điểm kiến trúc thế kỷ 19. \"maintain\" ở đây = giữ nguyên, bảo tồn = preserve → (D).\n(A) assert cũng có thể là nghĩa của maintain (\"khẳng định\": He maintains that...), nhưng không hợp ngữ cảnh. (C) support = ủng hộ/chống đỡ, không hợp.\n(A) khẳng định\n(B) chữa lành\n(C) hỗ trợ, chống đỡ\n(D) bảo tồn, giữ gìn"},{"n":180,"q":"According to the Web page, what is NOT part of the Clary Clinic?","qvi":"Theo trang web, cái gì KHÔNG thuộc Phòng khám Clary?","opts":["A medical laboratory","A pharmacy","Medical imaging equipment","Offices for clinicians"],"ans":"B","xp":"Câu hỏi NOT. Trang web: \"The clinic's interior boasts eighteen examination rooms, a state-of-the-art x-ray facility, private offices for patient consultations, and a lab for processing patient samples.\"\n(A) \"a lab for processing patient samples\" = phòng xét nghiệm y tế → có.\n(C) \"x-ray facility\" = thiết bị chẩn đoán hình ảnh → có.\n(D) \"private offices for patient consultations\" = văn phòng cho bác sĩ → có.\n(B) Nhà thuốc (pharmacy) không được nhắc đến → chọn (B).\n(A) Phòng xét nghiệm y tế\n(B) Nhà thuốc\n(C) Thiết bị chẩn đoán hình ảnh\n(D) Văn phòng cho bác sĩ"}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following form and e-mail.","passages":["<h3>PURCHASE ORDER</h3>\n<p>Pirate's Bounty Seafood<br>11 Harbor Street<br>Charlottetown, Prince Edward Island, C1A 0A5</p>\n<p>2 October<br>Purchase Order: 5338</p>\n<table>\n<tr><th>VENDOR</th><th>SHIP TO</th></tr>\n<tr><td>Rochette's Commercial Refrigeration<br>2175 Lyons Avenue<br>Guelph, Ontario, N1C 0A1<br>519-555-0112</td><td>Pirate's Bounty Seafood<br>11 Harbor Street<br>Charlottetown, Prince Edward Island, C1A 0A5<br>Attn: Lenore Okiya<br>782-555-0145</td></tr>\n</table>\n<table>\n<tr><th>ITEM NUMBER</th><th>DESCRIPTION</th><th>QUANTITY</th><th>PRICE</th><th>TOTAL</th></tr>\n<tr><td>BF550</td><td>Blizzard walk-in freezer</td><td>1</td><td>$6,400.00</td><td>$6,400.00</td></tr>\n<tr><td></td><td>Features: 1.5m x 2m x 2.5m, adjustable shelves, aluminum flooring, galvanized steel panels</td><td></td><td></td><td></td></tr>\n</table>\n<table>\n<tr><th>COMMENTS OR SPECIAL INSTRUCTIONS</th></tr>\n<tr><td>Restaurant expanding. Need unit by 17 November.</td></tr>\n</table>\n<table>\n<tr><th>SUBTOTAL</th><td>$6,400.00</td></tr>\n<tr><th>TAX</th><td>$960.00</td></tr>\n<tr><th>GRAND TOTAL</th><td>$7,360.00</td></tr>\n</table>","<div class=\"hdr\"><p><b>To:</b> Lenore Okiya &lt;l.okiya@piratesbounty.ca&gt;</p><p><b>From:</b> Shaliya Umuma &lt;customerservice@rochettesrefrigeration.ca&gt;</p><p><b>Date:</b> 3 October</p><p><b>Subject:</b> Purchase Order 5338</p></div>\n<p>Dear Ms. Okiya,</p>\n<p>We received your purchase order for the Blizzard walk-in freezer. Unfortunately, the model you requested is on back order and will not be available for three months. We regret the inconvenience and would like to offer you some options.</p>\n<p>I can offer you the Blizzard BF600, which measures 2m x 2.5m x 3m, at the discounted price of $6,900 plus tax. It comes with the same features as the item you ordered. Alternately, we have a refurbished BF400 in stock. It's the same size as the BF550; however, while the BF550 includes a remote control for setting the temperature, the BF400 has a wall-mounted device for that purpose. The BF400 unit comes with a two-year warranty. It is priced at $5,600 plus tax.</p>\n<p>Please let me know how you wish to proceed. Just reply to this e-mail.</p>\n<p>Shaliya Umuma, Customer Service Manager</p>"],"vi":"[Đơn đặt hàng]\nĐƠN ĐẶT HÀNG\nPirate's Bounty Seafood, số 11 phố Harbor, Charlottetown, đảo Prince Edward, C1A 0A5\nNgày 2 tháng 10 – Đơn đặt hàng số: 5338\n\nNHÀ CUNG CẤP: Rochette's Commercial Refrigeration (Điện lạnh Thương mại Rochette), số 2175 đại lộ Lyons, Guelph, Ontario, N1C 0A1, 519-555-0112\nGIAO ĐẾN: Pirate's Bounty Seafood, số 11 phố Harbor, Charlottetown, đảo Prince Edward, C1A 0A5. Người nhận: Lenore Okiya, 782-555-0145\n\nMÃ HÀNG: BF550 – MÔ TẢ: Tủ đông walk-in (kho đông đi vào được) Blizzard – SỐ LƯỢNG: 1 – ĐƠN GIÁ: 6.400 đô – THÀNH TIỀN: 6.400 đô\nĐặc điểm: 1,5m x 2m x 2,5m, kệ điều chỉnh được, sàn nhôm, tấm thép mạ kẽm\n\nGHI CHÚ HOẶC HƯỚNG DẪN ĐẶC BIỆT: Nhà hàng đang mở rộng. Cần có thiết bị trước ngày 17 tháng 11.\nTẠM TÍNH: 6.400 đô – THUẾ: 960 đô – TỔNG CỘNG: 7.360 đô\n\n[E-mail]\nNgười nhận: Lenore Okiya <l.okiya@piratesbounty.ca>\nNgười gửi: Shaliya Umuma <customerservice@rochettesrefrigeration.ca>\nNgày: 3 tháng 10\nTiêu đề: Đơn đặt hàng 5338\n\nChị Okiya thân mến,\n\nChúng tôi đã nhận được đơn đặt hàng tủ đông walk-in Blizzard của chị. Đáng tiếc là mẫu chị yêu cầu hiện đang hết hàng phải chờ nhập (back order) và sẽ không có trong ba tháng. Chúng tôi rất tiếc vì sự bất tiện này và muốn đưa ra cho chị một vài lựa chọn.\n\nTôi có thể cung cấp cho chị mẫu Blizzard BF600, kích thước 2m x 2,5m x 3m, với giá ưu đãi 6.900 đô cộng thuế. Nó có các tính năng giống như sản phẩm chị đã đặt. Ngoài ra, chúng tôi có sẵn một chiếc BF400 đã được tân trang. Nó có cùng kích thước với BF550; tuy nhiên, trong khi BF550 có điều khiển từ xa để cài đặt nhiệt độ, thì BF400 có một thiết bị gắn tường cho mục đích đó. Chiếc BF400 đi kèm bảo hành hai năm. Giá của nó là 5.600 đô cộng thuế.\n\nVui lòng cho tôi biết chị muốn xử lý thế nào. Chị chỉ cần trả lời e-mail này.\n\nShaliya Umuma, Quản lý Dịch vụ Khách hàng","qs":[{"n":181,"q":"Why does Pirate's Bounty Seafood need to purchase new equipment?","qvi":"Vì sao Pirate's Bounty Seafood cần mua thiết bị mới?","opts":["Its current refrigerator stopped working.","The warranty on its current refrigerator has expired.","The restaurant is increasing in size.","The restaurant is moving to a new location."],"ans":"C","xp":"Chi tiết. Trong đơn đặt hàng, mục ghi chú: \"Restaurant expanding. Need unit by 17 November.\" → nhà hàng đang mở rộng (expanding = increasing in size) → (C).\n(A), (B), (D) không được nhắc đến.\n(A) Tủ lạnh hiện tại của họ bị hỏng.\n(B) Bảo hành tủ lạnh hiện tại đã hết hạn.\n(C) Nhà hàng đang mở rộng quy mô.\n(D) Nhà hàng đang chuyển đến địa điểm mới."},{"n":182,"q":"What is the problem with the item Ms. Okiya ordered?","qvi":"Món hàng cô Okiya đặt gặp vấn đề gì?","opts":["It was lost during shipping.","It has been discontinued.","It is temporarily out of stock.","It has a damaged control panel."],"ans":"C","xp":"Chi tiết. E-mail: \"Unfortunately, the model you requested is on back order and will not be available for three months.\" → \"on back order\" = hết hàng, đang chờ nhập thêm; ba tháng nữa mới có → tạm thời hết hàng (temporarily out of stock) → (C).\n(B) \"discontinued\" = ngừng sản xuất hẳn – sai, vì 3 tháng nữa vẫn có hàng. (A), (D) không nhắc đến.\n(A) Nó bị thất lạc khi vận chuyển.\n(B) Nó đã ngừng sản xuất.\n(C) Nó tạm thời hết hàng.\n(D) Nó có bảng điều khiển bị hỏng."},{"n":183,"q":"What is NOT a feature of the Blizzard BF600?","qvi":"Đâu KHÔNG phải là đặc điểm của Blizzard BF600?","opts":["It has a fast-freeze switch.","It has adjustable shelves.","It has aluminum flooring.","It has galvanized steel panels."],"ans":"A","xp":"Câu hỏi NOT, liên kết 2 đoạn. E-mail nói BF600 \"comes with the same features as the item you ordered\" (có cùng tính năng với mẫu đã đặt, tức BF550). Đơn đặt hàng ghi tính năng của BF550: \"adjustable shelves, aluminum flooring, galvanized steel panels\".\n(B) kệ điều chỉnh được, (C) sàn nhôm, (D) tấm thép mạ kẽm → đều có.\n(A) Công tắc cấp đông nhanh (fast-freeze switch) không được nhắc đến → chọn (A).\n(A) Nó có công tắc cấp đông nhanh.\n(B) Nó có kệ điều chỉnh được.\n(C) Nó có sàn bằng nhôm.\n(D) Nó có các tấm thép mạ kẽm."},{"n":184,"q":"According to the e-mail, what does the BF400 model come with?","qvi":"Theo e-mail, mẫu BF400 đi kèm với cái gì?","opts":["A user manual","A remote control","A warranty","A tax waiver"],"ans":"C","xp":"Chi tiết. E-mail: \"The BF400 unit comes with a two-year warranty.\" → đi kèm bảo hành hai năm → (C).\n(B) Bẫy: điều khiển từ xa là của BF550; BF400 dùng thiết bị gắn tường (\"while the BF550 includes a remote control ..., the BF400 has a wall-mounted device\"). (D) Giá BF400 là \"$5,600 plus tax\" → vẫn phải trả thuế, không được miễn thuế. (A) không nhắc đến.\n(A) Sách hướng dẫn sử dụng\n(B) Điều khiển từ xa\n(C) Giấy bảo hành\n(D) Miễn thuế"},{"n":185,"q":"In the e-mail, the word \"Just\" in paragraph 3, line 1, is closest in meaning to","qvi":"Trong e-mail, từ \"Just\" ở đoạn 3, dòng 1, gần nghĩa nhất với","opts":["immediately","kindly","shortly","simply"],"ans":"D","xp":"Đồng nghĩa. Câu gốc: \"Please let me know how you wish to proceed. Just reply to this e-mail.\" → \"Just\" ở đây nghĩa là \"chỉ cần (đơn giản là)\" trả lời e-mail này = simply → (D).\n(A) immediately = ngay lập tức, (C) shortly = sắp, chẳng bao lâu: đây là nghĩa của \"just\" khi nói về thời gian (just now, just arrived), không hợp ngữ cảnh.\n(A) ngay lập tức\n(B) vui lòng, tử tế\n(C) sắp, chẳng bao lâu nữa\n(D) chỉ cần, đơn giản là"}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following schedule, e-mail, and article.","passages":["<h3>Fifth Annual International Marketing Society Conference</h3>\n<p>23–25 October, Grant Hotel and Conference Centre, London</p>\n<h4>Day 1:</h4>\n<table>\n<tr><th>Time</th><th>Description</th><th>Venue</th></tr>\n<tr><td>7:00 A.M. to 8:00 A.M.</td><td>Morning Social: Complimentary omelets, pastries, coffee, tea</td><td>Mezzanine</td></tr>\n<tr><td>8:30 A.M. to 10:00 A.M.</td><td>Marcos Secada, founder and CEO, Grindstone Marketing Group</td><td>Room 2</td></tr>\n<tr><td>10:30 A.M. to noon</td><td>Claire Song, business columnist and best-selling author</td><td>Room 10</td></tr>\n<tr><td>12:30 P.M. to 2:00 P.M.</td><td>Lunch (ticket purchase required)</td><td>Alexander Ballroom</td></tr>\n</table>","<div class=\"hdr\"><p><b>To:</b> Nadir Kalwar &lt;kalwar.n@kdbuildingconcepts.com&gt;</p><p><b>From:</b> Olek Dzik &lt;odzik.k@kdbuildingconcepts.com&gt;</p><p><b>Date:</b> 12 May</p><p><b>Subject:</b> Upcoming marketing campaign</p><p><b>Attachment:</b> Link to video</p></div>\n<p>Nadir,</p>\n<p>Thanks for your help with the corporate marketing plan. Attached is a link to the video created for us by Grindstone Marketing Group. It shows our 3-D printing equipment pouring fast-setting concrete, layer by layer. I think it looks great as is, and I believe it will be the most compelling aspect of our 1 June launch, especially if the Sheffield house is sold by then.</p>\n<p>In case you haven't heard, our next construction project will be a home just a couple of kilometres from your office building!</p>\n<p>Olek</p>","<h3>House Constructed Using 3-D Technology For Sale</h3>\n<p>SHEFFIELD (15 May)—An international construction firm specializing in innovative building technologies has completed one of Britain's first 3-D printed houses. The new structure is located on Morgan Road in Sheffield.</p>\n<p>KD Building Concepts took less than two weeks to execute the first phase of the project, which entailed printing the concrete walls and installing the electrical and plumbing systems, according to company president Olek Dzik. In just two months, the fully landscaped house with two bedrooms and two bathrooms was ready for market.</p>\n<p>\"Labour costs were cut in half thanks to 3-D printing technology,\" said Mr. Dzik, whose company has offices in France and Germany, as well as in Sheffield. \"At KD Building Concepts, we are committed to building homes that are both affordable and luxurious.\"</p>\n<p>The house was listed for sale this week by a local real estate broker. The asking price is £150,000.</p>\n<p>Next on the horizon for KD Building Concepts is the construction of a home in Hamburg, Germany.</p>"],"vi":"[Lịch trình]\nHội nghị thường niên lần thứ năm của Hiệp hội Marketing Quốc tế\n23–25 tháng 10, Khách sạn và Trung tâm Hội nghị Grant, London\nNgày 1:\n- 7:00 – 8:00 sáng: Giao lưu buổi sáng: trứng ốp lết, bánh ngọt, cà phê, trà miễn phí – Tầng lửng\n- 8:30 – 10:00 sáng: Marcos Secada, nhà sáng lập kiêm Giám đốc điều hành, Grindstone Marketing Group – Phòng 2\n- 10:30 sáng – 12:00 trưa: Claire Song, nhà báo chuyên mục kinh doanh và tác giả sách bán chạy – Phòng 10\n- 12:30 – 2:00 chiều: Ăn trưa (cần mua vé) – Phòng khiêu vũ Alexander\n\n[E-mail]\nNgười nhận: Nadir Kalwar <kalwar.n@kdbuildingconcepts.com>\nNgười gửi: Olek Dzik <odzik.k@kdbuildingconcepts.com>\nNgày: 12 tháng 5\nTiêu đề: Chiến dịch marketing sắp tới\nTệp đính kèm: Đường link video\n\nNadir,\n\nCảm ơn anh đã giúp đỡ với kế hoạch marketing của công ty. Đính kèm là đường link đến video do Grindstone Marketing Group làm cho chúng ta. Video cho thấy thiết bị in 3-D của chúng ta đổ bê tông đông kết nhanh, từng lớp một. Tôi nghĩ nó trông rất tuyệt như hiện tại, và tôi tin nó sẽ là điểm hấp dẫn nhất trong buổi ra mắt ngày 1 tháng 6 của chúng ta, nhất là nếu căn nhà ở Sheffield được bán trước thời điểm đó.\n\nPhòng khi anh chưa nghe tin, dự án xây dựng tiếp theo của chúng ta sẽ là một ngôi nhà chỉ cách tòa nhà văn phòng của anh vài cây số!\n\nOlek\n\n[Bài báo]\nNhà được xây bằng công nghệ 3-D được rao bán\n\nSHEFFIELD (15 tháng 5) – Một công ty xây dựng quốc tế chuyên về các công nghệ xây dựng đổi mới đã hoàn thành một trong những ngôi nhà in 3-D đầu tiên của Anh. Công trình mới nằm trên đường Morgan ở Sheffield.\n\nTheo chủ tịch công ty Olek Dzik, KD Building Concepts mất chưa đến hai tuần để thực hiện giai đoạn đầu của dự án, bao gồm in các bức tường bê tông và lắp đặt hệ thống điện và ống nước. Chỉ trong hai tháng, ngôi nhà hai phòng ngủ, hai phòng tắm với cảnh quan sân vườn hoàn chỉnh đã sẵn sàng để bán.\n\n\"Chi phí nhân công giảm một nửa nhờ công nghệ in 3-D,\" ông Dzik cho biết; công ty của ông có văn phòng ở Pháp và Đức, cũng như ở Sheffield. \"Tại KD Building Concepts, chúng tôi cam kết xây dựng những ngôi nhà vừa có giá phải chăng vừa sang trọng.\"\n\nNgôi nhà đã được một công ty môi giới bất động sản địa phương rao bán trong tuần này. Giá chào bán là 150.000 bảng Anh.\n\nDự án sắp tới của KD Building Concepts là xây dựng một ngôi nhà ở Hamburg, Đức.","qs":[{"n":186,"q":"What is mentioned on the schedule?","qvi":"Điều gì được đề cập trong lịch trình?","opts":["Free breakfast is available for conference participants.","The conference is five days long.","A keynote address will be delivered at the end of the first day.","A featured speaker has been replaced."],"ans":"A","xp":"Chi tiết. Lịch trình: \"7:00 A.M. to 8:00 A.M. Morning Social: Complimentary omelets, pastries, coffee, tea\" → \"complimentary\" = miễn phí; trứng, bánh ngọt, cà phê buổi sáng = bữa sáng miễn phí → (A).\n(B) Hội nghị diễn ra 23–25 tháng 10 = 3 ngày, không phải 5 (\"Fifth\" là lần thứ năm). (C), (D) không được nhắc đến.\n(A) Bữa sáng miễn phí dành cho người tham dự hội nghị.\n(B) Hội nghị kéo dài năm ngày.\n(C) Bài phát biểu chính sẽ diễn ra vào cuối ngày đầu tiên.\n(D) Một diễn giả nổi bật đã bị thay thế."},{"n":187,"q":"According to the schedule, what will happen at 10:30 A.M.?","qvi":"Theo lịch trình, điều gì sẽ diễn ra lúc 10:30 sáng?","opts":["A writer will give a presentation.","Coffee will be served in the lobby.","Lunch tickets will be sold in room 10.","A revised schedule will be distributed."],"ans":"A","xp":"Chi tiết. Lịch trình: \"10:30 A.M. to noon – Claire Song, business columnist and best-selling author – Room 10\" → Claire Song là nhà báo chuyên mục và tác giả sách bán chạy (= a writer), cô sẽ trình bày → (A).\n(B) Cà phê được phục vụ lúc 7–8 giờ ở Mezzanine. (C) Phòng 10 là nơi Claire Song nói chuyện; vé ăn trưa không được nói là bán ở đó. (D) Không nhắc đến.\n(A) Một nhà văn sẽ có bài thuyết trình.\n(B) Cà phê sẽ được phục vụ ở sảnh.\n(C) Vé ăn trưa sẽ được bán ở phòng 10.\n(D) Một lịch trình sửa đổi sẽ được phát."},{"n":188,"q":"What can be concluded about Mr. Dzik?","qvi":"Có thể kết luận gì về ông Dzik?","opts":["He wants a marketing video to be shortened.","He has asked Mr. Kalwar for a new marketing plan.","He organized a conference in London.","He hired Mr. Secada's firm for a project."],"ans":"D","xp":"Suy luận, liên kết 2 đoạn. E-mail của ông Dzik: \"Attached is a link to the video created for us by Grindstone Marketing Group.\" Lịch trình: \"Marcos Secada, founder and CEO, Grindstone Marketing Group\". → Công ty của ông Secada đã làm video cho công ty ông Dzik, tức ông Dzik đã thuê công ty của ông Secada cho một dự án → (D).\n(A) Ông nói video \"looks great as is\" (đẹp như hiện tại) → không muốn cắt ngắn. (B) Ông cảm ơn Kalwar đã giúp kế hoạch marketing, không yêu cầu kế hoạch mới. (C) Không có thông tin.\n(A) Ông muốn video marketing được rút ngắn.\n(B) Ông đã yêu cầu ông Kalwar làm một kế hoạch marketing mới.\n(C) Ông đã tổ chức một hội nghị ở London.\n(D) Ông đã thuê công ty của ông Secada cho một dự án."},{"n":189,"q":"What is suggested about Mr. Kalwar?","qvi":"Điều gì được ngụ ý về ông Kalwar?","opts":["He is a videographer.","He works in Germany.","He is planning to buy a house in Sheffield.","He specializes in construction materials."],"ans":"B","xp":"Suy luận, liên kết 2 đoạn. E-mail gửi ông Kalwar: \"our next construction project will be a home just a couple of kilometres from your office building!\" Bài báo: \"Next on the horizon for KD Building Concepts is the construction of a home in Hamburg, Germany.\" → Dự án tiếp theo ở Hamburg, Đức và chỉ cách văn phòng ông Kalwar vài cây số → ông Kalwar làm việc ở Đức (bài báo cũng nói công ty có văn phòng ở Đức) → (B).\n(A) Video do Grindstone làm, không phải ông. (C), (D) Không có thông tin.\n(A) Ông là người quay phim.\n(B) Ông làm việc ở Đức.\n(C) Ông đang định mua một căn nhà ở Sheffield.\n(D) Ông chuyên về vật liệu xây dựng."},{"n":190,"q":"What does the article indicate about the house created with a 3-D printer?","qvi":"Bài báo cho biết điều gì về ngôi nhà được tạo bằng máy in 3-D?","opts":["It cost £150,000 to build.","It was finished in two months.","It will be landscaped next week.","Its bedrooms are all the same size."],"ans":"B","xp":"Chi tiết. Bài báo: \"In just two months, the fully landscaped house with two bedrooms and two bathrooms was ready for market.\" → nhà hoàn thành trong hai tháng → (B).\n(A) Bẫy: £150,000 là giá chào bán (asking price), không phải chi phí xây dựng. (C) Nhà đã \"fully landscaped\" (có cảnh quan hoàn chỉnh) rồi. (D) Không nhắc đến kích thước phòng ngủ.\n(A) Xây nó tốn 150.000 bảng Anh.\n(B) Nó được hoàn thành trong hai tháng.\n(C) Nó sẽ được làm cảnh quan vào tuần tới.\n(D) Các phòng ngủ của nó đều cùng kích thước."}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following job posting, flyer, and article.","passages":["<h4>Gallery manager at Richard Lahiri Gallery in Cromwood</h4>\n<p>Applicants for this full-time position must have experience in retail art with an established history of successfully attracting patrons interested in purchasing original works of art. Experience managing a social media account is also desired. The position will be primarily on-site; however, some remote hours can be scheduled. Candidates must be available to start work on or before April 1. Qualified applicants should contact gallery director Richard Lahiri at rlahiri@richardlahirigallery.com.</p>","<h3>Summer Scene Arts Program</h3>\n<p>Starting on May 1, five art galleries in Cromwood will be hosting open houses every Friday from May through August. Come enjoy live music, refreshments, artist talks, and more on the Cromwood boardwalk. Activities start at 4:00 P.M. and continue until 9:30 P.M., rain or shine. Participating galleries are listed below.</p>\n<p><b>Rita Blake Art • Siitva Gallery • Richard Lahiri Gallery<br>Patricia Dolivo Painting • Ashland Pottery and Crafts</b></p>\n<p>Funded by the Cromwood City Council and Regents Bank</p>","<h3>Summer Activities in Middleton County</h3>\n<p>Compiled by Lisa Yu-Seaver</p>\n<h4>Cromwood Art Nights</h4>\n<p>Residents of Elmhurst, Melbridge, and Cromwood are invited to explore the local art scene in Cromwood this summer. The five galleries on the boardwalk overlooking the Wye River are holding special events each Friday as part of the Summer Scene Arts Program. This Friday, Richard Lahiri and his gallery manager, Geetu Gelang, will use a giant screen to demonstrate software for creating virtual art. The event will also feature craft vendors, food trucks, and live music. See www.cromwood.gov/things-to-do for more information.</p>\n<h4>Movies in Brady Park</h4>\n<p>The popular summer movie series in Herrontown returns on June 16! Each Saturday evening, a classic film will be projected on Brady Park's Grand Lawn. Bring your picnic basket and a blanket and get comfortable! The schedule of films is available at www.bradypark.org/activities.</p>"],"vi":"[Tin tuyển dụng]\nQuản lý phòng tranh tại Phòng tranh Richard Lahiri ở Cromwood\n\nỨng viên cho vị trí toàn thời gian này phải có kinh nghiệm bán lẻ nghệ thuật với thành tích đã được khẳng định trong việc thu hút thành công những khách hàng quan tâm đến việc mua các tác phẩm nghệ thuật gốc. Có kinh nghiệm quản lý tài khoản mạng xã hội cũng là một điểm mong muốn. Vị trí này chủ yếu làm việc tại chỗ; tuy nhiên, có thể sắp xếp một số giờ làm từ xa. Ứng viên phải có thể bắt đầu làm việc vào hoặc trước ngày 1 tháng 4. Ứng viên đủ điều kiện vui lòng liên hệ giám đốc phòng tranh Richard Lahiri qua rlahiri@richardlahirigallery.com.\n\n[Tờ rơi]\nChương trình Nghệ thuật Summer Scene\n\nBắt đầu từ ngày 1 tháng 5, năm phòng tranh ở Cromwood sẽ tổ chức các buổi mở cửa tự do vào mỗi thứ Sáu từ tháng 5 đến tháng 8. Hãy đến thưởng thức nhạc sống, đồ ăn nhẹ, các buổi nói chuyện với nghệ sĩ và nhiều hoạt động khác trên lối đi lát gỗ ven sông Cromwood. Các hoạt động bắt đầu lúc 4 giờ chiều và kéo dài đến 9 giờ 30 tối, dù mưa hay nắng. Các phòng tranh tham gia được liệt kê dưới đây.\n\nRita Blake Art • Siitva Gallery • Richard Lahiri Gallery • Patricia Dolivo Painting • Ashland Pottery and Crafts\n\nĐược tài trợ bởi Hội đồng Thành phố Cromwood và Ngân hàng Regents\n\n[Bài báo]\nCác hoạt động mùa hè ở Quận Middleton\nTổng hợp bởi Lisa Yu-Seaver\n\nĐêm Nghệ thuật Cromwood\nCư dân Elmhurst, Melbridge và Cromwood được mời khám phá không gian nghệ thuật địa phương ở Cromwood mùa hè này. Năm phòng tranh trên lối đi lát gỗ nhìn ra sông Wye đang tổ chức các sự kiện đặc biệt vào mỗi thứ Sáu trong khuôn khổ Chương trình Nghệ thuật Summer Scene. Thứ Sáu này, Richard Lahiri và quản lý phòng tranh của ông, Geetu Gelang, sẽ dùng một màn hình khổng lồ để trình diễn phần mềm tạo nghệ thuật ảo. Sự kiện cũng sẽ có các gian hàng thủ công, xe bán đồ ăn và nhạc sống. Xem www.cromwood.gov/things-to-do để biết thêm thông tin.\n\nChiếu phim ở Công viên Brady\nLoạt phim mùa hè được yêu thích ở Herrontown sẽ trở lại vào ngày 16 tháng 6! Mỗi tối thứ Bảy, một bộ phim kinh điển sẽ được chiếu trên Bãi cỏ Lớn của Công viên Brady. Hãy mang theo giỏ đồ ăn dã ngoại và một tấm chăn để ngồi thoải mái! Lịch chiếu phim có tại www.bradypark.org/activities.","qs":[{"n":191,"q":"What is stated in the job posting about the managerial position?","qvi":"Tin tuyển dụng nói gì về vị trí quản lý?","opts":["It is fully on-site.","It is Mr. Lahiri's current job.","It requires sales experience.","It will be part-time until April 1."],"ans":"C","xp":"Chi tiết. Tin tuyển dụng: \"Applicants ... must have experience in retail art with an established history of successfully attracting patrons interested in purchasing original works of art.\" → phải có kinh nghiệm bán lẻ, thu hút khách mua tranh = kinh nghiệm bán hàng (sales experience) → (C).\n(A) Sai: \"primarily on-site; however, some remote hours can be scheduled\" → chủ yếu tại chỗ, vẫn có giờ làm từ xa. (B) Ông Lahiri là giám đốc phòng tranh (gallery director). (D) Đây là vị trí toàn thời gian (full-time); April 1 là hạn bắt đầu làm.\n(A) Vị trí này làm việc hoàn toàn tại chỗ.\n(B) Đó là công việc hiện tại của ông Lahiri.\n(C) Vị trí này đòi hỏi kinh nghiệm bán hàng.\n(D) Vị trí này sẽ là bán thời gian đến ngày 1 tháng 4."},{"n":192,"q":"According to the flyer, what will happen on May 1?","qvi":"Theo tờ rơi, điều gì sẽ diễn ra vào ngày 1 tháng 5?","opts":["A public arts program will begin.","A city council meeting will take place.","A new art gallery will hold a grand opening.","Regents Bank will be closed for the day."],"ans":"A","xp":"Chi tiết. Tờ rơi có tiêu đề \"Summer Scene Arts Program\" và viết: \"Starting on May 1, five art galleries in Cromwood will be hosting open houses every Friday...\" → chương trình nghệ thuật mở cửa cho công chúng bắt đầu từ 1/5 → (A).\n(B), (D) Hội đồng thành phố và ngân hàng Regents chỉ là nhà tài trợ. (C) Đây là các buổi mở cửa tự do (open houses) của 5 phòng tranh có sẵn, không phải khai trương phòng tranh mới.\n(A) Một chương trình nghệ thuật công cộng sẽ bắt đầu.\n(B) Một cuộc họp hội đồng thành phố sẽ diễn ra.\n(C) Một phòng tranh mới sẽ tổ chức lễ khai trương.\n(D) Ngân hàng Regents sẽ đóng cửa cả ngày."},{"n":193,"q":"What is suggested about Ashland Pottery and Crafts?","qvi":"Điều gì được ngụ ý về Ashland Pottery and Crafts?","opts":["It is located near the Wye River.","It specializes in virtual art.","It hosts pottery workshops every Saturday.","It is sponsoring a summer movie series."],"ans":"A","xp":"Suy luận, liên kết 2 đoạn. Tờ rơi liệt kê Ashland Pottery and Crafts là một trong năm phòng tranh tham gia chương trình Summer Scene. Bài báo: \"The five galleries on the boardwalk overlooking the Wye River are holding special events each Friday as part of the Summer Scene Arts Program.\" → Năm phòng tranh này nằm trên lối đi nhìn ra sông Wye → Ashland ở gần sông Wye → (A).\n(B) Phần mềm nghệ thuật ảo là do Richard Lahiri trình diễn. (C) Sự kiện vào thứ Sáu; thứ Bảy là chiếu phim ở công viên Brady. (D) Không có thông tin về nhà tài trợ loạt phim.\n(A) Nó nằm gần sông Wye.\n(B) Nó chuyên về nghệ thuật ảo.\n(C) Nó tổ chức các buổi workshop làm gốm mỗi thứ Bảy.\n(D) Nó đang tài trợ cho một loạt phim mùa hè."},{"n":194,"q":"What is suggested about Geetu Gelang?","qvi":"Điều gì được ngụ ý về Geetu Gelang?","opts":["She is a local musician.","She will be selling her crafts on May 1.","She plans to start a social media account.","She was recently hired by the Richard Lahiri Gallery."],"ans":"D","xp":"Suy luận, liên kết 2 đoạn. Tin tuyển dụng đăng tuyển \"Gallery manager at Richard Lahiri Gallery\", yêu cầu bắt đầu làm \"on or before April 1\". Bài báo (mùa hè): \"Richard Lahiri and his gallery manager, Geetu Gelang, will use a giant screen...\" → Geetu Gelang hiện là quản lý phòng tranh, tức cô chính là người được tuyển gần đây cho vị trí trong tin tuyển dụng → (D).\n(A) Nhạc sống là hoạt động của sự kiện, không nói cô là nhạc sĩ. (B), (C) Không có thông tin.\n(A) Cô ấy là một nhạc sĩ địa phương.\n(B) Cô ấy sẽ bán đồ thủ công của mình vào ngày 1 tháng 5.\n(C) Cô ấy dự định lập một tài khoản mạng xã hội.\n(D) Cô ấy mới được Phòng tranh Richard Lahiri tuyển dụng."},{"n":195,"q":"According to the article, where is Brady Park located?","qvi":"Theo bài báo, Công viên Brady nằm ở đâu?","opts":["In Cromwood","In Elmhurst","In Herrontown","In Melbridge"],"ans":"C","xp":"Chi tiết. Bài báo, mục Movies in Brady Park: \"The popular summer movie series in Herrontown returns on June 16! Each Saturday evening, a classic film will be projected on Brady Park's Grand Lawn.\" → loạt phim diễn ra ở Herrontown, chiếu tại công viên Brady → công viên Brady ở Herrontown → (C).\n(A), (B), (D) Cromwood, Elmhurst, Melbridge được nhắc trong mục Cromwood Art Nights, không liên quan đến công viên Brady.\n(A) Ở Cromwood\n(B) Ở Elmhurst\n(C) Ở Herrontown\n(D) Ở Melbridge"}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following article, memo, and policy.","passages":["<h3>Senano Designs Buys Gendalla in $60 Million Deal</h3>\n<p>LOS ANGELES (March 20)—Fashion powerhouse Senano Designs announced on Wednesday that it had acquired Gendalla, an up-and-coming luxury brand. The acquisition is part of Senano's plan to supplement its clothing products with a line of designer watches. Over the next two years, the company has further plans to expand its offerings to include fragrances and luggage. Lina Pacheco, Senano's chief executive officer, said that such expansion is necessary to keep up and compete with other international fashion houses. Although based in Los Angeles, in recent years Senano has opened offices in Philadelphia, Chicago, and Miami. Ms. Pacheco says she was unfamiliar with Gendalla products until a year ago, when she saw one of their ads in an automobile magazine. \"The products have a distinctive, modern style,\" Ms. Pacheco said, \"which will go well with Senano's trendsetting clothes.\"</p>","<h4>MEMO</h4>\n<div class=\"hdr\"><p><b>From:</b> Oscar Johansen, Accounting department</p><p><b>To:</b> All Gendalla employees</p><p><b>Date:</b> March 22</p><p><b>Subject:</b> Travel expense policy</p><p><b>Attachment:</b> Policy</p></div>\n<p>I have attached a copy of Senano's policy on travel expenses, which will go into effect when we officially become employees of Senano on March 31.</p>\n<p>Note that Senano's policy is more restrictive than Gendalla's policy in several ways. For example, employees will no longer have one month to submit expense reports. However, the new policy will make some processes much easier: specifically, Senano's requirements for submitting expenses under $50 are simpler than those under current Gendalla policy.</p>\n<p>Carlie Dawson, an accounting director who works at Senano's headquarters, will come to our New York office to lead an information session about this and other policy-related changes on Thursday, March 28, at 2:00 P.M. I strongly encourage you to attend.</p>","<h3>Senano Designs</h3>\n<h4>Travel Expense Policy</h4>\n<ul>\n<li>To be reimbursed for work-related travel, employees must submit a travel request at least two weeks before a trip, listing the reason for travel and estimating all expenses.</li>\n<li>Original receipts must be submitted for expenses above $50. Any expenses below that do not require the submission of original receipts.</li>\n<li>All receipts and expense reports must be submitted within three weeks after a trip is completed. Expenses submitted after this time will require the approval of the department head.</li>\n</ul>\n<p>Page 1</p>"],"vi":"[Bài báo]\nSenano Designs mua lại Gendalla trong thương vụ 60 triệu đô\n\nLOS ANGELES (20 tháng 3) – Hãng thời trang hùng mạnh Senano Designs hôm thứ Tư thông báo đã mua lại Gendalla, một thương hiệu xa xỉ đang lên. Thương vụ mua lại này nằm trong kế hoạch của Senano nhằm bổ sung cho các sản phẩm quần áo của mình một dòng đồng hồ thiết kế cao cấp. Trong hai năm tới, công ty còn có kế hoạch mở rộng các sản phẩm của mình sang nước hoa và vali hành lý. Lina Pacheco, giám đốc điều hành của Senano, cho biết việc mở rộng như vậy là cần thiết để theo kịp và cạnh tranh với các hãng thời trang quốc tế khác. Mặc dù có trụ sở tại Los Angeles, trong những năm gần đây Senano đã mở văn phòng ở Philadelphia, Chicago và Miami. Bà Pacheco cho biết bà không hề biết đến các sản phẩm của Gendalla cho đến một năm trước, khi bà nhìn thấy một quảng cáo của họ trên một tạp chí ô tô. \"Các sản phẩm có phong cách hiện đại, khác biệt,\" bà Pacheco nói, \"và sẽ rất hợp với quần áo dẫn đầu xu hướng của Senano.\"\n\n[Bản ghi nhớ]\nNgười gửi: Oscar Johansen, Phòng Kế toán\nNgười nhận: Toàn thể nhân viên Gendalla\nNgày: 22 tháng 3\nTiêu đề: Chính sách chi phí công tác\nTệp đính kèm: Chính sách\n\nTôi đã đính kèm một bản chính sách về chi phí công tác của Senano, chính sách này sẽ có hiệu lực khi chúng ta chính thức trở thành nhân viên của Senano vào ngày 31 tháng 3.\n\nXin lưu ý rằng chính sách của Senano chặt chẽ hơn chính sách của Gendalla ở một số điểm. Ví dụ, nhân viên sẽ không còn được một tháng để nộp báo cáo chi phí nữa. Tuy nhiên, chính sách mới sẽ khiến một số quy trình dễ dàng hơn nhiều: cụ thể, yêu cầu của Senano đối với việc nộp các khoản chi dưới 50 đô đơn giản hơn so với chính sách hiện tại của Gendalla.\n\nCarlie Dawson, một giám đốc kế toán làm việc tại trụ sở chính của Senano, sẽ đến văn phòng New York của chúng ta để chủ trì một buổi thông tin về thay đổi này và các thay đổi chính sách khác vào thứ Năm, ngày 28 tháng 3, lúc 2 giờ chiều. Tôi rất khuyến khích các bạn tham dự.\n\n[Chính sách]\nSenano Designs\nChính sách chi phí công tác\n\n• Để được hoàn tiền cho chuyến đi công tác, nhân viên phải nộp đơn đề nghị đi công tác ít nhất hai tuần trước chuyến đi, nêu rõ lý do đi và ước tính toàn bộ chi phí.\n• Phải nộp hóa đơn gốc cho các khoản chi trên 50 đô. Mọi khoản chi dưới mức đó không cần nộp hóa đơn gốc.\n• Tất cả hóa đơn và báo cáo chi phí phải được nộp trong vòng ba tuần sau khi kết thúc chuyến đi. Các khoản chi nộp sau thời hạn này sẽ cần sự phê duyệt của trưởng phòng.\n\nTrang 1","qs":[{"n":196,"q":"What does Gendalla mainly produce?","qvi":"Gendalla chủ yếu sản xuất gì?","opts":["Watches","Luggage","Clothing","Fragrances"],"ans":"A","xp":"Suy luận/chi tiết. Bài báo: \"The acquisition is part of Senano's plan to supplement its clothing products with a line of designer watches.\" → Senano mua Gendalla để bổ sung dòng đồng hồ → Gendalla làm đồng hồ → (A).\n(C) Quần áo là sản phẩm của Senano. (B), (D) Vali và nước hoa là kế hoạch mở rộng trong hai năm tới của Senano (\"further plans to expand its offerings to include fragrances and luggage\").\n(A) Đồng hồ\n(B) Vali hành lý\n(C) Quần áo\n(D) Nước hoa"},{"n":197,"q":"According to the article, why is Senano Designs acquiring Gendalla?","qvi":"Theo bài báo, vì sao Senano Designs mua lại Gendalla?","opts":["To sell products at a lower price","To expand its social media presence","To offer a more diverse range of products","To address declining sales in some cities"],"ans":"C","xp":"Chi tiết. Bài báo: \"The acquisition is part of Senano's plan to supplement its clothing products with a line of designer watches.\" và \"such expansion is necessary to keep up and compete...\" → bổ sung thêm dòng đồng hồ vào quần áo = cung cấp dải sản phẩm đa dạng hơn → (C).\n(A), (B), (D) không được nhắc đến (bài nói Senano mở thêm văn phòng, không nói doanh số giảm).\n(A) Để bán sản phẩm với giá thấp hơn\n(B) Để mở rộng sự hiện diện trên mạng xã hội\n(C) Để cung cấp dải sản phẩm đa dạng hơn\n(D) Để giải quyết doanh số sụt giảm ở một số thành phố"},{"n":198,"q":"What are Gendalla's employees invited to do on March 28?","qvi":"Nhân viên Gendalla được mời làm gì vào ngày 28 tháng 3?","opts":["Suggest changes to a travel policy","Attend a meeting in the afternoon","Tour Senano's corporate headquarters","Make an appointment with an accountant"],"ans":"B","xp":"Chi tiết. Bản ghi nhớ: \"Carlie Dawson ... will come to our New York office to lead an information session ... on Thursday, March 28, at 2:00 P.M. I strongly encourage you to attend.\" → tham dự buổi thông tin (= a meeting) lúc 2 giờ chiều (= in the afternoon) → (B).\n(C) Bẫy: bà Dawson làm ở trụ sở chính nhưng sẽ đến văn phòng New York; nhân viên không đi tham quan trụ sở. (A), (D) không nhắc đến.\n(A) Đề xuất thay đổi chính sách công tác\n(B) Tham dự một cuộc họp vào buổi chiều\n(C) Tham quan trụ sở chính của Senano\n(D) Đặt lịch hẹn với một nhân viên kế toán"},{"n":199,"q":"Where is Ms. Dawson's office?","qvi":"Văn phòng của bà Dawson ở đâu?","opts":["In New York","In Chicago","In Philadelphia","In Los Angeles"],"ans":"D","xp":"Suy luận, liên kết 2 đoạn. Bản ghi nhớ: \"Carlie Dawson, an accounting director who works at Senano's headquarters...\" Bài báo: \"Although based in Los Angeles, in recent years Senano has opened offices in Philadelphia, Chicago, and Miami.\" → trụ sở chính của Senano ở Los Angeles → bà Dawson làm việc ở Los Angeles → (D).\n(A) New York là văn phòng của Gendalla, nơi bà sẽ đến. (B), (C) Chicago, Philadelphia là văn phòng chi nhánh của Senano, không phải trụ sở.\n(A) Ở New York\n(B) Ở Chicago\n(C) Ở Philadelphia\n(D) Ở Los Angeles"},{"n":200,"q":"How is Gendalla's current travel expense policy likely different from Senano's?","qvi":"Chính sách chi phí công tác hiện tại của Gendalla có lẽ khác với của Senano như thế nào?","opts":["A receipt must be submitted for every expense.","Preapproval must be obtained for expenses over $50.","The expense report must be signed by a manager.","Employees can submit their expense reports jointly."],"ans":"A","xp":"Suy luận, liên kết 2 đoạn. Bản ghi nhớ: \"Senano's requirements for submitting expenses under $50 are simpler than those under current Gendalla policy.\" Chính sách của Senano: \"Original receipts must be submitted for expenses above $50. Any expenses below that do not require the submission of original receipts.\" → Với Senano, khoản dưới 50 đô không cần hóa đơn; quy trình này \"đơn giản hơn\" của Gendalla → nghĩa là ở Gendalla hiện tại, khoản nào (kể cả dưới 50 đô) cũng phải nộp hóa đơn → (A).\n(B), (C), (D) không có căn cứ trong các văn bản.\n(A) Phải nộp hóa đơn cho mọi khoản chi.\n(B) Phải được phê duyệt trước cho các khoản chi trên 50 đô.\n(C) Báo cáo chi phí phải có chữ ký của quản lý.\n(D) Nhân viên có thể nộp chung báo cáo chi phí."}]}]}};
